  `titulo` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `enunciado_md` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `verificacao_sql` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'SELECT que roda no banco do SISTEMA (tenant da escola); >0 linhas = ok',
  `params_json` varchar(1000) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mensagem_ok` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mensagem_falha` varchar(300) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `ordem` smallint unsigned NOT NULL DEFAULT '0',
  `ativo` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_uni_pratica_slug` (`slug`),
  KEY `idx_uni_pratica_capsula` (`capsula_id`),
  CONSTRAINT `fk_uni_pratica_capsula` FOREIGN KEY (`capsula_id`) REFERENCES `uni_capsula` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
