INSERT INTO `uni_ativo` VALUES (1,3,'imagem','scripts/capturas/anterior/registrar-romaneio-de-campo.png',NULL,NULL,NULL,'3d3095dd0a29dc3298a1cb4bf6ae139a8683f4ba460d7724c1af7694eb17b437','desatualizado',0,'2026-07-26 17:22:06','2026-07-26 17:22:06'),(2,8,'imagem','scripts/capturas/anterior/receber-uma-compra.png',NULL,NULL,NULL,'dc13ea8a464df05e01ace695a299ee8595c3d7db3688fdb42d6676fd270e8fa5','desatualizado',0,'2026-07-26 17:22:06','2026-07-26 17:22:06'),(3,1,'imagem','scripts/capturas/anterior/conferir-custo-realizado-da-safra.png',NULL,NULL,NULL,'5bafc39f758abed341ca779ff6ccc6b7580ff8c04db229a1dc8ccf724d2c0d20','desatualizado',0,'2026-07-26 17:22:06','2026-07-26 17:22:06'),(4,9,'imagem','scripts/capturas/anterior/dar-entrada-de-nota-no-estoque.png',NULL,NULL,NULL,'b451ec5e0b703ffda4474ce0ac2f7cbd10e11f606b3ec021eb0a0a69957e6fa9','desatualizado',0,'2026-07-26 17:22:06','2026-07-26 17:22:06'),(5,10,'imagem','scripts/capturas/anterior/fazer-saldo-inicial.png',NULL,NULL,NULL,'28d59fd2cbc434e00f50625bb13f2b9c6b6c75daeb90be834d1f5eced22a24cb','desatualizado',0,'2026-07-26 17:22:06','2026-07-26 17:22:06'),(6,4,'imagem','scripts/capturas/anterior/baixar-um-titulo.png',NULL,NULL,NULL,'f3abc157f41acfd96d95ab2d3c6ec17786b11dc07add294421ec3f1ed905aa2c','desatualizado',0,'2026-07-26 17:22:06','2026-07-26 17:22:06'),(7,5,'imagem','scripts/capturas/anterior/registrar-monitoramento-mip.png',NULL,NULL,NULL,'7fc8dd7469ebdac2021838734820dc80ed7c9503c0f18802841eb033a172e138','desatualizado',0,'2026-07-26 17:22:06','2026-07-26 17:22:06'),(8,6,'imagem','scripts/capturas/anterior/abrir-safra-e-confirmar-poda.png',NULL,NULL,NULL,'3d22eafa4fd7ee7ae3ff9c784a3b4cb159833331c43907199fc91fbfb389ea92','desatualizado',0,'2026-07-26 17:22:06','2026-07-26 17:22:06'),(9,7,'imagem','scripts/capturas/anterior/emitir-ordem-de-servico.png',NULL,NULL,NULL,'6617a5d8b0b73e1eefc12cfdccb6c2f4e872e25f9e1f8f82136075de0bb7a5c2','desatualizado',0,'2026-07-26 17:22:06','2026-07-26 17:22:06'),(10,2,'imagem','scripts/capturas/anterior/finalizar-apontamento.png',NULL,NULL,NULL,'2ff2140130869e110fc58c288d5ffcb3135d8b1d319c777ff2ce125f2e3904e0','desatualizado',0,'2026-07-26 17:22:06','2026-07-26 17:22:06');
