/*!40000 ALTER TABLE `uni_capsula` DISABLE KEYS */;
INSERT INTO `uni_capsula` VALUES (1,NULL,'conferir-custo-realizado-da-safra','Conferir o custo realizado da safra','FAZER',NULL,'## Finalidade\nAqui você vê para onde o dinheiro da safra realmente foi: mão de obra, insumos e máquinas que já foram apontados e finalizados. É a foto do custo que já aconteceu, não do planejado.\n\n## Como fazer\n1. Abra **Custo Realizado** e selecione a safra e a fazenda.\n2. Leia o total e a quebra por categoria (mão de obra, insumos, máquinas).\n3. Se um custo esperado não aparece, verifique se o apontamento de origem foi **finalizado**.\n4. Compare com o planejado para enxergar o desvio.\n\n## Erros comuns\n- **Estranhar um custo faltando.** Quase sempre é um apontamento ainda \"iniciado\" lá atrás — finalize-o e o valor entra aqui.\n- **Comparar safras de tamanhos diferentes sem olhar o custo por hectare.** O total absoluto engana; use o custo por hectare para comparar de verdade.\n\n## Antes e depois\nAntes: Finalizar os apontamentos que geram o custo. Depois: Fechar a safra com o resultado consolidado.\n\n## Roteiro do vídeo\n- Abrir Custo Realizado com uma safra selecionada.\n- Narrar a leitura do total e da quebra por categoria.\n- Mostrar o caso \"custo faltando\" → voltar ao apontamento iniciado → finalizar → o valor aparece.','custos','conferir','safra','intermediario',140,'publicado','1.0','1.3',NULL,'conteudo@example.com',NULL,'2027-01-24',1,NULL,NULL,'2026-07-26 15:57:07','2026-07-26 17:23:28'),(2,NULL,'finalizar-apontamento','Finalizar um apontamento para o custo aparecer','FAZER',NULL,'## Finalidade\nO apontamento é o que transforma o trabalho do dia — pessoas, horas e insumos — em custo da safra. Enquanto ele fica \"iniciado\", nada disso entra na conta.\n\n## Como fazer\n1. Abra o apontamento iniciado na lista de **Apontamentos de Campo**.\n2. Confirme as pessoas, as horas trabalhadas e os insumos usados.\n3. Clique em **Finalizar** — este é o passo que gera o custo.\n4. Confira em **Custo Realizado** se o valor apareceu na safra.\n\n## Erros comuns\n- **Deixar iniciado e nunca finalizar.** O trabalho não vira custo e a Ordem de Serviço não fecha. Confira a lista de pendentes toda sexta-feira.\n- **Finalizar sem lançar os insumos.** O custo de mão de obra entra, mas o de produto fica de fora — o custo por hectare sai menor do que o real.\n\n## Antes e depois\nAntes: Emitir a Ordem de Serviço que autoriza o trabalho. Depois: Conferir o Custo Realizado da safra.\n\n## Roteiro do vídeo\n- Abrir a tela Apontamentos de Campo com um apontamento iniciado visível na lista.\n- Narrar: \"Todo apontamento nasce iniciado. Ele só vira custo quando a gente finaliza.\"\n- Abrir o apontamento, percorrer pessoas → horas → insumos.\n- Destacar o botão **Finalizar** antes de clicar; clicar.\n- Cortar para **Custo Realizado** mostrando a linha nova.','operacao-agricola','apontar','safra','iniciante',160,'publicado','1.0','1.3',NULL,'conteudo@example.com',NULL,'2027-01-24',1,NULL,NULL,'2026-07-26 15:57:07','2026-07-26 17:23:28'),(3,NULL,'registrar-romaneio-de-campo','Registrar um romaneio da carga que saiu do campo','FAZER',NULL,'## Finalidade\nO romaneio é a trilha do que saiu do campo: quanto pesou, de qual válvula veio e para onde foi. É o que liga cada carga à safra e, depois, ao registro de colheita.\n\n## Como fazer\n1. Abra **Romaneios de Colheita** e clique em **+ Nova carga**.\n2. Preencha o número do romaneio, a válvula e o peso em kg (maior que zero).\n3. Escolha a **safra** da válvula (ela aparece na lista só depois de escolher a válvula) — é o que rastreia o lote.\n4. Se quiser, informe a classificação, o destino e o registro de colheita ligado.\n5. Clique em **Salvar** — este é o passo que **registra a carga** e soma o peso no total do dia.\n\n## Erros comuns\n- **Peso zero ou em branco.** O sistema não salva: romaneio, válvula e peso maior que zero são obrigatórios. Confira a balança antes de lançar.\n- **Escolher a safra antes da válvula.** A lista de safras só carrega depois que você seleciona a válvula. Selecione a válvula primeiro e a safra certa aparece.\n- **Deixar a carga sem safra.** Sem a safra, o lote fica sem rastreabilidade e não aparece corretamente na trilha por safra. Escolha a safra da válvula sempre que houver.\n\n## Antes e depois\nAntes: Colher e pesar a carga no campo. Depois: Conferir o Custo Realizado da safra com a produção já lançada.\n\n## Roteiro do vídeo\n- Abrir Romaneios de Colheita mostrando o total de kg do dia.\n- Clicar em + Nova carga e abrir o formulário.\n- Preencher romaneio, válvula e peso; narrar que sem peso não salva.\n- Escolher a válvula e mostrar a lista de safras carregando em seguida.\n- Destacar o botão **Salvar** antes de clicar; clicar.\n- Mostrar a carga nova na tabela e o total de kg subindo.','colheita','registrar','safra','iniciante',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 16:19:28','2026-07-26 17:23:28'),(4,NULL,'baixar-um-titulo','Baixar um título para fechar o ciclo do dinheiro','FAZER',NULL,'## Finalidade\nBaixar um título é registrar que a conta foi paga — é o que fecha o ciclo do dinheiro e faz o valor sair do fluxo de caixa. Enquanto o título fica \"aberto\", ele continua contando como uma saída que ainda vai acontecer.\n\n## Como fazer\n1. Abra **Contas a Pagar** e localize o título em aberto que você pagou.\n2. Clique em **Baixar** na linha do título.\n3. Informe a data do pagamento e a forma de pagamento usada.\n4. Confirme a baixa — este é o passo que **quita o título e desconta o valor do fluxo de caixa**.\n5. Confira que o título mudou de \"aberto\" para \"pago\" na lista.\n\n## Erros comuns\n- **Baixar com a data errada.** O valor sai do fluxo de caixa no dia errado e distorce o saldo do período. Sempre use a data real do pagamento, não a de hoje.\n- **Baixar o título errado.** Confira descrição e valor antes de confirmar — a baixa quita aquele lançamento específico.\n- **Baixar por engano.** Se errou, use **Estornar baixa** para o título voltar a ficar aberto; não crie um lançamento novo para \"corrigir\".\n\n## Antes e depois\nAntes: Receber a compra que gerou o título a pagar. Depois: Conferir o fluxo de caixa com a saída já registrada.\n\n## Roteiro do vídeo\n- Abrir Contas a Pagar com um título em aberto visível na lista.\n- Narrar: \"Baixar um título é dizer que a conta foi paga — é isso que fecha o ciclo do dinheiro.\"\n- Clicar em **Baixar**, preencher data e forma de pagamento.\n- Confirmar e mostrar o título virando \"pago\".\n- Cortar para o fluxo de caixa mostrando a saída registrada.','financeiro','baixar','safra','iniciante',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 16:19:28','2026-07-26 17:23:28'),(5,NULL,'registrar-monitoramento-mip','Registrar um monitoramento de MIP para gerar o alerta','FAZER',NULL,'## Finalidade\nO monitoramento é o que transforma o que você viu no talhão — pragas, doenças, nível de infestação — em alerta fitossanitário para a equipe agir. Enquanto ele fica como rascunho, ninguém é avisado e o alerta não dispara.\n\n## Como fazer\n1. Abra **Monitoramento de MIP** e selecione a safra, a fazenda e o talhão que você percorreu.\n2. Lance o que encontrou: praga ou doença, nível de infestação e os pontos avaliados.\n3. Revise se cada ocorrência está com o alvo e o nível certos.\n4. Clique em **Concluir** para enviar o monitoramento — este é o passo que **gera o alerta fitossanitário**.\n5. Confira na lista se o monitoramento saiu de rascunho e ficou concluído.\n\n## Erros comuns\n- **Deixar como rascunho e nunca concluir.** O monitoramento fica só com você, o alerta não dispara e a equipe não fica sabendo da infestação. Confira seus rascunhos antes de sair do talhão.\n- **Concluir sem informar o nível de infestação.** O alerta até aparece, mas sem gravidade a equipe não sabe se é urgente — sempre registre o nível de cada ocorrência.\n- **Registrar no talhão errado.** O alerta chega para a área que não tem o problema. Confirme safra, fazenda e talhão antes de concluir.\n\n## Antes e depois\nAntes: Percorrer o talhão e avaliar os pontos de monitoramento. Depois: Emitir a Ordem de Serviço que atende ao alerta.\n\n## Roteiro do vídeo\n- Abrir a tela Monitoramento de MIP com um talhão selecionado.\n- Narrar: \"O que a gente vê no campo só vira alerta quando o monitoramento é concluído.\"\n- Lançar uma ocorrência: praga → nível de infestação → pontos.\n- Mostrar o estado \"rascunho\" e destacar que nele nenhum alerta dispara.\n- Clicar em **Concluir** e mostrar o monitoramento saindo de rascunho e o alerta aparecendo.','mip','monitorar','safra','iniciante',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 16:19:28','2026-07-26 17:23:28'),(6,NULL,'abrir-safra-e-confirmar-poda','Abrir a safra e confirmar a poda (o dia 0)','FAZER',NULL,'## Finalidade\nAbrir a safra do semestre e, válvula por válvula, confirmar que a poda terminou. A confirmação de poda é o dia 0 da safra: é dela que a fenologia começa a contar.\n\n## Como fazer\n1. Abra **Abertura de Safra** e clique em **+ Abrir safra do semestre** — a identificação (AAAA.S-NN) sai sozinha.\n2. Abra a safra recém-criada para ver as válvulas candidatas.\n3. Encontre a válvula com a situação **Pronta p/ confirmar** (todas as OS de poda concluídas e ao menos um apontamento de poda).\n4. Clique em **Confirmar poda** — este é o passo que **define o dia 0** (a data do último apontamento de poda) e libera a fenologia da válvula.\n5. Repita a confirmação para cada válvula que já teve a poda terminada.\n\n## Erros comuns\n- **Válvula sem variedade.** O sistema trava a confirmação: sem variedade não há cultura nem ciclo, e sem isso não dá para calcular o dia 0. Defina a variedade da válvula antes.\n- **Confirmar com OS de poda ainda aberta.** Enquanto houver OS de poda aberta ou em execução, o botão fica bloqueado. Conclua todas as OS de poda daquela válvula primeiro.\n- **Sem apontamento de poda.** A OS concluída não basta: é preciso ao menos um apontamento de poda, porque o dia 0 é a data desse apontamento. Sem ele, não há data de origem.\n- **Achar que dá para reconfirmar.** Depois de confirmada em uma safra ativa, a válvula fica travada para não duplicar safra. A confirmação não se desfaz por aqui.\n\n## Antes e depois\nAntes: Terminar as OS e os apontamentos de poda de cada válvula. Depois: Emitir as Ordens de Serviço dos tratos que vêm depois da poda.\n\n## Roteiro do vídeo\n- Abrir Abertura de Safra sem nenhuma safra ativa na lista.\n- Narrar: \"A safra do semestre agrupa as válvulas. Mas o relógio da fenologia só começa quando a gente confirma a poda de cada uma.\"\n- Clicar em + Abrir safra do semestre; mostrar a identificação gerada.\n- Abrir a safra e percorrer as válvulas: apontar uma Pendente (falta OS ou apontamento) e uma Pronta p/ confirmar.\n- Destacar o botão **Confirmar poda** e a data do último apontamento antes de clicar; clicar.\n- Mostrar a válvula virando Poda finalizada com o \"dia 0\" carimbado.','operacao-agricola','abrir','safra','intermediario',175,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 16:19:28','2026-07-26 17:23:28'),(7,NULL,'emitir-ordem-de-servico','Emitir uma Ordem de Serviço para o campo executar','FAZER',NULL,'## Finalidade\nNo VERO a Ordem de Serviço nasce da atividade planejada — uma para cada. Você não cria a OS solta: você planeja o trabalho no **Planejamento de Atividades** e a OS aparece numerada sozinha na fila.\n\n## Como fazer\n1. Abra **Agrícola → Planejamento de Atividades**.\n2. Clique em **Nova atividade** e descreva o trabalho: tipo (poda, raleio, trato…), válvula, data planejada e responsável.\n3. **Salve a atividade** — este é o passo que **emite a Ordem de Serviço** numerada, 1:1 com a atividade.\n4. Confira em **Ordens de Serviço** que a OS entrou na fila com o número gerado.\n5. Se precisar, imprima a OS de campo pelo botão de impressão da fila.\n\n## Erros comuns\n- **Procurar um botão de criar OS na tela de Ordens de Serviço.** Não existe: aquela tela é só a fila de leitura. Toda criação, edição e mudança de status acontece na atividade, e a OS acompanha sozinha.\n- **Mudar o status direto na OS.** O status vem da atividade. Para colocar em execução ou concluir, edite a atividade — a OS reflete na hora.\n- **Planejar a atividade na válvula errada.** A OS herda a válvula da atividade e é ali que o custo vai cair depois. Confira a válvula e a data antes de salvar.\n\n## Antes e depois\nAntes: Abrir a safra e confirmar a poda das válvulas (o dia 0). Depois: Finalizar o apontamento que executa a OS e gera o custo.\n\n## Roteiro do vídeo\n- Abrir Ordens de Serviço e mostrar a fila; narrar: \"Repare que aqui não tem botão de criar. A OS não nasce nesta tela.\"\n- Cortar para Planejamento de Atividades e clicar em Nova atividade.\n- Preencher tipo, válvula, data e responsável.\n- Destacar o botão **Salvar** antes de clicar; clicar.\n- Voltar para Ordens de Serviço e mostrar a OS nova, já numerada, no topo da fila.','operacao-agricola','planejar','safra','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 16:19:28','2026-07-26 17:23:28'),(8,NULL,'receber-uma-compra','Receber uma compra que chegou','FAZER',NULL,'## Finalidade\nReceber é o passo que confirma que a mercadoria do pedido chegou de verdade. Ao confirmar, o sistema dá entrada no estoque ao custo da nota e abre a conta a pagar para o fornecedor.\n\n## Como fazer\n1. Abra **Recebimentos** e escolha o pedido que chegou (só aparecem os pedidos **aprovados**).\n2. Confira item por item — produto, quantidade e custo — contra a nota que veio com a carga.\n3. Informe a data do recebimento e a condição de pagamento (à vista ou os dias parcelados, ex.: 45/90).\n4. Clique em **Confirmar recebimento** — este é o passo que **dá entrada no estoque e gera a conta a pagar**.\n5. Confira que a entrada apareceu no estoque com o custo certo.\n\n## Erros comuns\n- **Confirmar sem bater com a nota.** O custo errado entra no estoque e distorce o custo médio de todos os insumos. Confira quantidade e valor antes de clicar.\n- **Procurar um pedido que não está aprovado.** Só entra em Recebimentos o pedido já aprovado — se ele não aparece, volte e libere a aprovação primeiro.\n- **Digitar a condição de pagamento fora do padrão.** Texto solto não vira parcela; use um preset ou os dias separados por barra (ex.: 45/90), senão o vencimento sai errado.\n\n## Antes e depois\nAntes: Aprovar o pedido de compra que autoriza a mercadoria. Depois: Conferir a entrada de nota no estoque que essa confirmação gerou.\n\n## Roteiro do vídeo\n- Abrir a tela Recebimentos com um pedido aprovado esperando na lista.\n- Narrar: \"O pedido está aprovado, a carga chegou. Receber é confirmar o que chegou de verdade.\"\n- Percorrer os itens conferindo quantidade e custo contra a nota na mão.\n- Preencher data e condição de pagamento; destacar o botão **Confirmar recebimento** antes de clicar.\n- Cortar para o estoque mostrando a entrada nova e para o contas a pagar com a conta gerada.','compras','receber','safra','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 16:20:52','2026-07-26 17:23:28'),(9,NULL,'dar-entrada-de-nota-no-estoque','Dar entrada de nota no estoque','FAZER',NULL,'## Finalidade\nA entrada é o que coloca o produto dentro do estoque com o custo real da nota. É esse custo que forma o custo médio ponderado dos insumos — se a entrada está certa, o custo por hectare da safra fica certo.\n\n## Como fazer\n1. Abra **Entradas** e veja as entradas que já chegaram das compras confirmadas.\n2. Confira produto, quantidade e **custo unitário** de cada entrada contra a nota — é esse custo que alimenta o custo médio.\n3. Para uma nota que **não** veio de pedido de compra, vá em **Produtos**, ache o item e clique em **Movimentar**.\n4. Escolha o tipo **Entrada**, informe a quantidade, o custo real da nota e a validade (quando o produto controla lote) — este passo **cria o saldo e o custo do insumo**.\n5. Volte a Entradas e confirme que a movimentação apareceu com o custo certo.\n\n## Erros comuns\n- **Lançar entrada sem o custo da nota.** Sem o custo real, o custo médio do insumo fica errado e todo apontamento que usar esse produto sai barato demais.\n- **Esquecer a validade em produto que controla lote.** O sistema não deixa criar o saldo sem o lote — informe a validade na entrada, senão a movimentação nem grava.\n- **Lançar de novo uma entrada que já veio do recebimento.** A confirmação da compra já dá entrada sozinha; conferir em Entradas evita dobrar a quantidade.\n\n## Antes e depois\nAntes: Receber a compra que chegou (a confirmação já gera a entrada). Depois: O custo do insumo entra no custo médio e alimenta a conta da safra.\n\n## Roteiro do vídeo\n- Abrir Entradas mostrando uma movimentação recém-chegada de um recebimento.\n- Narrar: \"Toda entrada carrega o custo da nota. É esse custo que forma o custo médio do insumo.\"\n- Apontar produto, quantidade e custo unitário na linha.\n- Ir a Produtos, clicar em Movimentar, escolher Entrada e preencher quantidade, custo e validade.\n- Voltar a Entradas e mostrar a nova movimentação com o custo certo.','estoque','lancar','safra','iniciante',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 16:20:52','2026-07-26 17:23:28'),(10,NULL,'fazer-saldo-inicial','Fazer o saldo inicial do estoque','FAZER',NULL,'## Finalidade\nO saldo inicial é a foto do que já existe no almoxarifado no dia em que você começa a usar o sistema. Ele vira a base de tudo: o custo médio e todos os custos da safra saem desse número, então ele precisa nascer certo.\n\n## Como fazer\n1. Abra **Saldo Inicial** (a rota abre o modal na tela de Produtos).\n2. Informe a **data da implantação** e digite o **código do produto** — o sistema mostra o saldo atual que está no sistema.\n3. Vá até a prateleira e **conte o físico** antes de digitar qualquer coisa.\n4. Digite o **saldo correto** (o que existe de verdade) e, se for entrada, o custo unitário e a validade do lote quando o produto controla lote.\n5. Clique em **Corrigir saldo** — este passo **grava o saldo inicial pela diferença no estoque oficial**.\n\n## Erros comuns\n- **Confirmar sem contar o físico.** O saldo inicial é a base do custo médio de tudo; um número errado aqui contamina todo custo futuro e não tem um \"desfazer\" limpo — só um novo ajuste por cima, que deixa rastro. Confira antes de confirmar.\n- **Deixar o custo unitário em branco na entrada.** Quando o saldo correto é maior que o atual, o sistema faz uma entrada e exige o custo — sem ele o custo médio já nasce torto.\n- **Refazer o saldo várias vezes para \"acertar\".** Cada correção grava uma movimentação nova de implantação e embaralha o histórico. Conte uma vez, confira e confirme uma vez só.\n\n## Antes e depois\nAntes: Contar fisicamente o que há no almoxarifado no dia da virada. Depois: Dar entrada das notas novas, agora que a base já está montada.\n\n## Roteiro do vídeo\n- Abrir o modal Saldo Inicial pela rota de implantação.\n- Narrar: \"Este é o número que vira a base de tudo. Não tem desfazer limpo — então conta antes.\"\n- Digitar a data e o código; mostrar o saldo atual aparecendo.\n- Mostrar a contagem na prateleira, digitar o saldo correto e o custo.\n- Destacar o botão **Corrigir saldo** antes de clicar; mostrar a mensagem de saldo corrigido e custo médio atualizado.','estoque','implantar','safra','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 16:20:52','2026-07-26 17:23:28'),(11,NULL,'confirmar-entrada-da-colheita-no-estoque','Confirmar a entrada da colheita no estoque (gerar o lote)','FAZER',NULL,'## Finalidade\nRegistrar a colheita diz quanto foi produzido; confirmar a entrada no estoque transforma esses kg num lote real, valorizado. O lote entra a custo provisório — a média do custeio acumulado da safra dividida pelos kg colhidos — e é revalorizado no fechamento. É o que liga a produção do campo ao estoque de fruta pronta para comercializar.\n\n## Como fazer\n1. Na lista de **Colheita**, ache o registro já salvo da válvula.\n2. Clique em **Confirmar entrada no estoque** — este é o passo que cria o lote e dá entrada nos kg colhidos.\n3. Leia a mensagem: ela mostra o código do lote, os kg e o custo provisório por kg.\n4. Se precisar corrigir, use **Estornar** para devolver o saldo e marcar o lote como estornado; o registro de colheita permanece.\n\n## Erros comuns\n- **Confirmar duas vezes a mesma colheita.** Se já existe entrada ativa, o sistema avisa e nada é duplicado — mostra o lote que já existia. Não force uma segunda entrada.\n- **Confirmar com a safra fechada no custeio.** Se o período está fechado, a entrada é bloqueada. Reabra a safra em Custos → Fechamento de Safra e tente de novo.\n- **Estranhar o custo \"provisório\".** O custo por kg da entrada é uma média provisória; o valor definitivo sai na revalorização do fechamento. Não trate esse número como final.\n\n## Antes e depois\nAntes: Registrar a colheita da válvula com a classificação. Depois: Conferir o Custo Realizado da safra com a produção já no estoque.\n\n## Roteiro do vídeo\n- Abrir Colheita com um registro salvo sem entrada.\n- Clicar em **Confirmar entrada no estoque**.\n- Ler em voz alta a mensagem com lote, kg e custo provisório.\n- Mostrar o lote COLH- aparecendo no estoque.\n- Demonstrar o **Estornar** devolvendo o saldo e mantendo a colheita.','colheita','confirmar','safra','intermediario',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(12,NULL,'registrar-colheita-com-classificacao','Registrar a colheita da válvula com a classificação de qualidade','FAZER',NULL,'## Finalidade\nO registro de colheita fecha a produção de uma válvula numa safra: quantos kg saíram e como se dividem por qualidade (Premium, CAT 1 a 3, Perdidos). Os kg totais vêm de kg/ha × área da válvula, os kg de cada categoria de kg total × percentual, e o faturamento de kg × preço. É a base da comercialização e do resultado da safra.\n\n## Como fazer\n1. Abra **Colheita** e clique em **+ Nova colheita** (ou em Finalizar, para completar uma já iniciada).\n2. Informe a **data**, a **válvula** (setor) e a **safra** — os três são obrigatórios.\n3. Preencha os kg previstos e realizados da produção.\n4. Distribua os **percentuais por categoria** em cada momento (previsto e realizado) e os preços — a soma dos percentuais de um momento não pode passar de 100%.\n5. Clique em **Salvar colheita** — este é o passo que grava a produção e o faturamento estimado da válvula.\n\n## Erros comuns\n- **Somar mais de 100% num momento.** Se os percentuais de qualidade de previsto (ou de realizado) passam de 100%, o sistema recusa e mostra a soma. Ajuste as categorias para fechar em até 100%.\n- **Faltar data, válvula ou safra.** Os três são obrigatórios; sem eles a colheita não grava. Escolha a safra da válvula para o registro entrar na trilha certa.\n- **Editar uma colheita que já entrou no estoque sem cuidado.** Se ela tinha entrada ativa, o sistema estorna antes de alterar e reconfirma depois — se o estorno falhar (período fechado no custeio), a colheita não muda. Reabra a safra no fechamento antes de editar.\n\n## Antes e depois\nAntes: Registrar os romaneios das cargas que saíram do campo. Depois: Confirmar a entrada da colheita no estoque para gerar o lote.\n\n## Roteiro do vídeo\n- Abrir Colheita mostrando os registros por válvula.\n- Clicar em + Nova colheita e preencher data, válvula e safra.\n- Distribuir os percentuais por categoria e narrar: \"A soma não pode passar de 100%.\"\n- Mostrar o faturamento estimado sendo calculado.\n- Destacar **Salvar colheita**; clicar e ver a linha na tabela.','colheita','registrar','safra','intermediario',175,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(13,NULL,'cadastrar-um-comprador','Cadastrar um comprador para vender e faturar para ele','FAZER',NULL,'## Finalidade\nO comprador é o cliente para quem a fazenda vende. Sem ele cadastrado, não dá para registrar venda nem firmar contrato. É também aqui que ficam os dados fiscais (CNPJ/CPF e Inscrição Estadual) que a NF-e vai precisar.\n\n## Como fazer\n1. Abra **Compradores** e clique em **Novo comprador**.\n2. Informe a **razão social** (obrigatória) e, se houver, o **nome fantasia**.\n3. Preencha o **CNPJ/CPF** — o sistema valida o dígito verificador e recusa documento inválido.\n4. Para comprador pessoa jurídica, informe a **Inscrição Estadual** (necessária para emitir NF-e depois).\n5. Complete e-mail, telefone e endereço se tiver, e clique em **Salvar**.\n\n## Erros comuns\n- **Digitar CNPJ/CPF errado.** O sistema barra documento com dígito verificador incorreto e não grava nada. Confira o número antes de salvar.\n- **Cadastrar o mesmo documento duas vezes.** Não é permitido comprador ativo repetido com o mesmo CNPJ/CPF. Procure na lista antes de criar um novo.\n- **Deixar PJ sem Inscrição Estadual.** O sistema salva, mas avisa: sem IE você não conseguirá emitir NF-e para esse comprador. Complete assim que tiver o dado.\n\n## Antes e depois\nAntes: ter os dados do cliente (documento e, se PJ, a IE). Depois: registrar uma venda ou firmar um contrato de pré-venda com ele.\n\n## Roteiro do vídeo\n- Abrir Compradores com a lista visível.\n- Narrar: \"O comprador precisa existir aqui antes de qualquer venda — e é dele que sai a IE da nota fiscal.\"\n- Criar novo comprador PJ, preencher razão social, CNPJ e IE.\n- Mostrar a validação do documento funcionando.\n- Salvar e apontar o comprador já disponível para venda.','comercial','cadastrar','continuo','iniciante',140,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(14,NULL,'definir-a-tabela-de-precos','Definir a tabela de preços para a venda sugerir o preço certo','FAZER',NULL,'## Finalidade\nA tabela de preços guarda regras de preço por cultura, variedade, calibre, embalagem, comprador, canal e safra. Na hora da venda, o sistema puxa a regra vigente mais específica como sugestão — então preencher bem a tabela é o que faz o preço certo aparecer sozinho.\n\n## Como fazer\n1. Abra **Tabela de preços** e clique em **Nova regra**.\n2. Informe o **preço** e o **início de vigência** (os dois obrigatórios) e escolha a **moeda**.\n3. Restrinja a regra o quanto precisar: cultura, variedade, calibre, embalagem, comprador, canal e safra. Quanto mais campos preenchidos, mais específica — e ela ganha das regras genéricas.\n4. Se a regra tiver validade, informe o **fim de vigência**.\n5. Clique em **Salvar** — a regra passa a sugerir preço nas novas vendas que se encaixarem nela.\n\n## Erros comuns\n- **Esquecer o início de vigência.** Sem data de início a regra não é aceita — ela precisa saber a partir de quando vale.\n- **Criar duas regras igualmente específicas para o mesmo caso.** O sistema escolhe a vigente mais específica; regras concorrentes confundem a sugestão. Encerre a vigência da antiga ao trocar o preço.\n- **Excluir uma regra antiga achando que some o histórico.** A exclusão apenas inativa (mantém a trilha). Para mudar o preço, crie uma nova regra com nova vigência em vez de apagar a anterior.\n\n## Antes e depois\nAntes: ter os preços acordados por cultura/comprador/canal. Depois: registrar vendas já com o preço sugerido automaticamente (e ajustável).\n\n## Roteiro do vídeo\n- Abrir Tabela de preços com regras cadastradas.\n- Narrar: \"A tabela não trava o preço da venda — ela sugere o preço certo, e você ajusta se precisar.\"\n- Criar uma regra específica: cultura, comprador e preço com início de vigência.\n- Salvar e mostrar, numa nova venda, o preço vindo sozinho.','comercial','cadastrar','continuo','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(15,NULL,'emitir-um-romaneio-de-saida','Registrar um romaneio de saída para conferir o embarcado com a venda','FAZER',NULL,'## Finalidade\nO romaneio registra o que de fato saiu no embarque, ligado a uma venda. Ele permite confrontar o peso embarcado com o kg vendido — se o carregamento saiu em várias viagens, cada uma vira um romaneio e a soma tem que bater com a venda.\n\n## Como fazer\n1. Abra **Romaneios** e clique em **Novo romaneio**.\n2. Escolha a **venda** (o sistema mostra comprador, kg vendido e lote de cada uma).\n3. Informe o **número do romaneio** e o **peso (kg)** embarcado (maior que zero).\n4. Ajuste a **data do romaneio** se não for hoje.\n5. Clique em **Salvar** — o embarque entra no confronto embarcado × vendido daquela venda.\n\n## Erros comuns\n- **Escolher venda cancelada.** Romaneio só liga a venda ativa. Se a venda foi cancelada, ele não é aceito.\n- **Somar romaneios acima do kg da venda.** A tela mostra o total embarcado por venda justamente para você perceber quando passou do vendido — confira antes de fechar mais um embarque.\n- **Repetir o número do romaneio.** Cada embarque tem seu número; repetir dificulta a conferência com a transportadora.\n\n## Antes e depois\nAntes: a venda já registrada. Depois: acompanhar o confronto embarcado × vendido e conferir com o comprador/transportadora.\n\n## Roteiro do vídeo\n- Abrir Romaneios agrupados por venda.\n- Narrar: \"O romaneio é a prova do que embarcou — e ele tem que fechar com o kg da venda.\"\n- Criar romaneio: escolher venda, número e peso.\n- Salvar e mostrar o confronto embarcado × vendido no card da venda.','comercial','registrar','safra','iniciante',130,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(16,NULL,'firmar-um-contrato-de-venda','Firmar um contrato de pré-venda para travar o preço antes da colheita','FAZER',NULL,'## Finalidade\nO contrato de pré-venda trava preço e quantidade antes da colheita: kg contratado × preço/kg, com vencimento. Quando o contrato está ativo, ele entra no fluxo de caixa como previsto e serve de referência para as vendas que forem faturadas contra ele.\n\n## Como fazer\n1. Abra **Contratos de venda** e clique em **Novo contrato**.\n2. Escolha o **comprador** e informe o **kg contratado** e o **preço/kg** (ambos maiores que zero).\n3. Se quiser, vincule **cultura** e **safra** e defina a **data de vencimento**.\n4. Clique em **Salvar** — o contrato nasce como **rascunho** com número automático (ex.: CT2026-0001).\n5. Quando o negócio estiver acertado, mude o status para **Ativo** — só assim ele passa a valer no fluxo de caixa.\n\n## Erros comuns\n- **Deixar o contrato em rascunho.** Rascunho não entra no fluxo de caixa. Ative o contrato quando o acordo estiver fechado.\n- **Tentar mudar o preço de um contrato ativo já faturado.** Se já existe venda vinculada, o preço fica travado e a edição é bloqueada — é essa a proteção do contrato. Cancele e refaça se o preço mudou de fato.\n- **Editar um contrato cumprido ou cancelado.** Não é possível; esses status são finais. Respeite o caminho rascunho → ativo → cumprido/cancelado.\n\n## Antes e depois\nAntes: comprador cadastrado e preço combinado com ele. Depois: registrar as vendas que faturam contra o contrato e acompanhar o saldo (kg contratado − kg faturado).\n\n## Roteiro do vídeo\n- Abrir Contratos de venda com a lista por status.\n- Narrar: \"O contrato trava o preço antes da fruta existir — é a proteção contra a oscilação do mercado.\"\n- Criar contrato: comprador, kg e preço/kg; salvar como rascunho.\n- Mudar o status para Ativo e mostrar ele entrando como previsto no fluxo.\n- Fechar apontando o saldo a faturar.','comercial','registrar','safra','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(17,NULL,'registrar-uma-venda','Registrar uma venda para baixar o estoque e gerar a conta a receber','FAZER',NULL,'## Finalidade\nRegistrar a venda é o passo que fecha o ciclo da produção: baixa o kg do lote agrícola no estoque e gera automaticamente a conta a receber no financeiro. Sem esse registro, a colheita continua parada no estoque e o dinheiro nunca aparece no fluxo.\n\n## Como fazer\n1. Abra **Vendas** e clique em **Nova venda**.\n2. Escolha o **comprador** e o **lote agrícola** (lote COLH- disponível vindo da colheita) — venda nova exige lote.\n3. Informe o **kg total**, a **qualidade** e o **preço** (a tabela de preços sugere um valor, que você pode ajustar).\n4. Defina a **data da venda**, o **vencimento** e, se for parcelado, o **número de parcelas**.\n5. Clique em **Salvar** — o sistema **baixa o kg do lote e gera a conta a receber** (uma parcela ou várias mensais).\n\n## Erros comuns\n- **Tentar vender sem lote.** Venda nova sem lote COLH- é barrada. Confirme a entrada da colheita no estoque (tela de Colheita) e selecione o lote antes.\n- **Vender mais kg do que o lote tem.** O estoque não fecha. Confira o saldo do lote antes de lançar o kg.\n- **Datar o vencimento errado.** A conta a receber nasce com o vencimento que você informar — se errar, o fluxo de caixa mostra a entrada no dia errado.\n- **Cancelar criando outra venda.** Para desfazer, use **Cancelar** na própria venda: ela devolve o kg ao lote e cancela a conta a receber. Não crie um lançamento novo para \"corrigir\".\n\n## Antes e depois\nAntes: comprador cadastrado e colheita já lançada no estoque como lote. Depois: emitir o romaneio de saída e acompanhar a conta a receber no financeiro.\n\n## Roteiro do vídeo\n- Abrir Vendas com o formulário de nova venda.\n- Narrar: \"Uma venda faz duas coisas de uma vez: tira a fruta do estoque e cria a conta a receber.\"\n- Escolher comprador, lote COLH-, kg e preço sugerido pela tabela.\n- Definir vencimento e salvar.\n- Mostrar a mensagem de estoque baixado e a conta a receber gerada.','comercial','registrar','safra','intermediario',190,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(18,NULL,'abrir-uma-solicitacao-de-compra','Abrir uma solicitação de compra','FAZER',NULL,'## Finalidade\nA solicitação de compra é o pedido interno: alguém da operação registra o que precisa comprar, sem ainda escolher fornecedor nem preço. Ela abre o fluxo — pode virar cotação para comparar fornecedores ou ir direto para um pedido de compra.\n\n## Como fazer\n1. Abra **Solicitações de Compra** e clique em **Nova solicitação**.\n2. Informe a **data** e adicione os **itens**: produto do cadastro (ou uma descrição livre) e a **quantidade**.\n3. Clique em **Salvar** — a solicitação nasce no status \"aberta\".\n4. Encaminhe: gere as **cotações** para comparar fornecedores ou converta direto em **pedido**.\n\n## Erros comuns\n- **Salvar sem itens ou sem data.** A data é obrigatória e uma solicitação vazia não serve para nada — liste pelo menos um item com quantidade.\n- **Descrever tudo em texto livre quando o produto já existe no cadastro.** Aponte o produto cadastrado sempre que possível: isso liga a compra ao estoque e ao custo mais tarde.\n- **Deixar a solicitação \"aberta\" e esquecer.** Ela não compra sozinha — precisa virar cotação ou pedido. Acompanhe a lista de abertas.\n\n## Antes e depois\nAntes: Perceber a necessidade (alerta de estoque mínimo, pedido da operação). Depois: Cotar fornecedores ou emitir o pedido de compra a partir dela.\n\n## Roteiro do vídeo\n- Abrir Solicitações e criar uma nova.\n- Adicionar dois itens com quantidade.\n- Salvar e mostrar o status \"aberta\".\n- Apontar os dois caminhos: gerar cotação ou converter em pedido.','compras','solicitar','continuo','iniciante',140,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(19,NULL,'aprovar-um-pedido-de-compra','Aprovar ou rejeitar um pedido de compra','FAZER',NULL,'## Finalidade\nA tela de Aprovações é a alçada: os pedidos enviados ficam numa fila esperando um sim ou não de quem tem autoridade para autorizar a compra. Aprovar libera o pedido para recebimento; rejeitar devolve ao rascunho para o comprador corrigir, com a observação registrada.\n\n## Como fazer\n1. Abra **Aprovações** e veja a fila de pedidos pendentes.\n2. Abra o pedido e confira fornecedor, itens, valores e prazo.\n3. Clique em **Aprovar** para liberar — o pedido fica pronto para ser recebido.\n4. Ou clique em **Rejeitar**, escrevendo a **observação** do motivo — ele volta a rascunho para ajuste.\n\n## Erros comuns\n- **Aprovar sem ler o pedido.** A aprovação é o controle de gasto; confira valor, fornecedor e vínculo de safra antes de liberar — depois de aprovado, ele segue para recebimento.\n- **Rejeitar sem escrever o motivo.** Sem a observação, o comprador não sabe o que corrigir e o pedido volta e volta. Diga o que precisa mudar.\n- **Procurar um pedido já decidido na fila.** A fila mostra só os pendentes; um pedido já aprovado ou rejeitado não aparece aqui — consulte-o na tela de Pedidos.\n\n## Antes e depois\nAntes: O comprador enviar o pedido para aprovação. Depois: Receber a compra no estoque quando o material chegar.\n\n## Roteiro do vídeo\n- Abrir Aprovações com pedidos pendentes.\n- Abrir um pedido e conferir valores e fornecedor.\n- Aprovar um e mostrar que ele sai da fila liberado.\n- Rejeitar outro com observação e mostrar que voltou a rascunho.','compras','aprovar','continuo','intermediario',130,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(20,NULL,'cadastrar-um-fornecedor','Cadastrar um fornecedor','FAZER',NULL,'## Finalidade\nO fornecedor é a ficha de quem vende para a fazenda: nome, CNPJ/CPF, categoria, cidade/UF e condição de pagamento. Ele é referenciado nas cotações, nos pedidos e nos recebimentos — e a própria ficha vai acumulando volume, ticket, lead time e % de entregas no prazo para você comparar quem entrega melhor.\n\n## Como fazer\n1. Abra **Fornecedores** e clique em **Novo fornecedor**.\n2. Preencha o **nome**, o **CNPJ/CPF**, a **categoria**, cidade/UF e a **condição de pagamento**.\n3. Clique em **Salvar** — o documento é normalizado (sem pontuação) para não duplicar por diferença de formatação.\n4. Depois, use a **ficha (?ficha=ID)** para ver o desempenho consolidado do fornecedor.\n\n## Erros comuns\n- **Cadastrar o mesmo fornecedor duas vezes com o CNPJ formatado diferente.** O sistema normaliza o documento para evitar isso, mas confira antes — duplicata quebra a ficha de desempenho e o histórico.\n- **Deixar categoria e condição de pagamento em branco.** Sem categoria você não filtra fornecedores; sem condição de pagamento os pedidos precisam preencher tudo de novo toda vez.\n- **Inativar um fornecedor com histórico achando que apaga tudo.** A inativação é lógica (campo ativo) — o histórico de compras dele continua íntegro para relatórios.\n\n## Antes e depois\nAntes: Reunir os dados do fornecedor (documento, contato, condição). Depois: Usá-lo nas cotações e nos pedidos de compra.\n\n## Roteiro do vídeo\n- Abrir Fornecedores e criar um novo.\n- Preencher nome, CNPJ, categoria e condição de pagamento; salvar.\n- Abrir a ficha consolidada de um fornecedor com histórico (volume, lead time, % no prazo).\n- Mostrar o fornecedor disponível na cotação.','compras','cadastrar','continuo','iniciante',140,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(21,NULL,'cotar-fornecedores-e-escolher-a-vencedora','Cotar fornecedores e escolher a cotação vencedora','FAZER',NULL,'## Finalidade\nA cotação compara fornecedores para a mesma solicitação. Cada fornecedor cotado vira uma linha com os itens precificados, e o comparativo mostra os totais lado a lado. Você marca a vencedora — as demais ficam recusadas, mas continuam no comparativo para preservar a história da decisão.\n\n## Como fazer\n1. Abra **Cotações** e selecione a **solicitação de compra** que quer cotar.\n2. Adicione uma cotação por **fornecedor**: informe a data e os **preços** de cada item da solicitação.\n3. Repita para os outros fornecedores e leia o **comparativo** de totais lado a lado.\n4. Clique em **Escolher** na melhor — ela vira \"escolhida\" e as outras, \"recusadas\". Depois use **Gerar pedido**.\n\n## Erros comuns\n- **Cotar uma solicitação sem itens.** A cotação copia os itens da solicitação; se ela estiver vazia, o sistema recusa — volte e complete a solicitação primeiro.\n- **Escolher pelo menor total ignorando prazo e frete.** O comparativo mostra o valor, mas prazo de entrega e condição de pagamento entram na decisão real — olhe além do número.\n- **Achar que \"escolher\" já gera o pedido.** Marcar a vencedora só define a decisão; o pedido de compra é criado no passo seguinte, com \"Gerar pedido\".\n\n## Antes e depois\nAntes: Ter a solicitação de compra aberta com itens. Depois: Gerar o pedido de compra a partir da cotação escolhida.\n\n## Roteiro do vídeo\n- Abrir Cotações e escolher uma solicitação.\n- Cadastrar duas cotações de fornecedores diferentes com preços.\n- Mostrar o comparativo de totais lado a lado.\n- Escolher a vencedora e apontar o botão Gerar pedido.','compras','cotar','continuo','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(22,NULL,'emitir-um-pedido-de-compra','Emitir um pedido de compra e enviar para aprovação','FAZER',NULL,'## Finalidade\nO pedido de compra é o documento firme com o fornecedor: itens, preços, prazo de entrega, frete e condição de pagamento. Ele segue um fluxo — rascunho → aprovação → aprovado → recebido — e pode nascer de uma solicitação ou de uma cotação escolhida. É ele que depois casa com o recebimento no estoque.\n\n## Como fazer\n1. Abra **Pedidos de Compra** e clique em **Novo pedido** (ou gere a partir de uma cotação/solicitação).\n2. Escolha o **fornecedor**, a **data**, os **itens com preço** e preencha prazo, frete e condição de pagamento.\n3. Salve o **rascunho** e revise os valores.\n4. Clique em **Enviar para aprovação** — o pedido vai para a fila de Aprovações (ou é liberado direto, se estiver dentro da alçada de valor configurada).\n\n## Erros comuns\n- **Deixar o pedido em rascunho e achar que já foi comprado.** Só pedidos em rascunho vão para aprovação; enquanto não enviar, nada acontece com ele.\n- **Esquecer prazo de entrega e condição de pagamento.** Esses campos alimentam a ficha do fornecedor (lead time, % no prazo) e o controle de orçamento — preencha para os relatórios fecharem.\n- **Vincular à safra errada (ou não vincular).** O vínculo com o talhão/safra é o que joga a compra no custo certo e no controle de orçamento; sem ele, o pedido pode cair em \"compras fora do orçamento\".\n\n## Antes e depois\nAntes: Escolher a cotação vencedora (ou abrir a solicitação). Depois: Aprovar o pedido e, na entrega, receber a compra no estoque.\n\n## Roteiro do vídeo\n- Abrir Pedidos e criar um novo a partir de uma cotação escolhida.\n- Preencher fornecedor, itens, prazo, frete e condição.\n- Salvar o rascunho e revisar o total.\n- Enviar para aprovação e mostrar o pedido entrando na fila.','compras','comprar','continuo','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(23,NULL,'comparar-o-custo-entre-safras','Comparar o custo entre safras','CONSULTAR',NULL,'## Finalidade\nO comparativo coloca até quatro safras lado a lado — área, produção, faturamento, custo por categoria, custo/ha, custo/kg, resultado e margem — para responder \"a 2026.2 foi melhor que a 2026.1 no mesmo parreiral?\". Como a safra do VERO é o ciclo de poda, dá para comparar ciclos do mesmo talhão ao longo do tempo.\n\n## Como fazer\n1. Abra **Comparativo entre Safras**. Ele já vem com as duas safras mais recentes.\n2. Selecione as **safras** que quer confrontar — até quatro de uma vez.\n3. Leia as linhas lado a lado, com atenção ao **custo/ha** e ao **custo/kg**, que neutralizam diferenças de tamanho.\n4. Olhe a quebra por **categoria** para descobrir onde uma safra gastou mais que a outra.\n\n## Erros comuns\n- **Comparar pelo custo total absoluto.** Safras de áreas diferentes têm totais diferentes por natureza — compare pelo custo por hectare e por kg, não pelo total.\n- **Comparar safra fechada com safra em andamento.** Uma safra ainda aberta tem custo incompleto; verifique o status antes de tirar conclusões.\n\n## Antes e depois\nAntes: Conferir o custo realizado de cada safra. Depois: Usar o aprendizado para calibrar o orçamento da próxima.\n\n## Roteiro do vídeo\n- Abrir o Comparativo com duas safras.\n- Adicionar uma terceira e narrar a leitura de custo/ha e custo/kg.\n- Apontar a categoria que mais variou entre elas.','custos','comparar','safra','iniciante',100,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(24,NULL,'configurar-a-metodologia-de-custeio','Configurar a metodologia de custeio','FAZER',NULL,'## Finalidade\nA metodologia define como o custo de produção é organizado e de onde cada valor realizado é puxado. Ela tem grupos (variável, fixo, operacional) e, dentro deles, itens que apontam para uma origem de custo do sistema. É o esqueleto que o orçamento de produção usa para gerar itens e que a derivação do realizado segue para saber o que entra em cada linha.\n\n## Como fazer\n1. Abra **Metodologias** e crie uma **metodologia**: nome e **tipo de ciclo** (anual ou perene).\n2. Dentro dela, adicione **grupos** — cada grupo tem um tipo: variável, fixo ou operacional.\n3. Em cada grupo, adicione **itens** informando **nome, método de cálculo e origem** (de onde o realizado vem: aplicação, apontamento, folha, irrigação…).\n4. Ao salvar o item, o VERO checa o **mapa do realizado**: se a origem/categoria já estiver coberta por outro item, ele avisa — e se a sobreposição for exata, **bloqueia** para não contar o mesmo custo duas vezes.\n5. Deixe ativa a metodologia que vai ser usada. A seed \"Padrão VERO\" é editável e pode ser inativada — nunca é obrigatória.\n\n## Erros comuns\n- **Dois itens puxando a mesma origem.** O mesmo custo entraria duas vezes. Quando a sobreposição é exata o sistema bloqueia; quando é parcial, ele só avisa — leia o aviso e ajuste.\n- **Inativar uma metodologia com orçamento aberto.** O sistema não deixa: feche ou cancele os orçamentos que a usam antes de inativá-la.\n- **Confundir tipo de ciclo.** Anual e perene mudam como o custo de formação é tratado — escolha conforme a cultura, não no chute.\n\n## Antes e depois\nAntes: Definir com o cliente quais grupos e origens compõem o custo. Depois: Usar a metodologia para montar o orçamento de produção e derivar o realizado.\n\n## Roteiro do vídeo\n- Criar uma metodologia anual e um grupo variável.\n- Adicionar um item com origem \"aplicação\" e salvar.\n- Tentar um segundo item na mesma origem e mostrar o aviso/bloqueio do mapa.','custos','configurar','continuo','iniciante',200,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(25,NULL,'definir-as-metas-da-safra','Definir as metas da safra','FAZER',NULL,'## Finalidade\nMetas são os alvos que você quer bater na safra: custo total, custo por hectare, colheita em kg, produtividade, faturamento, preço médio e margem. O Dashboard Executivo confronta cada meta com o realizado — sem meta definida, não há com o que comparar o resultado.\n\n## Como fazer\n1. Abra **Metas da Safra** e selecione a **safra** no topo.\n2. Escolha o **indicador** (custo por hectare, produtividade, margem…).\n3. Informe o **valor da meta** — precisa ser maior que zero — e uma observação opcional.\n4. Clique em **Salvar meta**. Ela vira um card e passa a valer no Dashboard Executivo.\n5. Repita para cada indicador que quiser acompanhar. Cada indicador tem **uma única meta por safra** — salvar o mesmo indicador de novo apenas atualiza o valor.\n\n## Erros comuns\n- **Digitar o valor na unidade errada.** Custo por hectare é R$/ha, produtividade é kg/ha, margem é %. Confira a unidade no rótulo do indicador antes de salvar.\n- **Duplicar o indicador.** Não existe meta repetida — salvar de novo sobrescreve. Se o número mudou, é só salvar por cima.\n- **Definir meta na safra errada.** Confira a safra selecionada no topo antes de salvar; a meta fica amarrada a ela.\n\n## Antes e depois\nAntes: Abrir a safra que vai receber as metas. Depois: Acompanhar meta versus realizado no Dashboard Executivo.\n\n## Roteiro do vídeo\n- Abrir Metas da Safra e escolher a safra.\n- Cadastrar duas metas (custo/ha e produtividade) e mostrar os cards surgindo.\n- Salvar o mesmo indicador com outro valor e mostrar que atualiza, não duplica.','custos','definir','safra','iniciante',120,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(26,NULL,'fechar-a-safra-no-custeio','Fechar a safra no custeio','FAZER',NULL,'## Finalidade\nFechar a safra grava um retrato do custo total apurado naquele momento — é a referência oficial para o resultado final. A partir do fechamento, a safra **não aceita mais lançamentos de custeio**, o que impede que números novos mexam num período que já foi consolidado.\n\n## Como fazer\n1. Abra **Fechamento de Safra** e localize a safra na lista, com o custo apurado ao lado.\n2. Antes de fechar, se houver custos indiretos, aplique o **rateio** da safra — o próprio botão de ratear fica aqui.\n3. Clique em **Fechar** na safra desejada.\n4. Confirme. O sistema grava o **snapshot do custo total** e a partir daí trava novos lançamentos de custeio nessa safra.\n5. Leia o aviso: se sobrar custo indireto **sem rateio**, a mensagem avisa que o custo por talhão está incompleto — vale rerratear antes de dar por encerrada.\n\n## Erros comuns\n- **Fechar com indiretos ainda soltos.** A mensagem avisa \"custos indiretos sem rateio\". Se ignorar, o custo por hectare fica menor que o real — rateie e refeche.\n- **Precisar de um ajuste depois de fechar.** Não force por fora: use **Reabrir**, lance a correção e feche de novo — o snapshot é recalculado ao refechar.\n- **Reabrir e esquecer do rateio.** Se havia rateio aplicado, ao reabrir você precisa desfazer e reaplicar após os ajustes — a própria tela avisa.\n\n## Antes e depois\nAntes: Ratear os custos indiretos e conferir o custo realizado. Depois: Comparar o resultado desta safra com outras.\n\n## Roteiro do vídeo\n- Abrir Fechamento de Safra com o custo apurado visível.\n- Fechar uma safra e mostrar o snapshot gravado no histórico.\n- Reabrir para demonstrar o ciclo fechado → reaberto → refechado.','custos','fechar','safra','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(27,NULL,'montar-o-orcamento-da-safra','Montar o orçamento da safra','FAZER',NULL,'## Finalidade\nO orçamento é o quanto você planeja gastar na safra, quebrado por categoria: mão de obra, insumos, máquinas, irrigação e outros. É a régua contra a qual o realizado vai ser medido depois em Realizado vs Planejado — sem orçamento, não existe desvio para acompanhar.\n\n## Como fazer\n1. Abra **Orçamento de Safra** e clique em **+ Novo orçamento**.\n2. Selecione a **safra**. Cada safra só pode ter um orçamento ativo por vez.\n3. Preencha o **previsto por categoria** — deixe em branco (ou zero) as categorias sem previsão.\n4. Clique em **Salvar**. O sistema soma tudo e mostra o **total previsto**.\n5. Quando o orçamento estiver pronto, use o botão de **tornar vigente** — é isso que o marca como a versão oficial da safra e encerra qualquer outro vigente.\n\n## Erros comuns\n- **Deixar o orçamento em rascunho.** Rascunho não é a referência oficial — só o orçamento **vigente** vira régua. Torne-o vigente quando fechar os números.\n- **Tentar criar um segundo orçamento na mesma safra.** O sistema bloqueia: edite o que já existe ou encerre-o antes de abrir outro.\n- **Querer editar um orçamento encerrado.** Encerrado é histórico e não muda mais. Se precisar ajustar, reabra-o como rascunho.\n\n## Antes e depois\nAntes: Abrir a safra que vai receber o orçamento. Depois: Acompanhar o realizado contra este previsto em Realizado vs Planejado.\n\n## Roteiro do vídeo\n- Abrir Orçamento de Safra e clicar em + Novo orçamento.\n- Selecionar a safra e preencher duas ou três categorias.\n- Salvar e narrar o total previsto aparecendo.\n- Tornar vigente e mostrar o badge mudando de Rascunho para Vigente.','custos','orcar','safra','intermediario',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(28,NULL,'montar-o-orcamento-de-producao','Montar o orçamento de produção da safra','FAZER',NULL,'## Finalidade\nO orçamento de produção é o planejamento detalhado do custo, item por item, seguindo a metodologia de custeio. Diferente do orçamento simples (só o total por categoria), aqui o VERO gera os itens a partir da metodologia e calcula os indicadores — custo por hectare, custo por kg e o ponto de equilíbrio — a partir da produtividade e do preço previstos.\n\n## Como fazer\n1. Abra **Orçamento de Produção** e clique em **+ Novo** para iniciar o assistente.\n2. No cabeçalho, escolha **cultura, safra, fazenda e metodologia** e informe a **área** — o VERO já puxa a produtividade, o preço e a área dos parâmetros da cultura.\n3. Confirme para **gerar os itens da metodologia** — cada grupo e item aparece numa tabela editável.\n4. Ajuste os **valores previstos** item a item; os indicadores recalculam conforme você edita.\n5. Peça a **aprovação** — este é o passo que trava o orçamento como plano oficial, e só **gestor ou administrador** pode aprovar.\n\n## Erros comuns\n- **Montar sem os parâmetros da cultura prontos.** Sem produtividade e preço previstos, os indicadores saem vazios ou errados. Parametrize a cultura antes.\n- **Esperar ver a margem sem permissão financeira.** A margem só aparece para quem enxerga o financeiro (gestor, financeiro, contador) — operador e consulta não veem, e isso é proposital.\n- **Achar que salvar aprova.** Salvar guarda os valores; a **aprovação** é um passo à parte, restrito a gestor/administrador.\n\n## Antes e depois\nAntes: Configurar a metodologia e parametrizar a cultura da safra. Depois: Fechar a safra e confrontar o previsto com o custo apurado.\n\n## Roteiro do vídeo\n- Abrir Orçamento de Produção e iniciar o assistente.\n- Escolher cultura/safra/fazenda e mostrar os defaults sendo puxados.\n- Gerar os itens e editar dois valores, narrando o custo/ha recalculando.\n- Aprovar com um usuário gestor e mostrar o orçamento travado.','custos','planejar','safra','iniciante',180,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(29,NULL,'parametrizar-a-cultura-da-safra','Parametrizar a cultura da safra','FAZER',NULL,'## Finalidade\nAqui você define, por cultura e safra, o que se espera dela: produtividade prevista (kg/ha), preço previsto e área prevista, além da metodologia de custeio que vai reger o orçamento. São esses parâmetros que o orçamento de produção puxa como ponto de partida e que fazem os indicadores (custo/kg, ponto de equilíbrio) terem sentido.\n\n## Como fazer\n1. Abra **Parâmetros de Cultura** e selecione a **safra** no topo.\n2. Adicione ou edite um parâmetro escolhendo **cultura** e a **metodologia ativa** que vai reger o custo.\n3. Informe **produtividade prevista, preço previsto e área prevista** — nenhum valor pode ser negativo.\n4. Se precisar, ajuste as **unidades da cultura** (unidade comercial, fator de conversão, peso por unidade) nos campos inline.\n5. Clique em **Salvar**. Um mesmo par cultura+safra é atualizado no lugar (não duplica).\n\n## Erros comuns\n- **Apagar a unidade da cultura sem querer.** Campo de unidade deixado em branco **não apaga** o que já está gravado na cultura — só grava o que você preencher. Mas lembre: unidade vale para **todas as safras**, pois é gravada na cultura, não no parâmetro.\n- **Escolher uma metodologia inativa.** Só metodologia **ativa** é aceita — ative-a em Metodologias antes.\n- **Deixar produtividade ou preço em branco.** Sem eles, o orçamento de produção gera indicadores vazios. Preencha o que se espera da safra.\n\n## Antes e depois\nAntes: Configurar a metodologia de custeio que a cultura vai usar. Depois: Montar o orçamento de produção puxando estes parâmetros.\n\n## Roteiro do vídeo\n- Abrir Parâmetros de Cultura e escolher a safra.\n- Cadastrar uma cultura com produtividade, preço e área previstos.\n- Salvar e mostrar que reeditar atualiza no lugar, sem duplicar.','custos','parametrizar','safra','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(30,NULL,'ratear-os-custos-indiretos','Ratear os custos indiretos entre as safras','FAZER',NULL,'## Finalidade\nRatear é distribuir os custos que não nasceram amarrados a um talhão ou safra — folha, depreciação, energia, combustível — entre as safras e válvulas certas, para que o custo por hectare fique completo e justo. Sem rateio, esses custos gerais ficam \"soltos\" e o custo por talhão sai menor do que a realidade.\n\n## Como fazer\n1. Abra **Rateios**. A tela tem três blocos: lançamentos sem safra, combustível por horas e as regras de critério.\n2. No bloco **1 · Lançamentos sem safra**, confira os custos gerais pendentes e clique em **Atribuir às safras do período** — eles são distribuídos pela área plantada de cada safra ativa.\n3. No bloco **2 · Combustível por horas**, clique em **Ratear por horas** para distribuir os abastecimentos às válvulas conforme as horas de máquina apontadas.\n4. Em **3 · Regras de rateio**, use **+ Nova regra** para registrar o critério acordado com o cliente (base: área, produção, custo direto ou manual).\n5. Confira as memórias de cálculo. Cada cota vira **uma linha própria**, o lançamento original nunca é apagado e toda distribuição é **reversível** pelo botão de desfazer.\n\n## Erros comuns\n- **Rodar o rateio antes de todos os lançamentos entrarem.** O que ficar para depois não é rateado retroativamente sozinho — lance tudo do período, depois distribua.\n- **Ratear de novo achando que corrige.** Aplicar de novo não duplica, mas também não conserta um erro: use **Desfazer** e reaplique após ajustar.\n- **Esperar combustível rateado onde não há horas.** Se a máquina não tem horas em safra ativa no mês, o abastecimento é **pulado** (e reportado), não chutado por área.\n\n## Antes e depois\nAntes: Lançar todos os custos do período, inclusive os gerais sem safra. Depois: Fechar a safra com o custo por hectare já completo.\n\n## Roteiro do vídeo\n- Abrir Rateios e mostrar os três blocos.\n- Atribuir os lançamentos sem safra e mostrar as linhas com memória de cálculo.\n- Ratear o combustível por horas.\n- Desfazer uma distribuição para mostrar que é reversível.','custos','ratear','safra','iniciante',190,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(31,NULL,'ajustar-ou-estornar-movimentacao-de-estoque','Ajustar o saldo ou estornar uma movimentação de estoque','FAZER',NULL,'## Finalidade\nO Histórico de Movimentações é a trilha de tudo que entrou e saiu — e é também onde você corrige. Dá para fazer um ajuste tipado (com motivo obrigatório, por produto ou por lote), registrar uma devolução de campo (sobra de apontamento que volta ao custo original) e estornar um lançamento manual errado.\n\n## Como fazer\n1. Abra **Histórico de Movimentações** e localize o produto ou o lançamento.\n2. Para acertar saldo, use **Ajustar**: escolha o motivo, a direção (aumentar/reduzir), a quantidade e a data.\n3. Para desfazer um lançamento manual errado, use **Estornar** e informe o **motivo** — o sistema gera o contra-movimento.\n4. Confira o novo saldo na tela de Produtos.\n\n## Erros comuns\n- **Ajustar sem escolher o motivo.** O motivo é obrigatório e é o que dá rastreabilidade ao acerto — sem ele o sistema recusa.\n- **Tentar estornar uma compra ou apontamento por aqui.** Documentos (compra, apontamento, aplicação, inventário) estornam pela tela de origem; aqui só saem lançamentos `manual` e `devolução de campo`. Transferência tem o fluxo do par na tela própria.\n- **Estornar sem alçada.** O estorno usa a permissão `estoque.historico_movimentacoes.excluir`; se você só tem a de edição, faz ajuste, mas não estorno.\n\n## Antes e depois\nAntes: Identificar a divergência (pela auditoria ou pelo inventário). Depois: Conferir o saldo corrigido e o contra-movimento registrado no histórico.\n\n## Roteiro do vídeo\n- Abrir o Histórico e filtrar um produto com divergência.\n- Fazer um ajuste de redução com motivo; mostrar o saldo mudando.\n- Localizar um lançamento manual errado e estorná-lo com motivo.\n- Mostrar o contra-movimento na trilha.','estoque','corrigir','continuo','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(32,NULL,'bloquear-lote-e-rastrear-validade','Bloquear um lote por qualidade e rastrear sua origem','FAZER',NULL,'## Finalidade\nA tela de Lotes é a base do FEFO: mostra saldo, validade, dias para vencer, origem e custo de cada lote. Aqui você bloqueia manualmente um lote com problema de qualidade (para ele não sair no consumo) e rastreia de onde ele veio — colheita, compra ou transferência — e para onde foi.\n\n## Como fazer\n1. Abra **Lotes e Validade** e use os filtros de situação para achar o lote (por exemplo, \"a vencer\" ou \"bloqueado\").\n2. Para tirar um lote da fila de consumo, clique em **Bloquear** — ele deixa de ser escolhido pelo FEFO.\n3. Resolvida a pendência de qualidade, clique em **Desbloquear** para devolvê-lo ao consumo.\n4. Para investigar, use o **Rastreio**: para trás mostra a origem do lote; para frente, os consumos que ele abasteceu.\n\n## Erros comuns\n- **Tentar mudar um status que é do sistema.** Só a transição manual disponível↔bloqueado é permitida; \"em classificação\", \"consumido\" e \"estornado\" são controlados pelo sistema (colheita, consumo, estorno) e o app recusa a troca.\n- **Bloquear e esquecer.** Lote bloqueado não sai no consumo — se a colheita ou a aplicação \"não encontram saldo\", confira se não há lote bloqueado indevidamente.\n- **Confundir bloqueio com baixa.** Bloquear não tira o produto do estoque; só o congela. Para reduzir de fato, use ajuste ou inventário.\n\n## Antes e depois\nAntes: Detectar o problema de qualidade ou a validade curta (alerta de estoque). Depois: Desbloquear quando resolver, ou ajustar/descartar o saldo se o lote for perdido.\n\n## Roteiro do vídeo\n- Abrir Lotes, filtrar \"a vencer\" e escolher um lote suspeito.\n- Bloquear o lote; narrar \"agora o FEFO não o usa mais\".\n- Abrir o rastreio para trás mostrando a origem do lote.\n- Desbloquear para devolver ao consumo.','estoque','controlar','continuo','intermediario',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(33,NULL,'cadastrar-um-almoxarifado','Cadastrar um almoxarifado','FAZER',NULL,'## Finalidade\nO almoxarifado é o lugar físico onde o estoque fica guardado — depósito da sede, galpão de uma fazenda, tanque de combustível. Cada saldo e cada movimentação pertencem a um almoxarifado, e é isso que permite transferir produto de um para outro e inventariar cada local separadamente.\n\n## Como fazer\n1. Abra **Almoxarifados** e clique em **Novo almoxarifado**.\n2. Dê um **nome** claro e, se fizer sentido, vincule à **fazenda** e escolha o **tipo**.\n3. Clique em **Salvar** — ele já fica disponível para receber entradas e transferências.\n4. Para desativar um antigo, use **Excluir** (inativa) — só funciona se ele estiver sem saldo.\n\n## Erros comuns\n- **Repetir um nome já existente.** Não pode haver dois almoxarifados ativos com o mesmo nome — o sistema recusa; use nomes distintos (ex.: \"Galpão Sede\" e \"Galpão Fazenda B\").\n- **Tentar inativar um almoxarifado com saldo.** Transfira todo o estoque para outro local antes; enquanto houver saldo, o sistema bloqueia a inativação.\n- **Criar almoxarifados demais.** O \"Almoxarifado Central\" já é criado pelo sistema quando necessário — crie novos só para locais que você realmente controla separado.\n\n## Antes e depois\nAntes: Definir os locais físicos de estoque da operação. Depois: Cadastrar produtos e transferir saldo entre os almoxarifados.\n\n## Roteiro do vídeo\n- Abrir Almoxarifados e criar um novo.\n- Preencher nome, vincular a uma fazenda e salvar.\n- Mostrar o novo almoxarifado disponível na lista de transferência.\n- Tentar inativar um com saldo e mostrar a mensagem de bloqueio.','estoque','cadastrar','continuo','iniciante',120,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(34,NULL,'cadastrar-um-produto-no-estoque','Cadastrar um produto no estoque','FAZER',NULL,'## Finalidade\nO produto é a ficha de tudo que entra e sai do estoque: código, nome, unidade, tipo de insumo e grupo. Sem ele cadastrado, não há como dar entrada de nota, apontar consumo no campo nem calcular o custo médio. É o primeiro passo de qualquer item novo.\n\n## Como fazer\n1. Abra **Produtos e Insumos** e clique em **Novo produto**.\n2. Preencha o **código** (6 números — o campo já traz o próximo livre) e o **nome**.\n3. Escolha o **tipo de insumo** (defensivo, fertilizante, semente etc.), a **unidade** e o **grupo/subgrupo**.\n4. Clique em **Salvar** — o produto passa a aparecer nas telas de entrada, saída e apontamento.\n\n## Erros comuns\n- **Sobrescrever o código sugerido por um número que já existe.** O código é único no tenant e o cadastro é recusado; só troque o número se precisar de um específico e livre.\n- **Errar a unidade de medida.** Ela alimenta o custo médio e as doses; um produto em litros cadastrado como quilo distorce todo o consumo depois. Confira antes de salvar.\n- **Cadastrar dados de bula (dose, carência) que só o gestor/RT deveria editar.** Deixe esses campos para quem tem a alçada — o cadastro básico você faz normalmente.\n\n## Antes e depois\nAntes: Organizar os grupos e subgrupos para classificar o produto. Depois: Fazer o saldo inicial ou dar a primeira entrada de nota.\n\n## Roteiro do vídeo\n- Abrir Produtos e Insumos e clicar em Novo produto.\n- Mostrar o código de 6 dígitos já preenchido; narrar \"o sistema sugere o próximo livre\".\n- Preencher nome, tipo, unidade e grupo; destacar a unidade como campo crítico.\n- Salvar e mostrar o produto novo aparecendo na lista.','estoque','cadastrar','continuo','iniciante',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(35,NULL,'conferir-a-auditoria-do-estoque','Conferir a auditoria de consistência do estoque','CONSULTAR',NULL,'## Finalidade\nA Auditoria de Estoque é uma tela só de leitura que roda um conjunto de checagens de consistência com severidade (crítico, atenção, baixa) — por exemplo, saldo consolidado que não bate com a soma das movimentações. Ela não grava nada: aponta os achados para você corrigir nas telas próprias.\n\n## Como fazer\n1. Abra **Auditoria de Estoque** e leia o placar geral no topo.\n2. Priorize as checagens **críticas** — são as que indicam saldo inconsistente de verdade.\n3. Abra cada checagem para ver os itens afetados (produto, almoxarifado, diferença).\n4. Corrija na tela certa: ajuste ou estorno no Histórico, contagem no Inventário, ou a tela de origem do documento.\n\n## Antes e depois\nAntes: Rodar a auditoria periodicamente (pré e pós-homologação). Depois: Corrigir os achados nas telas de origem e rodar de novo até o placar zerar as críticas.\n\n## Roteiro do vídeo\n- Abrir a Auditoria e mostrar o placar por severidade.\n- Expandir uma checagem crítica e ler os itens.\n- Narrar \"a correção acontece na tela própria, não aqui\".\n- Mostrar o caminho para o Histórico/Inventário e o placar melhorando depois.','estoque','conferir','continuo','intermediario',120,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(36,NULL,'fazer-inventario-do-almoxarifado','Fazer o inventário (contagem) de um almoxarifado','FAZER',NULL,'## Finalidade\nO inventário confronta o saldo do sistema com a contagem física do almoxarifado. Ele abre congelando o saldo item por item (por lote, quando o produto tem lotes), recebe a contagem real e, ao ser aprovado, gera os acertos automáticos pela diferença — com trilha completa no histórico.\n\n## Como fazer\n1. Abra **Inventário**, selecione o **almoxarifado** e clique em **Abrir inventário**.\n2. Percorra a lista e digite a **quantidade contada** de cada item (vem pré-preenchido com o saldo do sistema).\n3. Clique em **Fechar contagem** — o inventário fica no status \"contado\", ainda sem mexer no estoque.\n4. Peça a quem tem alçada para **Aprovar**: só então os acertos entram e o saldo passa a bater com a contagem.\n\n## Erros comuns\n- **Abrir um segundo inventário no mesmo almoxarifado.** O sistema recusa enquanto houver um em andamento — conclua ou cancele o aberto primeiro.\n- **Achar que fechar a contagem já ajusta o estoque.** Não ajusta: fechar só grava a contagem. O saldo só muda na aprovação (alçada `estoque.inventario.excluir`).\n- **Contar produto com lote somando tudo numa linha.** Quando o produto tem lotes, cada lote é uma linha própria — conte lote a lote para o FEFO continuar correto.\n\n## Antes e depois\nAntes: Ter os produtos e o almoxarifado cadastrados. Depois: Conferir os acertos no histórico de movimentações e, se preciso, rodar a auditoria de consistência.\n\n## Roteiro do vídeo\n- Abrir Inventário, escolher o almoxarifado e abrir a contagem.\n- Digitar contagens diferentes do saldo em alguns itens.\n- Fechar a contagem; mostrar o status \"contado\" sem mexer no estoque.\n- Aprovar e mostrar o acerto entrando no histórico e o saldo passando a bater.','estoque','conferir','continuo','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(37,NULL,'importar-produtos-por-planilha','Importar produtos em massa por planilha','FAZER',NULL,'## Finalidade\nQuando você tem dezenas ou centenas de produtos para cadastrar, a importação por planilha faz isso de uma vez. Você sobe um CSV no template padrão, o sistema valida linha a linha e mostra o que vai criar ou atualizar — e só grava depois que você confirma. O casamento é pelo código: existe, atualiza; não existe, cria.\n\n## Como fazer\n1. Abra **Importar Produtos** e baixe o **template CSV** (já vem com o cabeçalho e um exemplo).\n2. Preencha a planilha (código, nome, ingrediente ativo, tipo, unidade, doses, carência etc.) e salve como CSV.\n3. Suba o arquivo — o sistema roda **sempre um dry-run primeiro**: mostra o que será criado e atualizado, com os erros por linha.\n4. Revise a prévia e clique em **Confirmar** para gravar de fato.\n\n## Erros comuns\n- **Achar que subir o arquivo já grava.** Não grava: a primeira passada é só validação. Os produtos só entram quando você clica em Confirmar.\n- **Mudar o cabeçalho ou a ordem das colunas do template.** Use o template como está; tipo e unidade fora da lista aceita (defensivo, fertilizante… / kg, L, mL, g, un) travam a linha.\n- **Reusar um código já existente sem querer.** Código repetido não duplica — ele atualiza o produto existente. Confira a prévia para não sobrescrever um cadastro certo.\n\n## Antes e depois\nAntes: Ter os grupos definidos e a planilha preenchida no template. Depois: Fazer o saldo inicial dos produtos importados e conferir alguns cadastros na tela de Produtos.\n\n## Roteiro do vídeo\n- Abrir Importar Produtos e baixar o template.\n- Mostrar a planilha preenchida com algumas linhas.\n- Subir o arquivo e percorrer a prévia do dry-run (criados x atualizados x erros).\n- Confirmar e mostrar os produtos novos na lista.','estoque','importar','continuo','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(38,NULL,'organizar-grupos-e-subgrupos-de-produtos','Organizar produtos em grupos e subgrupos','FAZER',NULL,'## Finalidade\nGrupos e subgrupos são as gavetas do estoque: eles classificam os produtos (insumo, veterinário, peça, combustível, EPI, irrigação) para você filtrar, somar custo por categoria e achar as coisas rápido. Cadastrá-los antes deixa o cadastro de produto mais limpo e os relatórios mais úteis.\n\n## Como fazer\n1. Abra **Grupos e Subgrupos**.\n2. Em **Novo grupo**, dê o **nome** e escolha o **tipo** (insumo, veterinário, peça, EPI etc.) e salve.\n3. Dentro do grupo, crie os **subgrupos** para detalhar (ex.: grupo \"Defensivo\" → subgrupos \"Fungicida\", \"Herbicida\").\n4. Ao cadastrar um produto, selecione o grupo/subgrupo criado.\n\n## Erros comuns\n- **Escolher um tipo que não existe na lista.** O tipo é validado; use apenas os previstos (insumo, veterinário, peça, combustível, EPI, irrigação, outro).\n- **Tentar excluir um grupo em uso.** A exclusão é física; se houver produto ou subgrupo ligado, o sistema traduz o erro de vínculo numa mensagem — reclassifique os produtos antes de excluir.\n- **Criar subgrupos genéricos demais.** Subgrupo serve para separar de verdade; \"Outros\" cheio não ajuda em nada nos relatórios.\n\n## Antes e depois\nAntes: Mapear as categorias de insumo que a fazenda usa. Depois: Cadastrar os produtos apontando para o grupo e o subgrupo certos.\n\n## Roteiro do vídeo\n- Abrir Grupos e Subgrupos.\n- Criar um grupo \"Defensivo\" do tipo insumo.\n- Adicionar subgrupos \"Fungicida\" e \"Herbicida\".\n- Mostrar o grupo aparecendo no cadastro de produto.','estoque','organizar','continuo','iniciante',130,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(39,NULL,'transferir-produto-entre-almoxarifados','Transferir um produto entre almoxarifados','FAZER',NULL,'## Finalidade\nA transferência move produto de um almoxarifado para outro sem mudar o custo: gera uma saída na origem e uma entrada no destino ao mesmo custo unitário, numa única operação. O custo médio global do produto não muda — só o lugar onde ele está guardado.\n\n## Como fazer\n1. Abra **Transferências** e clique em **Nova transferência**.\n2. Escolha o **produto**, o **almoxarifado de origem**, o **de destino** e a **quantidade**.\n3. Confirme a **data** e clique em **Transferir** — origem e destino são atualizados juntos.\n4. Confira o saldo dos dois almoxarifados na tela de Produtos.\n\n## Erros comuns\n- **Origem igual ao destino.** O sistema recusa — escolha almoxarifados diferentes.\n- **Transferir mais do que há na origem.** A saída usa o lote mais próximo do vencimento (FEFO); se faltar saldo, a operação inteira é desfeita e nada muda.\n- **Ignorar o aviso de lote vencido.** Se o FEFO cair num lote vencido, é preciso marcar a confirmação explícita e reenviar — não force sem entender por que o lote está vencido.\n\n## Antes e depois\nAntes: Ter os dois almoxarifados cadastrados e saldo na origem. Depois: Conferir os saldos ou, se errou, estornar o par pela própria tela (alçada de exclusão).\n\n## Roteiro do vídeo\n- Abrir Transferências e iniciar uma nova.\n- Selecionar produto, origem, destino e quantidade.\n- Narrar \"o custo não muda, só o lugar\"; clicar em Transferir.\n- Mostrar o saldo caindo na origem e subindo no destino.','estoque','movimentar','continuo','intermediario',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(40,NULL,'tratar-alertas-de-estoque-critico','Tratar os alertas de estoque crítico','FAZER',NULL,'## Finalidade\nA tela de Alertas junta numa fila os avisos de estoque: item abaixo do mínimo e produto perto do vencimento. Eles são reemitidos automaticamente a cada movimentação enquanto a condição existir — então \"sumir da tela\" só acontece de verdade quando o problema é resolvido no estoque.\n\n## Como fazer\n1. Abra **Alertas de Estoque** e leia a fila (mínimo e vencimento).\n2. Para sinalizar que já viu e vai cuidar, clique em **Reconhecer**.\n3. Resolvida a causa (comprou, transferiu, deu baixa do vencido), clique em **Resolver**.\n4. Confira: se a condição persistir, o alerta volta na próxima movimentação — isso é esperado.\n\n## Erros comuns\n- **Resolver o alerta sem resolver a causa.** Marcar \"resolvido\" não repõe o estoque nem descarta o vencido; na primeira movimentação seguinte o alerta reaparece. Trate o estoque, não só o aviso.\n- **Confundir reconhecer com resolver.** Reconhecer é \"estou ciente\"; resolver é \"a condição acabou\". Use reconhecer quando ainda vai agir e resolver só depois de agir.\n- **Ignorar o alerta de vencimento até o produto vencer.** O aviso é justamente para você consumir, transferir ou bloquear a tempo — não deixe o lote passar do prazo.\n\n## Antes e depois\nAntes: Definir os mínimos dos produtos para os alertas fazerem sentido. Depois: Abrir uma solicitação de compra (mínimo) ou bloquear/descartar o lote (vencimento).\n\n## Roteiro do vídeo\n- Abrir Alertas com itens abaixo do mínimo e a vencer.\n- Reconhecer um alerta de mínimo; narrar \"estou ciente e vou comprar\".\n- Mostrar a ligação com a solicitação de compra.\n- Resolver um alerta e explicar por que ele pode voltar se a causa persistir.','estoque','acompanhar','continuo','iniciante',130,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(41,NULL,'acompanhar-as-despesas-pagas','Acompanhar as despesas pagas','CONSULTAR',NULL,'## Finalidade\nDespesas é a visão gerencial do que já saiu do caixa — só saídas **efetivadas** (pagas), recortadas por mês e por origem. É leitura pura: aqui você entende para onde o dinheiro foi, não faz baixa nem edita título. A manutenção dos títulos fica em Contas a Pagar.\n\n## Como fazer\n1. Abra **Despesas**. Ela mostra as saídas pagas do ano, com o gráfico por mês.\n2. Filtre por **ano, mês e origem** para focar no recorte que interessa.\n3. Clique numa **barra do mês** para saltar direto para aquele mês.\n4. Leia o **total** do recorte e, se precisar levar para fora, use **Exportar CSV** ou **Imprimir**.\n\n## Erros comuns\n- **Procurar uma despesa que ainda não foi paga.** Esta tela só mostra o que já saiu do caixa; título em aberto aparece em Contas a Pagar, não aqui.\n- **Tentar corrigir um valor por aqui.** É relatório read-only — para mexer no título, vá à tela de origem (Contas a Pagar).\n\n## Antes e depois\nAntes: Registrar as baixas em Contas a Pagar. Depois: Cruzar as saídas com o fluxo de caixa e o DRE.\n\n## Roteiro do vídeo\n- Abrir Despesas e filtrar por um mês.\n- Clicar numa barra e mostrar o recorte.\n- Exportar o CSV do período.','financeiro','acompanhar','continuo','iniciante',90,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(42,NULL,'cadastrar-um-centro-de-custo','Cadastrar um centro de custo','FAZER',NULL,'## Finalidade\nCentro de custo é o destino do gasto — para onde o custeio aponta. Mão de obra (MDO), insumos (INS), máquinas (MAQ) e irrigação (IRR) são criados automaticamente pelos módulos; aqui você cadastra o resto (administrativo, sede, projetos), para organizar os custos que não nascem dos módulos operacionais.\n\n## Como fazer\n1. Abra **Centros de Custo** e clique em **+ Novo centro**.\n2. Informe um **código** curto (vira maiúsculas automaticamente) e o **nome**.\n3. Adicione uma descrição, se ajudar a diferenciar dos demais.\n4. Clique em **Salvar**. O código precisa ser **único** — o sistema recusa duplicados.\n5. Para tirar um de circulação, **inative-o** em vez de apagar (o botão faz isso quando há custeio ligado).\n\n## Erros comuns\n- **Recriar os automáticos.** MDO, INS, MAQ e IRR aparecem sozinhos na primeira emissão de custo — não precisa cadastrá-los à mão.\n- **Repetir um código.** O código é a chave; se já existe, o sistema bloqueia. Escolha outro.\n- **Tentar excluir um centro em uso.** Se há lançamentos de custeio nele, o sistema apenas o **inativa** — o histórico é preservado.\n\n## Antes e depois\nAntes: Mapear com o cliente quais destinos de custo existem além dos módulos. Depois: Usar o centro ao classificar despesas e lançamentos.\n\n## Roteiro do vídeo\n- Abrir Centros de Custo e clicar em + Novo centro.\n- Cadastrar um centro \"ADM — Administrativo\".\n- Tentar repetir o código e mostrar o bloqueio.','financeiro','cadastrar','continuo','iniciante',110,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(43,NULL,'cadastrar-uma-conta-bancaria','Cadastrar uma conta bancária','FAZER',NULL,'## Finalidade\nAqui ficam as contas e caixas por onde o dinheiro da operação passa: conta corrente, poupança, caixa e aplicação. Cadastrá-las é o que dá base para a conciliação bancária — é contra essas contas que você vai bater o extrato do banco com o razão do sistema.\n\n## Como fazer\n1. Abra **Contas Bancárias** e clique em **+ Nova conta**.\n2. Informe o **nome** (obrigatório) e escolha o **tipo** (corrente, poupança, caixa ou aplicação).\n3. Preencha **banco, agência e conta** quando fizer sentido.\n4. Informe o **saldo inicial**, se for começar a controlar a partir de um saldo já existente.\n5. Clique em **Salvar**. A conta fica disponível na conciliação bancária.\n\n## Erros comuns\n- **Deixar o nome vazio.** O nome é o único campo obrigatório — é como a conta aparece na conciliação. Sem ele, o sistema recusa.\n- **Errar o saldo inicial.** Ele é o ponto de partida do controle; um saldo inicial errado empurra toda a conciliação. Confira com o extrato antes.\n- **Tentar excluir uma conta já conciliada.** O sistema apenas a **inativa** para preservar as conciliações feitas — não some com o histórico.\n\n## Antes e depois\nAntes: Levantar as contas e caixas reais da operação. Depois: Conciliar o extrato de cada conta contra o razão pago.\n\n## Roteiro do vídeo\n- Abrir Contas Bancárias e clicar em + Nova conta.\n- Cadastrar uma conta corrente com saldo inicial.\n- Mostrar a conta aparecendo na lista da conciliação.','financeiro','cadastrar','continuo','iniciante',100,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(44,NULL,'conciliar-o-extrato-bancario','Conciliar o extrato bancário','FAZER',NULL,'## Finalidade\nConciliar é bater o saldo do extrato do banco contra o saldo que o sistema calcula a partir do que foi pago e recebido no período. Se os dois batem, o razão está fiel ao banco; se divergem, a conciliação **sinaliza** a diferença para você caçar o lançamento que falta ou sobra.\n\n## Como fazer\n1. Abra **Conciliação Bancária** e inicie uma nova conciliação.\n2. Escolha a **conta bancária** e o **período** (início e fim).\n3. Informe o **saldo do extrato** naquele período, copiado do banco.\n4. Confirme — o VERO calcula sozinho o **saldo do sistema** (movimentações pagas no período) e compara.\n5. Leia o resultado: **conciliada** quando bate, **divergente** quando não — e a diferença aparece em reais para você investigar.\n\n## Erros comuns\n- **Período do extrato diferente do período informado.** O saldo do sistema é calculado exatamente pelas datas que você digitou — use o mesmo intervalo do extrato, senão vai divergir por recorte, não por erro real.\n- **Divergiu e parar por aí.** Divergente não é o fim: é o convite para achar o lançamento faltante. Confira baixas não registradas ou datas de pagamento erradas.\n- **Digitar o saldo do extrato com sinal ou vírgula trocados.** Um saldo mal digitado gera divergência fantasma — confira o valor antes de confirmar.\n\n## Antes e depois\nAntes: Cadastrar a conta bancária e registrar as baixas do período. Depois: Corrigir o que divergiu e refazer a conciliação até bater.\n\n## Roteiro do vídeo\n- Abrir Conciliação Bancária e iniciar uma nova.\n- Escolher conta e período, digitar o saldo do extrato.\n- Confirmar e mostrar o resultado batendo (conciliada) e um caso divergente.','financeiro','conciliar','continuo','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(45,NULL,'lancar-uma-conta-a-receber','Lançar uma conta a receber','FAZER',NULL,'## Finalidade\nUma conta a receber é um valor que a operação tem para entrar — uma venda a prazo, um acerto, um reembolso. Lançá-la coloca o título no razão de recebíveis e o joga na projeção do fluxo de caixa. Vendas já geram recebíveis sozinhas; use o lançamento manual para o que não veio de uma venda.\n\n## Como fazer\n1. Abra **Contas a Receber** e clique em **+ Novo lançamento**.\n2. Preencha **descrição** e **valor** (maior que zero).\n3. Informe a **data de vencimento** — ela é obrigatória no lançamento novo.\n4. Se quiser, classifique o título (centro de custo, plano de contas, safra) e defina **parcelas**.\n5. Clique em **Salvar**. O título entra como **aberto** e passa a contar na projeção do fluxo de caixa.\n\n## Erros comuns\n- **Salvar sem vencimento.** O sistema exige vencimento no título novo — sem ele, o valor cairia no bucket \"Sem vencimento\" e sumiria da projeção mensal do fluxo.\n- **Lançar à mão um recebível que já veio da venda.** Vendas geram recebíveis automaticamente; lançar de novo duplica o valor. O manual é só para o que não tem venda de origem.\n- **Misturar parcelamento com rateio.** Os dois juntos não são suportados — escolha lançar em parcelas OU ratear entre centros, não os dois.\n\n## Antes e depois\nAntes: Ter o acerto ou a cobrança que originou o valor a receber. Depois: Receber o título quando o dinheiro entrar.\n\n## Roteiro do vídeo\n- Abrir Contas a Receber e clicar em + Novo lançamento.\n- Preencher descrição, valor e vencimento.\n- Salvar e mostrar o título entrando como \"aberto\".\n- Cortar para o fluxo de caixa mostrando o valor na projeção.','financeiro','lancar','continuo','iniciante',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(46,NULL,'ler-o-fluxo-de-caixa','Ler o fluxo de caixa','CONSULTAR',NULL,'## Finalidade\nO fluxo de caixa mostra o dinheiro entrando e saindo ao longo do ano em duas camadas: o **realizado** (o que já foi pago e recebido, por data de pagamento) e o **previsto** (títulos em aberto, por data de vencimento). É a leitura que responde \"vou ter caixa nos próximos meses?\".\n\n## Como fazer\n1. Abra **Fluxo de Caixa** e escolha o **ano**.\n2. Leia os KPIs no topo e os gráficos de entradas e saídas por mês.\n3. Distinga as duas camadas: **realizado** vem das baixas; **previsto** vem dos títulos em aberto pelo vencimento.\n4. Confira o bucket **Sem vencimento** — títulos abertos sem data caem ali e ficam de fora da projeção mensal até ganharem vencimento.\n\n## Erros comuns\n- **Achar que previsto é dinheiro garantido.** Previsto é só título em aberto pelo vencimento — só vira caixa quando é baixado. Trate como projeção, não como saldo.\n- **Ignorar o \"Sem vencimento\".** Título aberto sem vencimento não entra na projeção do mês; dê vencimento a ele na tela de origem para que apareça no fluxo.\n\n## Antes e depois\nAntes: Lançar e baixar os títulos que alimentam o fluxo. Depois: Decidir compras e pagamentos com base na projeção de caixa.\n\n## Roteiro do vídeo\n- Abrir Fluxo de Caixa e trocar o ano.\n- Narrar a diferença entre realizado e previsto nos gráficos.\n- Apontar o bucket Sem vencimento e explicar por que ele fica fora da projeção.','financeiro','ler','continuo','iniciante',110,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(47,NULL,'montar-o-plano-de-contas','Montar o plano de contas','FAZER',NULL,'## Finalidade\nO plano de contas é a árvore que classifica cada valor como receita ou despesa e o organiza em grupos e subgrupos. É ele que dá nome ao dinheiro nos relatórios financeiros e no DRE. Contas-pai agrupam; as contas-folha (as pontas da árvore) são as que **aceitam lançamento**.\n\n## Como fazer\n1. Abra **Plano de Contas** e clique em **+ Nova conta**.\n2. Informe **código** e **nome** e escolha o **tipo** (receita ou despesa).\n3. Para criar uma subconta, escolha a **conta pai** — o nível é calculado sozinho e o **tipo é herdado do pai**.\n4. Marque **aceita lançamento** nas contas-folha; deixe desmarcado nas que só agrupam.\n5. Clique em **Salvar**. O código precisa ser **único** em todo o plano.\n\n## Erros comuns\n- **Lançar em conta que só agrupa.** Contas-pai servem para somar; quem recebe valor é a folha. Deixe \"aceita lançamento\" só nas pontas.\n- **Repetir código.** O código é a chave da conta — se já existe, o sistema recusa.\n- **Tentar excluir uma conta com filhas ou lançamentos.** O sistema não apaga: ele **inativa**, para não quebrar o histórico nem os relatórios.\n\n## Antes e depois\nAntes: Definir com o cliente a estrutura de receitas e despesas. Depois: Classificar despesas e recebíveis usando as contas-folha.\n\n## Roteiro do vídeo\n- Abrir Plano de Contas e criar uma conta-pai \"Despesas operacionais\".\n- Criar uma subconta-folha e mostrar o tipo herdado e o nível calculado.\n- Tentar excluir a conta-pai e mostrar que ela é inativada, não apagada.','financeiro','estruturar','continuo','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(48,NULL,'receber-um-titulo','Receber um título para registrar a entrada','FAZER',NULL,'## Finalidade\nReceber um título é dar baixa num recebível — registrar que o dinheiro entrou. É o gêmeo do baixar em Contas a Pagar: fecha o ciclo do lado das entradas e faz o valor virar caixa efetivo no fluxo. Enquanto o título fica \"aberto\", ele é só uma entrada prevista.\n\n## Como fazer\n1. Abra **Contas a Receber** e localize o título **em aberto** que foi pago.\n2. Clique em **Baixar** na linha do título.\n3. Informe a **data do recebimento** e a **forma** (dinheiro, PIX, transferência…).\n4. Confirme — este é o passo que **registra a entrada e joga o valor no caixa efetivo** do fluxo.\n5. Se o título veio de uma venda, a baixa também **marca a venda como paga**; confira que o status virou \"pago\".\n\n## Erros comuns\n- **Receber com a data errada.** O valor entra no caixa no dia errado e distorce o saldo do período. Use a data real em que o dinheiro caiu, não a de hoje.\n- **Baixar o título errado.** Confira descrição e valor antes de confirmar — a baixa quita aquele recebível específico.\n- **Recebeu por engano?** Use **Estornar** para o título voltar a ficar aberto; não crie um lançamento novo para \"compensar\".\n\n## Antes e depois\nAntes: Ter o recebível lançado (ou gerado por uma venda). Depois: Conferir o fluxo de caixa com a entrada já efetivada.\n\n## Roteiro do vídeo\n- Abrir Contas a Receber com um título em aberto.\n- Clicar em Baixar, preencher data e forma do recebimento.\n- Confirmar e mostrar o título virando \"pago\".\n- Mostrar o estorno reabrindo o título, para o caso de erro.','financeiro','receber','continuo','iniciante',140,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(49,NULL,'lancar-no-livro-caixa','Lançar no livro caixa do produtor a partir do razão pago','FAZER',NULL,'## Finalidade\nO livro caixa do produtor reúne entradas e saídas com saldo corrente, base para a atividade rural. Além do lançamento manual, ele pode ser gerado a partir do razão já pago do período — sem duplicar o que já foi lançado. A apuração oficial (IRPF da atividade rural) continua sendo da contabilidade.\n\n## Como fazer\n1. Abra **Livro caixa**.\n2. Para um lançamento avulso: informe **data**, **histórico**, **tipo** (entrada ou saída) e **valor** (maior que zero) e clique em **Salvar**.\n3. Para trazer do financeiro: use **Gerar do razão** e informe o **período** (início e fim).\n4. O sistema cria um lançamento para cada movimentação **paga** do período; o que já foi gerado antes é **pulado** (não duplica).\n5. Confira o **saldo corrente** e imprima o livro quando precisar.\n\n## Erros comuns\n- **Gerar o mesmo período duas vezes.** Não há problema: a geração é idempotente e marca cada lançamento com a origem do razão. Ela avisa quantos foram criados e quantos já existiam.\n- **Esperar movimentação não paga aparecer.** A geração só traz o que está **pago** no período. Baixe os títulos no financeiro antes de gerar.\n- **Confundir o livro com a apuração fiscal.** Esta tela organiza entradas e saídas; a apuração oficial do IRPF rural é feita pela contabilidade a partir daqui.\n\n## Antes e depois\nAntes: ter as movimentações do período pagas no financeiro. Depois: conferir o saldo e entregar o livro à contabilidade.\n\n## Roteiro do vídeo\n- Abrir Livro caixa com saldo corrente à mostra.\n- Narrar: \"O livro reúne entradas e saídas — e boa parte dele vem pronto do razão que você já pagou.\"\n- Usar Gerar do razão informando o mês.\n- Mostrar a mensagem de quantos foram criados e quantos já existiam.\n- Fechar no saldo atualizado.','fiscal','registrar','continuo','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(50,NULL,'lancar-um-documento-fiscal','Lançar um documento fiscal para completar o acervo','FAZER',NULL,'## Finalidade\nA tela de Documentos Fiscais é a central do acervo: reúne NF-e, NFC-e, CT-e e outros documentos com filtros, detalhe e anexos. O registro manual serve para incluir um documento que não veio por importação de XML, deixando o acervo completo para a contabilidade.\n\n## Como fazer\n1. Abra **Documentos** e clique em **Registrar documento**.\n2. Escolha o **tipo** (NF-e, NFC-e, CT-e ou Outro) e informe o **número** e o **valor** (obrigatórios).\n3. Se tiver a **chave de acesso**, cole os 44 dígitos — o sistema evita duplicidade por chave.\n4. Informe o **fornecedor** e a **data de emissão** quando fizer sentido.\n5. Clique em **Salvar** — o documento entra no acervo e pode ser detalhado, anexado ou recusado depois.\n\n## Erros comuns\n- **Digitar chave inválida.** A chave deve ter 44 dígitos (ou ficar em branco); e não pode repetir uma já existente no acervo. Cole direto do documento.\n- **Usar esta tela para importar XML.** Importação de NF-e por arquivo fica na tela de Importação de NF-e; a conciliação, na tela própria. Aqui é registro manual e gestão do acervo.\n- **Excluir um documento errado.** Para tirar um documento do fluxo, use **Recusar** (a linha é preservada) e **Reativar** se precisar voltar — não apague o histórico.\n\n## Antes e depois\nAntes: ter o documento em mãos (número, valor e, de preferência, a chave). Depois: conciliar e acompanhar o acervo fiscal do período.\n\n## Roteiro do vídeo\n- Abrir Documentos com os filtros e a lista do acervo.\n- Narrar: \"Esta é a central de tudo que é documento fiscal — e dá para lançar na mão o que não veio por XML.\"\n- Registrar um documento tipo Outro com número e valor.\n- Mostrar o detalhe e a opção Recusar preservando a linha.','fiscal','registrar','continuo','intermediario',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(51,NULL,'registrar-um-receituario-agronomico','Registrar um receituário agronômico e anexar a prescrição','FAZER',NULL,'## Finalidade\nO receituário agronômico é a prescrição emitida pelo responsável técnico que autoriza a aplicação de defensivos — exigência legal. O VERO **não recomenda** produto, dose ou carência: esta tela apenas **arquiva** o documento emitido pelo RT e o vincula à aplicação, mantendo a rastreabilidade e o cumprimento fiscal/ambiental.\n\n## Como fazer\n1. Abra **Receituários** (no módulo MIP) e clique em **Novo receituário**.\n2. Informe o **número** do receituário (obrigatório e único).\n3. Vincule a **aplicação** correspondente e o **responsável técnico** que emitiu (quando aplicável).\n4. Preencha a **data de emissão** e a **validade**, e clique em **Salvar**.\n5. Com o receituário salvo, **anexe o documento** (PDF, JPG ou PNG) — é o arquivo que comprova a prescrição.\n\n## Erros comuns\n- **Repetir o número do receituário.** Cada receituário tem número único no sistema; um número já usado é barrado.\n- **Vincular a uma aplicação cancelada.** Só é aceita aplicação válida e não cancelada. Confirme a aplicação antes de salvar.\n- **Salvar e esquecer de anexar o PDF.** O receituário sem o documento anexado não comprova a prescrição — anexe logo após salvar.\n- **Esperar que o sistema sugira produto ou dose.** Ele nunca recomenda nada: a prescrição é responsabilidade do agrônomo e aqui só se arquiva.\n\n## Antes e depois\nAntes: o RT emitir a prescrição e a aplicação estar registrada. Depois: a aplicação fica com o receituário vinculado e o documento anexado para auditoria.\n\n## Roteiro do vídeo\n- Abrir Receituários no módulo MIP.\n- Narrar: \"O sistema não receita nada — quem receita é o agrônomo. Aqui a gente guarda e liga à aplicação.\"\n- Criar receituário com número, aplicação e RT.\n- Salvar e anexar o PDF da prescrição.\n- Mostrar o vínculo do receituário com a aplicação.','fiscal','registrar','safra','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(52,NULL,'registrar-uma-nfe-emitida','Registrar uma NF-e emitida para guardar no acervo fiscal','FAZER',NULL,'## Finalidade\nHoje a emissão integrada à SEFAZ está fora do escopo. Esta tela **registra** a nota que você emitiu por fora (no emissor gratuito da SEFAZ ou no sistema do contador) e a guarda no acervo fiscal com número, chave, valor e o XML — mantendo o histórico completo sem depender de certificado.\n\n## Como fazer\n1. Abra **Emissão de NF-e** e vá ao bloco **Registrar nota emitida**.\n2. Escolha o **tipo** (NF-e ou NFC-e) e informe o **número** e o **valor** da nota (obrigatórios).\n3. Cole a **chave de acesso** (44 dígitos) — opcional, mas recomendado para evitar duplicidade.\n4. Confirme a **data de emissão** e anexe o **XML autorizado** (opcional, mas recomendado).\n5. Clique em **Registrar nota** — ela entra no acervo fiscal.\n\n## Erros comuns\n- **Confundir esta tela com emissão real.** Ela não transmite nada à SEFAZ. A emissão integrada exige certificado digital A1, credenciamento e homologação, que não fazem parte do go-live. Emita a nota por fora e registre aqui.\n- **Digitar a chave com quantidade errada de dígitos.** A chave precisa ter exatamente 44 dígitos (ou ficar em branco). Cole direto do XML para não errar.\n- **Registrar a mesma nota duas vezes.** Se a chave já existir no acervo, o sistema barra — não force um número diferente para \"passar\".\n\n## Antes e depois\nAntes: emitir a nota no emissor gratuito da SEFAZ ou no contador e ter o XML em mãos. Depois: acompanhar a nota no acervo em Documentos Fiscais.\n\n## Roteiro do vídeo\n- Abrir Emissão de NF-e mostrando o aviso de \"como funciona hoje\".\n- Narrar: \"Aqui a gente registra a nota que já foi emitida por fora — o VERO guarda tudo no acervo.\"\n- Preencher tipo, número, valor e colar a chave de 44 dígitos.\n- Anexar o XML e clicar em Registrar nota.\n- Mostrar a nota entrando na lista do acervo.','fiscal','registrar','continuo','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(53,NULL,'cadastrar-pivo','Cadastrar um pivô ou sistema de irrigação','FAZER',NULL,'## Finalidade\nO pivô (ou sistema de irrigação) é a máquina de água da fazenda. Cadastrá-lo dá ao VERO onde pendurar os apontamentos e planejamentos de rega e mostra o pulso dos últimos 30 dias (horas, lâmina, consumos). É o cadastro-base para acompanhar a irrigação por equipamento.\n\n## Como fazer\n1. Na tela de **Pivôs e Sistemas de Irrigação**, clique em **+ Novo pivô**.\n2. Informe o **nome** do pivô/sistema — é o único campo obrigatório.\n3. Escolha a **fazenda** e informe a **área (ha)** atendida.\n4. Clique em **Salvar**. O pivô passa a aparecer no painel com seus KPIs de 30 dias.\n\n## Erros comuns\n- **Salvar sem nome.** O nome é obrigatório — sem ele o cadastro é recusado.\n- **Tentar excluir um pivô em uso.** Se o pivô já tem apontamentos ou planejamentos, a exclusão é bloqueada. Deixe-o cadastrado ou remova os lançamentos primeiro.\n- **Duplicar o mesmo sistema.** Antes de criar, confira a lista — pivôs repetidos dividem o histórico e bagunçam os KPIs.\n\n## Antes e depois\nAntes: Ter a fazenda cadastrada. Depois: Registrar apontamentos de irrigação e planejar a lâmina por esse pivô.\n\n## Roteiro do vídeo\n- Abrir o painel de Pivôs e clicar em + Novo pivô.\n- Preencher nome, fazenda e área; salvar.\n- Mostrar o pivô novo na lista com os KPIs de 30 dias zerados.','irrigacao','cadastrar','continuo','iniciante',120,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(54,NULL,'consultar-consumo-de-agua-e-energia','Consultar o consumo de água e energia da irrigação','CONSULTAR',NULL,'## Finalidade\nEstas telas consolidam quanto de água (m³) e energia (kWh) a irrigação gastou — por lançamento, por válvula e por mês —, com o custo. São de leitura: o número nasce nos apontamentos de irrigação. Servem para acompanhar consumo, comparar válvulas e entender o custo da água na safra.\n\n## Como fazer\n1. Abra **Consumo de Água** (ou **Consumo de Energia**) e filtre por válvula e período.\n2. Leia o detalhe por lançamento e a consolidação por válvula e por mês.\n3. Observe o selo de custo: **auto** significa que o valor bate com a tarifa vigente; **manual** significa que foi digitado ou lançado antes da tarifa.\n4. Se um consumo esperado não aparece, verifique se o apontamento de origem foi salvo com a quantidade.\n\n## Antes e depois\nAntes: Registrar os apontamentos de irrigação com os consumos. Depois: Cruzar o custo com o Custo Realizado da safra.\n\n## Roteiro do vídeo\n- Abrir Consumo de Água, filtrar por válvula e período.\n- Narrar a leitura do detalhe e da consolidação por mês.\n- Explicar o selo auto × manual e sua ligação com a tarifa.','irrigacao','consultar','safra','iniciante',110,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(55,NULL,'definir-tarifas-de-irrigacao','Definir as tarifas de água e energia da irrigação','FAZER',NULL,'## Finalidade\nA tarifa é o preço do m³ de água (do Vale) e do kWh de energia. Cadastrada uma vez, ela faz o custo dos apontamentos de irrigação sair sozinho: você lança só a quantidade e o VERO multiplica pela tarifa. Sem tarifa, ou você digita o custo em cada apontamento, ou ele fica em zero.\n\n## Como fazer\n1. Na tela de **Apontamentos de Irrigação**, abra o bloco de **tarifas**.\n2. Informe a **tarifa de água (R$/m³)** e a **tarifa de energia (R$/kWh)**.\n3. Clique em **Gravar tarifas**.\n4. A partir daí, todo apontamento novo com quantidade e custo em branco calcula o custo automaticamente (quantidade × tarifa).\n\n## Erros comuns\n- **Tarifa negativa.** O sistema recusa — tarifa é sempre zero ou positiva.\n- **Achar que corrige o passado.** A tarifa vale para os apontamentos novos; os já lançados mantêm o custo que tinham. Reabra e salve o apontamento antigo se quiser recalcular.\n- **Deixar a tarifa vazia.** Sem tarifa, o custo automático não acontece — você terá que digitar o custo em cada apontamento.\n\n## Antes e depois\nAntes: Ter os valores atuais de R$/m³ (Vale) e R$/kWh em mãos. Depois: Registrar os apontamentos de irrigação com o custo saindo automático.\n\n## Roteiro do vídeo\n- Abrir Apontamentos de Irrigação e o bloco de tarifas.\n- Preencher R$/m³ e R$/kWh, gravar.\n- Criar um apontamento deixando o custo vazio e mostrar o valor calculado sozinho.','irrigacao','definir','continuo','intermediario',120,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(56,NULL,'planejar-irrigacao','Planejar a lâmina de irrigação de uma válvula','FAZER',NULL,'## Finalidade\nO planejamento define a lâmina-alvo (mm) que uma válvula deve receber em um período. É a meta contra a qual o realizado será confrontado em Planejado vs Realizado. A lâmina é decisão do responsável — o sistema não recomenda valores, só guarda o que você definir.\n\n## Como fazer\n1. Escolha a **válvula** e informe a **lâmina-alvo (mm)** — precisa ser maior que zero.\n2. Defina o **início** (obrigatório) e, se houver, o **fim** do período.\n3. Se quiser controlar a captação, informe as **horas de irrigação** e a **vazão (m³/h)** — ao escolher a válvula, a vazão da bomba é sugerida, e você pode ajustar.\n4. Escolha o **pivô** vinculado, se aplicável.\n5. Clique em **Salvar**. O planejamento passa a ser a régua do confronto planejado × realizado.\n\n## Erros comuns\n- **Lâmina zero ou início em branco.** O salvamento é recusado — válvula, lâmina maior que zero e início são obrigatórios.\n- **Fim antes do início.** O sistema não aceita período invertido; confira as datas.\n- **Vazão ou horas negativas.** Não são aceitas. A vazão sugerida vem da bomba da válvula — só ajuste se souber o valor real.\n\n## Antes e depois\nAntes: Ter as válvulas e o pivô cadastrados. Depois: Registrar os apontamentos e acompanhar o desvio em Planejado vs Realizado.\n\n## Roteiro do vídeo\n- Abrir Planejamento de Irrigação e criar um plano.\n- Escolher a válvula e mostrar a vazão da bomba sendo sugerida.\n- Preencher lâmina-alvo e período; salvar.\n- Apontar onde o realizado vai ser confrontado.','irrigacao','planejar','safra','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(57,NULL,'registrar-apontamento-de-irrigacao','Registrar um apontamento de irrigação com água e energia','FAZER',NULL,'## Finalidade\nO apontamento de irrigação é o que transforma a rega do dia em número e em custo. Você lança por válvula e data as horas e a lâmina, mais o consumo de água (m³) e energia (kWh). Cada consumo com custo vira lançamento no custeio, amarrado à válvula e à safra — é assim que a irrigação entra na conta da lavoura.\n\n## Como fazer\n1. Escolha a **válvula** e a **data** — os dois são obrigatórios.\n2. Informe as **horas** irrigadas e a **lâmina (mm)** aplicada.\n3. Lance o **consumo de água (m³)** e/ou **energia (kWh)**. Se deixar o custo em branco e houver tarifa cadastrada, o VERO calcula sozinho (quantidade × tarifa).\n4. Se o apontamento pertence a uma safra, confirme o **vínculo de safra** — o custo é rateado nela.\n5. Clique em **Salvar**: o consumo com custo gera o lançamento no custeio (categoria irrigação).\n\n## Erros comuns\n- **Válvula ou data em branco.** O salvamento é recusado — sem esses dois o apontamento não existe.\n- **Safra fechada.** Se a safra vinculada já foi encerrada, o custeio não aceita o lançamento; o sistema avisa e bloqueia. Aponte na safra correta.\n- **Digitar custo e ter tarifa.** O custo digitado prevalece sobre a tarifa automática — se digitar errado, é ele que vale. Deixe em branco para o cálculo automático.\n\n## Antes e depois\nAntes: Definir as tarifas (R$/m³ e R$/kWh) para o custo sair automático. Depois: Conferir o Consumo de Água e Energia e o Custo Realizado da safra.\n\n## Roteiro do vídeo\n- Abrir Apontamentos de Irrigação e iniciar um novo.\n- Preencher válvula, data, horas, lâmina.\n- Lançar água em m³ deixando o custo vazio; narrar o cálculo automático pela tarifa.\n- Salvar e mostrar o valor lançado no custeio.','irrigacao','registrar','safra','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(58,NULL,'cadastrar-maquina','Cadastrar uma máquina da frota','FAZER',NULL,'## Finalidade\nA máquina é o cadastro-base de tudo em Máquinas: sem ela não há horímetro, abastecimento, manutenção nem custo por hora. Aqui você registra trator, colheitadeira, pulverizador, bandejão e afins, com o horímetro atual, o custo/hora e os dados de depreciação que alimentam o custeio.\n\n## Como fazer\n1. Clique em **+ Nova máquina** e informe **código**, **nome** e **tipo** — os três são obrigatórios.\n2. Escolha a **fazenda**, a **marca**, o **modelo** e o **ano**.\n3. Informe o **horímetro atual** e o **custo/hora** (usados no custo das operações).\n4. Se for controlar depreciação, preencha **valor de aquisição**, **valor residual** e **vida útil (horas)**; para máquinas com tanque, a **capacidade do tanque (L)**.\n5. Defina o **operador padrão** e o **status** (ativa, em manutenção, inativa) e clique em **Salvar**.\n\n## Erros comuns\n- **Código repetido.** Cada máquina tem um código único no tenant; o sistema recusa duplicado. Use uma numeração clara (TR-01, CO-02...).\n- **Valores negativos.** Horímetro, custo/hora, valores e capacidade não podem ser negativos — o salvamento é bloqueado.\n- **Tipo em branco ou inválido.** O tipo tem que ser um da lista (trator, colheitadeira, pulverizador...); sem ele o cadastro não salva.\n\n## Antes e depois\nAntes: Ter a fazenda cadastrada. Depois: Registrar leituras de horímetro, abastecimentos e planos de manutenção da máquina.\n\n## Roteiro do vídeo\n- Abrir Cadastro de Máquinas e clicar em + Nova máquina.\n- Preencher código, nome, tipo; mostrar a recusa de código duplicado.\n- Completar horímetro, custo/hora e depreciação; salvar.','maquinas','cadastrar','continuo','iniciante',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(59,NULL,'criar-plano-de-manutencao','Criar um plano de manutenção preventiva','FAZER',NULL,'## Finalidade\nO plano preventivo é o lembrete automático da manutenção: \"troca de óleo a cada 250 horas\" ou \"revisão a cada 90 dias\". Com o plano criado, o VERO dispara alertas conforme as leituras de horímetro e o calendário — vence o que chegar primeiro. É o que evita a manutenção esquecida.\n\n## Como fazer\n1. Escolha a **máquina** e escreva a **descrição** do plano (o que será feito).\n2. Informe o **intervalo em horas** de horímetro **e/ou** em **dias** — pelo menos um dos dois, e o que vencer primeiro dispara o alerta.\n3. Ajuste a **antecedência** (com quantas horas/dias antes o alerta aparece).\n4. Se já houve execução, informe o **horímetro** e a **data da última** para o plano contar a partir dali.\n5. Clique em **Salvar**. O alerta passa a disparar na antecedência configurada.\n\n## Erros comuns\n- **Não informar nenhum intervalo.** Sem horas nem dias o plano não sabe quando vencer — informe pelo menos um.\n- **Antecedência ou horímetro negativos.** Não são aceitos; use zero ou valor positivo.\n- **Esquecer da leitura de horímetro.** O alerta por horas só dispara se as leituras estiverem em dia. Mantenha o horímetro atualizado.\n\n## Antes e depois\nAntes: Ter a máquina cadastrada. Depois: Registrar as ordens de manutenção quando o alerta disparar — vinculadas a este plano.\n\n## Roteiro do vídeo\n- Abrir Planos de Manutenção e criar um.\n- Preencher máquina, descrição e intervalo em horas; narrar o \"vence o primeiro\".\n- Ajustar antecedência e a última execução; salvar.\n- Mostrar o alerta sendo previsto pelo horímetro atual.','maquinas','cadastrar','continuo','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(60,NULL,'lancar-abastecimento','Lançar um abastecimento de combustível','FAZER',NULL,'## Finalidade\nCada abastecimento é combustível que entra na máquina e custo que entra na safra. Ao lançar litros e valor, o VERO joga o gasto no custeio (categoria máquinas) e, se você informar o horímetro do momento, atualiza o horímetro da máquina de quebra. É a base do custo de combustível da frota.\n\n## Como fazer\n1. Escolha a **máquina** e a **data** do abastecimento.\n2. Informe os **litros** e o **valor total** pagos — os dois são obrigatórios.\n3. Se anotou, informe o **horímetro** no momento do abastecimento (ajuda a acompanhar o consumo por hora).\n4. Clique em **Salvar**: o valor vira lançamento no custeio e, se houver horímetro, a máquina é atualizada.\n\n## Erros comuns\n- **Litros ou valor zerados.** Litros precisam ser maiores que zero e o valor não pode ser negativo — o salvamento é recusado.\n- **Horímetro menor que o atual.** Se o horímetro informado for menor que o da máquina, o sistema recusa (o horímetro não regride). Confira o número no painel da máquina.\n- **Esquecer o horímetro.** É opcional, mas sem ele você perde o consumo por hora — anote sempre que der.\n\n## Antes e depois\nAntes: Ter a máquina cadastrada. Depois: O custo aparece no Custo Realizado (categoria máquinas) e o consumo alimenta a ficha da máquina.\n\n## Roteiro do vídeo\n- Abrir Abastecimentos e iniciar um lançamento.\n- Preencher máquina, data, litros e valor.\n- Informar o horímetro e narrar que ele atualiza a máquina.\n- Salvar e mostrar o custo lançado no custeio.','maquinas','registrar','continuo','iniciante',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(61,NULL,'registrar-leitura-de-horimetro','Registrar uma leitura de horímetro','FAZER',NULL,'## Finalidade\nO horímetro é o relógio de horas de trabalho da máquina. Registrar a leitura mantém o horímetro atual em dia e é o que dispara os alertas dos planos de manutenção preventiva — a troca de óleo a cada X horas só avisa se as leituras estiverem em dia.\n\n## Como fazer\n1. Escolha a **máquina** e informe a **leitura** do horímetro (em horas).\n2. Confirme a **data da leitura** (por padrão, hoje).\n3. Clique em **Registrar**. O sistema atualiza o horímetro atual da máquina e reavalia os alertas dos planos preventivos.\n4. Confira a lista: a nova leitura entra no histórico e o horímetro atual passa a refletir o valor informado.\n\n## Erros comuns\n- **Leitura menor que o horímetro atual.** O horímetro não regride — o sistema recusa. Se digitou errado, corrija; a leitura sempre avança.\n- **Registrar na máquina errada.** A leitura vai para o histórico da máquina escolhida e mexe nos alertas dela. Confira antes de confirmar.\n- **Deixar leituras atrasadas.** Sem leituras em dia, os alertas de manutenção preventiva não disparam na hora certa. Registre com regularidade.\n\n## Antes e depois\nAntes: Ter a máquina cadastrada. Depois: Os planos de manutenção preventiva passam a avisar quando o intervalo de horas está próximo.\n\n## Roteiro do vídeo\n- Abrir Horímetro e escolher uma máquina.\n- Digitar uma leitura menor que a atual e mostrar a recusa (não regride).\n- Corrigir para um valor maior, registrar, mostrar o horímetro atualizado e o alerta reavaliado.','maquinas','registrar','continuo','iniciante',130,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(62,NULL,'registrar-manutencao-preventiva','Registrar uma ordem de manutenção e executá-la','FAZER',NULL,'## Finalidade\nA ordem de manutenção (OS) registra o que foi feito na máquina: peças trocadas e serviços contratados. Quando você marca a OS como executada, o VERO baixa as peças do estoque ao custo real, consolida o custo da ordem e lança tudo no custeio (categoria máquinas). É o elo entre manutenção, estoque e custo.\n\n## Como fazer\n1. Escolha a **máquina**, o **tipo** e a **data** da manutenção. Se ela nasce de um plano, vincule o **plano**.\n2. Lance os **itens**: para peça, escolha o produto e a quantidade; para serviço, descreva e informe o valor.\n3. Informe o **horímetro** da máquina no momento (atualiza a máquina se avançar) e o **fornecedor**, se houver.\n4. Defina o **status**. Deixe **aberta** para uma OS planejada; marque **executada** quando o serviço foi de fato feito.\n5. Clique em **Salvar**. Na execução, as peças saem do estoque e o custo entra no custeio.\n\n## Erros comuns\n- **Editar uma OS já executada.** Não é permitido — para corrigir, você cancela a OS (o cancelamento estorna as peças e o custeio) e cria outra.\n- **Peça de lote vencido.** Se a baixa pegar um lote vencido, o sistema segura e pede confirmação; marque \"confirmo usar peça de lote vencido\" e reenvie, ou troque o lote.\n- **Custo negativo.** O custo da manutenção não pode ser negativo — o salvamento é bloqueado.\n\n## Antes e depois\nAntes: Ter o plano preventivo e as peças no estoque. Depois: Ver o custo no Custo Realizado e o horímetro/plano reprogramados.\n\n## Roteiro do vídeo\n- Abrir Manutenções e criar uma OS aberta com um item de peça.\n- Narrar a diferença entre aberta e executada.\n- Marcar executada e mostrar a peça baixando do estoque + o custo no custeio.\n- Mostrar que a OS executada não edita — só cancela.','maquinas','registrar','continuo','intermediario',175,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(63,NULL,'arquivar-receituario-agronomico','Registrar um receituário agronômico e anexar o documento','FAZER',NULL,'## Finalidade\nO receituário é a prescrição emitida pelo responsável técnico. Aqui você só arquiva o documento e o liga à aplicação — o sistema nunca recomenda produto, dose ou carência (Regra 1). É o registro que dá respaldo legal e rastreabilidade à pulverização, guardando o PDF ou a foto do papel original.\n\n## Como fazer\n1. Abra **Receituários** e clique em novo receituário.\n2. Informe o **número** do receituário (obrigatório e único) e a data de emissão.\n3. Se quiser, ligue à **aplicação** correspondente e a quem emitiu; informe a validade.\n4. Clique em **Salvar** — o receituário fica registrado e liberado para receber o anexo.\n5. No receituário salvo, escolha o arquivo (PDF, JPG ou PNG dentro do limite) e clique em **Anexar** — este é o passo que guarda o documento original.\n\n## Erros comuns\n- **Salvar sem o número.** O número do receituário é obrigatório e não pode repetir. Se já existir, o sistema avisa e não grava o duplicado.\n- **Tentar anexar antes de salvar.** O anexo só entra depois que o receituário existe. Salve primeiro; o campo de anexo aparece em seguida.\n- **Enviar um arquivo fora do formato ou grande demais.** Só PDF, JPG e PNG dentro do limite são aceitos, e o conteúdo precisa bater com um PDF/imagem real. Envie o arquivo original, não uma cópia convertida.\n\n## Antes e depois\nAntes: O RT emite o receituário e a OS de pulverização. Depois: Validar a aplicação ligada, com o documento arquivado dando respaldo.\n\n## Roteiro do vídeo\n- Abrir Receituários mostrando a lista existente.\n- Criar um novo, preencher número e data e narrar que o número não pode repetir.\n- Clicar em **Salvar** e mostrar o campo de anexo surgindo.\n- Selecionar um PDF e clicar em **Anexar**.\n- Mostrar o documento anexado na ficha do receituário.','mip','arquivar','safra','iniciante',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(64,NULL,'cadastrar-alvo-de-controle','Cadastrar um alvo de controle com nível de ação','FAZER',NULL,'## Finalidade\nO alvo de controle é o catálogo de pragas, doenças e plantas daninhas que você monitora. O que dá vida a ele é o nível de ação: o limiar que, atingido no monitoramento, dispara o alerta fitossanitário. Sem cadastrar o alvo e seu nível, o monitoramento não tem contra o que comparar a leitura.\n\n## Como fazer\n1. Abra **Alvos de Controle** e clique em novo alvo.\n2. Informe o **nome** e escolha o **tipo** (praga, doença ou planta daninha).\n3. Defina o **nível de ação** — o limiar (maior que zero) que aciona o alerta quando o índice o alcança.\n4. Se aplicável, escolha a cultura a que o alvo se refere.\n5. Clique em **Salvar** — o alvo passa a estar disponível para os monitoramentos e para o nível de infestação.\n\n## Erros comuns\n- **Salvar sem o nível de ação ou com zero.** O nível é obrigatório e precisa ser maior que zero — é ele que dispara o alerta. Sem um limiar válido o alvo não serve ao monitoramento.\n- **Repetir um alvo já existente no mesmo tipo.** Não pode haver dois alvos com o mesmo nome no mesmo tipo. O sistema avisa e não grava o duplicado.\n- **Tentar excluir um alvo já usado.** Se houver monitoramentos ligados a ele, o alvo é inativado em vez de excluído, para preservar o histórico. Use a inativação quando quiser tirá-lo de circulação.\n\n## Antes e depois\nAntes: Definir com o RT quais pragas e doenças acompanhar e seus limiares. Depois: Registrar os monitoramentos MIP que leem o índice contra esse nível.\n\n## Roteiro do vídeo\n- Abrir Alvos de Controle com o catálogo existente e o filtro por tipo.\n- Criar um novo alvo, preencher nome e tipo.\n- Destacar o campo **Nível de ação** e narrar: \"É esse número que acende o alerta.\"\n- Clicar em **Salvar** e mostrar o alvo na lista.\n- Mostrar rapidamente o Nível de Infestação usando esse limiar.','mip','cadastrar','safra','iniciante',145,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(65,NULL,'cadastrar-ponto-de-amostragem','Cadastrar um ponto de amostragem na válvula','FAZER',NULL,'## Finalidade\nOs pontos de amostragem são os lugares fixos, dentro de cada válvula, onde a equipe sempre faz a leitura do monitoramento. Cadastrá-los antes garante que as medições venham sempre dos mesmos pontos — a base para comparar a evolução da praga ao longo do tempo sem viés de local.\n\n## Como fazer\n1. Abra **Pontos de Amostragem** e clique em novo ponto.\n2. Escolha a **válvula** a que o ponto pertence.\n3. Dê um **nome** ao ponto (algo que a equipe reconheça no campo).\n4. Se tiver, informe latitude e longitude para localizar no mapa.\n5. Clique em **Salvar** — o ponto passa a ficar disponível para escolha nos monitoramentos daquela válvula.\n\n## Erros comuns\n- **Salvar sem válvula ou sem nome.** Os dois são obrigatórios: o ponto não existe solto, ele pertence a uma válvula e precisa de um nome. Preencha ambos.\n- **Repetir o mesmo nome na mesma válvula.** Não pode haver dois pontos com o mesmo nome na mesma válvula. Diferencie os nomes para não confundir a equipe.\n- **Tentar excluir um ponto já usado.** Se houver monitoramentos feitos nele, a exclusão é bloqueada para não quebrar o histórico. Deixe o ponto e apenas pare de usá-lo, se for o caso.\n\n## Antes e depois\nAntes: Definir no campo os locais fixos de leitura em cada válvula. Depois: Registrar os monitoramentos MIP apontando o ponto onde a leitura foi feita.\n\n## Roteiro do vídeo\n- Abrir Pontos de Amostragem, filtrando por válvula.\n- Criar um novo ponto, escolher a válvula e nomear.\n- Narrar: \"Sempre o mesmo ponto, sempre a mesma comparação.\"\n- Clicar em **Salvar** e mostrar o ponto na lista.\n- Abrir um monitoramento e mostrar o ponto aparecendo como opção.','mip','cadastrar','safra','iniciante',130,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(66,NULL,'confirmar-execucao-da-aplicacao','Confirmar a execução de uma OS emitida (baixar estoque e custo)','FAZER',NULL,'## Finalidade\nA OS emitida é só uma instrução. Confirmar a execução é o passo que torna a aplicação real: você informa as quantidades efetivamente consumidas, a data, as horas e o clima. É nessa confirmação que o estoque é baixado por FEFO e o custo entra na safra. Sem confirmar, a DF/IF fica parada como planejada e nada disso acontece.\n\n## Como fazer\n1. Na fila de **Pulverização**, ache a OS em status planejada e clique em **Confirmar execução**.\n2. Informe a **Data realizada** e, se houver, as horas de início e término (o término não pode ser antes do início).\n3. Ajuste as **quantidades reais** de cada produto — elas vêm pré-preenchidas com as previstas, mas o que vale é o que foi consumido.\n4. Identifique **pelo menos um operador** no bloco Operadores/EPI — é exigência de certificação e a confirmação não passa sem isso.\n5. Clique em **Confirmar execução** — este é o passo que baixa o estoque por FEFO e lança o custeio; a OS passa a \"registrada\".\n\n## Erros comuns\n- **Confirmar sem nenhum operador.** A confirmação exige pelo menos um operador identificado no bloco Operadores/EPI. Sem isso ela é recusada — informe quem aplicou.\n- **Hora de término antes da de início.** O sistema bloqueia horários invertidos. Revise as horas antes de confirmar.\n- **Confirmar uma OS sem produtos.** Documento sem itens não pode ser confirmado. Volte à emissão, lance os produtos e só então confirme.\n- **Tentar confirmar algo que não está planejado.** Só documentos emitidos (aguardando execução) podem ser confirmados. Registro direto e aplicações já registradas seguem outro caminho.\n\n## Antes e depois\nAntes: Emitir a OS de pulverização/fertirrigação. Depois: Deixar o RT validar a aplicação registrada.\n\n## Roteiro do vídeo\n- Abrir Pulverização com uma OS planejada na fila.\n- Clicar em Confirmar execução e mostrar o formulário.\n- Ajustar as quantidades reais e preencher data, horas e clima.\n- Destacar o bloco Operadores/EPI e narrar: \"Sem pelo menos um operador aqui, não confirma.\"\n- Clicar em **Confirmar execução**; cortar para o estoque baixando e o custo na safra.','mip','confirmar','safra','intermediario',175,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(67,NULL,'emitir-ordem-de-pulverizacao','Emitir a Ordem de Serviço de pulverização ou fertirrigação (DF/IF)','FAZER',NULL,'## Finalidade\nA Ordem de Serviço (DF de pulverização, IF de fertirrigação) é a prescrição numerada do responsável técnico: define válvula, produtos e doses ANTES de ir a campo. Ela nasce só como instrução — não baixa estoque nem lança custo. Isso só acontece quando a execução é confirmada. O sistema nunca recomenda produto, dose ou carência: a receita é sempre do RT.\n\n## Como fazer\n1. Abra **Pulverização** e clique em **+ Nova aplicação**.\n2. Marque o modo **Emitir OS (DF/IF)** — este é o passo que transforma o registro em instrução numerada, sem baixa de estoque.\n3. Escolha a válvula, a safra, o tipo e informe a **Data prevista** (a data realizada só existe na confirmação, então ela some do formulário).\n4. Lance os produtos e doses da receita do RT e o bico/volume de calda quando for pulverização.\n5. Clique em **Registrar aplicação** — a OS entra na fila em status \"planejada\", aguardando o preparo e a execução.\n\n## Erros comuns\n- **Emitir OS sem a Data prevista.** O sistema trava: na emissão a data realizada não existe, então a prevista é obrigatória. Informe a data em que o serviço deve acontecer.\n- **Confundir emitir OS com registro direto.** Se você quer instruir um serviço que ainda vai acontecer, use Emitir OS. Se a aplicação já foi feita, use o registro direto — só ele baixa estoque na hora.\n- **Esperar que a OS baixe estoque.** A emissão não toca no estoque nem no custeio; isso é intencional. A baixa por FEFO e o custo entram só na confirmação da execução.\n\n## Antes e depois\nAntes: Tratar o alerta fitossanitário que motivou a decisão de controle. Depois: Preparar a calda e atribuir o aplicador e o trator/pulverizador à OS.\n\n## Roteiro do vídeo\n- Abrir Pulverização com a fila de aplicações visível.\n- Clicar em + Nova aplicação e destacar as duas opções de modo.\n- Marcar **Emitir OS (DF/IF)** e narrar: \"Aqui é só a instrução do RT. Nada de estoque ainda.\"\n- Preencher válvula, safra, data prevista, produtos e doses.\n- Destacar **Registrar aplicação**; clicar e mostrar a OS entrando na fila como planejada.','mip','emitir','safra','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(68,NULL,'imprimir-boletim-de-pulverizacao','Consultar e imprimir o boletim diário de pulverização','CONSULTAR',NULL,'## Finalidade\nO boletim consolida num único documento todas as DFs e IFs de um período, uma linha por documento, preservando número, carência e RT de cada um. Ele agrupa para impressão sem fundir as caldas: os documentos seguem distintos e rastreáveis. É a folha que vai a campo ou ao arquivo, com o cabeçalho canônico do emissor.\n\n## Como consultar\n1. Abra o **Boletim de Pulverização**.\n2. Ajuste a data final e quantos dias para trás quer incluir no período.\n3. Se precisar, filtre por série (DF ou IF) e por fazenda.\n4. Confira a tabela consolidada e use a impressão do navegador para gerar o documento.\n\nO boletim é somente leitura: para lançar ou corrigir uma aplicação, use a tela de Pulverização.\n\n## Antes e depois\nAntes: Confirmar a execução das aplicações do período. Depois: Arquivar o boletim impresso junto ao restante da rastreabilidade da safra.\n\n## Roteiro do vídeo\n- Abrir o Boletim de Pulverização já com um período com aplicações.\n- Ajustar a data final e o número de dias e mostrar a tabela mudando.\n- Filtrar por série DF e por fazenda.\n- Acionar a impressão e mostrar o cabeçalho canônico com o emissor.','mip','consultar','safra','iniciante',110,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(69,NULL,'preparar-calda-e-atribuir-aplicador','Preparar a calda: atribuir aplicador e trator e confirmar a OS','FAZER',NULL,'## Finalidade\nEsta é a visão do preparador de calda. O RT emite a OS de pulverização/fertirrigação com produtos e doses, mas sem operador nem máquina. Na hora do preparo, você abre a fila do dia, escolhe a OS, atribui o aplicador (tratorista) e o trator/pulverizador numerado e confirma. Essa confirmação é a mesma da execução: baixa o estoque por FEFO e lança o custeio.\n\n## Como fazer\n1. Abra **Preparo de Calda** e ajuste a data em \"OS previstas até\" para ver a fila do dia (inclui as atrasadas e as sem data).\n2. Na OS que vai preparar, clique em **Preparar** para abrir o painel de atribuição.\n3. Escolha o **trator** (obrigatório) e, se usar, o pulverizador/implemento.\n4. Escolha o **aplicador principal** — pelo menos um operador é exigência de certificação.\n5. Ajuste as quantidades reais da calda, se o preparo consumiu diferente do previsto, e clique em **Atribuir e confirmar preparo** — este é o passo que tira a OS da fila, baixa o estoque e lança o custo.\n\n## Erros comuns\n- **Confirmar sem trator ou sem aplicador.** O painel exige o trator e pelo menos um aplicador. Sem eles a confirmação é recusada — a certificação depende de quem aplicou.\n- **Procurar a OS na fila e não achar.** A fila só mostra OS emitidas (planejadas). Se a aplicação já foi confirmada ou é registro direto, ela não aparece aqui.\n- **Deixar as quantidades previstas quando o preparo gastou outra coisa.** Os valores vêm pré-preenchidos com os previstos, mas é o número que você confirma que baixa do estoque. Ajuste para o consumo real.\n\n## Antes e depois\nAntes: Emitir a OS de pulverização/fertirrigação (o RT define produtos e doses). Depois: Detalhar clima, tríplice lavagem e EPI em Pulverização, na confirmação da execução, se ainda faltar.\n\n## Roteiro do vídeo\n- Abrir Preparo de Calda com algumas OS na fila, uma marcada como atrasada.\n- Narrar: \"O RT já mandou a receita. Aqui o preparador põe quem aplica e com qual máquina.\"\n- Clicar em Preparar numa OS e abrir o painel.\n- Escolher trator e aplicador; ajustar uma quantidade de calda.\n- Destacar **Atribuir e confirmar preparo**; clicar e mostrar a OS saindo da fila.','mip','preparar','safra','iniciante',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(70,NULL,'registrar-aplicacao-ja-executada','Registrar direto uma aplicação que já foi feita no campo','FAZER',NULL,'## Finalidade\nQuando a aplicação já aconteceu — retroativa, ou feita sem OS emitida antes — você registra tudo de uma vez: produtos, quantidades reais e a data realizada. Diferente da OS emitida, o registro direto já baixa o estoque por FEFO e lança o custo na hora. Continua valendo a Regra 1: quem definiu a receita foi o RT; aqui você só documenta o que foi usado.\n\n## Como fazer\n1. Abra **Pulverização** e clique em **+ Nova aplicação**.\n2. Deixe o modo em **registro direto** (o padrão, para aplicação já executada) — este é o passo que faz o sistema baixar estoque e lançar custo ao salvar.\n3. Escolha a válvula, a safra, o tipo e informe a **Data realizada** (obrigatória no registro direto).\n4. Lance os produtos com as **quantidades realmente consumidas**, não as previstas.\n5. Clique em **Registrar aplicação** — o estoque é baixado por FEFO e o custeio da safra é lançado, na categoria insumos.\n\n## Erros comuns\n- **Lançar quantidade prevista no lugar da consumida.** No registro direto o número que você digita é o que sai do estoque e vira custo. Confira o que foi realmente gasto no campo.\n- **Usar registro direto para um serviço que ainda vai acontecer.** Se a aplicação não foi feita, emita a OS (DF/IF) — o registro direto é só para o que já foi executado.\n- **Salvar sem safra e estranhar o custo sumido.** Sem a safra vinculada o custeio não tem onde entrar. Selecione a safra da válvula para o custo aparecer no Custo Realizado.\n\n## Antes e depois\nAntes: Conferir no campo os produtos e as quantidades realmente usadas. Depois: Deixar o RT validar a aplicação registrada.\n\n## Roteiro do vídeo\n- Abrir Pulverização e clicar em + Nova aplicação.\n- Mostrar o modo em registro direto e narrar: \"Essa aplicação já foi feita, então já baixa estoque.\"\n- Preencher válvula, safra, data realizada e as quantidades consumidas.\n- Destacar **Registrar aplicação**; clicar.\n- Cortar para o estoque com o saldo abaixando e o custeio lançado na safra.','mip','registrar','safra','intermediario',165,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:08','2026-07-26 18:33:08'),(71,NULL,'tratar-alerta-fitossanitario','Reconhecer, registrar a decisão e resolver um alerta fitossanitário','FAZER',NULL,'## Finalidade\nOs alertas fitossanitários nascem sozinhos: quando um monitoramento chega ao nível de ação do alvo, o sistema abre um alerta. Esta tela é a fila dessas ocorrências. Aqui você reconhece que viu, registra a decisão de controle do responsável técnico e resolve. O sistema não recomenda produto nem dose — toda decisão de controle é do RT; aqui ela fica documentada.\n\n## Como fazer\n1. Abra **Alertas Fitossanitários** e mantenha o filtro em ativos para ver os abertos e reconhecidos.\n2. No alerta, clique em **Reconhecer** — marca que a equipe tomou ciência, com seu usuário e a data.\n3. Clique em **Registrar ação** e descreva a decisão tomada pelo RT; se já houve pulverização, ligue à aplicação correspondente.\n4. Quando o controle estiver feito, clique em **Resolver** — este é o passo que fecha o alerta.\n\n## Erros comuns\n- **Resolver sem registrar a decisão.** O aceite formal do RT (Registrar ação) é o que dá rastreabilidade ao controle. Descreva a ação antes de fechar o alerta.\n- **Registrar ação sem descrever nada.** O texto da ação é obrigatório — sem ele o sistema não grava. Diga o que foi decidido, mesmo que seja \"monitorar de novo em X dias\".\n- **Esperar que o sistema indique o produto.** Ele nunca recomenda produto ou dose. A ação e a receita são do responsável técnico; a tela só registra.\n\n## Antes e depois\nAntes: Registrar o monitoramento MIP que atingiu o nível de ação. Depois: Emitir a OS de pulverização, se a decisão do RT for aplicar.\n\n## Roteiro do vídeo\n- Abrir Alertas Fitossanitários com alertas abertos e críticos no topo.\n- Clicar em **Reconhecer** num alerta e narrar que fica registrado quem viu.\n- Abrir **Registrar ação**, descrever a decisão do RT e vincular a uma aplicação.\n- Clicar em **Resolver** e mostrar o alerta saindo da fila de ativos.','mip','tratar','safra','intermediario',155,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(72,NULL,'validar-aplicacao-como-rt','Validar como responsável técnico uma aplicação registrada','FAZER',NULL,'## Finalidade\nA validação é o aceite formal do responsável técnico sobre uma aplicação já registrada: é o carimbo de \"eu, RT, confirmo que esta execução está correta\". Só aplicações em status registrada aguardam validação. É a última etapa da trilha da DF/IF, importante para a rastreabilidade e para as exigências do RT.\n\n## Como fazer\n1. Na lista de **Pulverização**, localize a aplicação em status registrada.\n2. Confira a execução: produtos, quantidades, data e operadores.\n3. Clique no botão **Validar (RT)** — este é o passo que registra o aceite, com seu usuário e a data/hora.\n4. A aplicação passa a \"validada\" e a trilha fica completa.\n\n## Erros comuns\n- **Tentar validar uma OS ainda emitida.** Se o documento está planejado, o sistema manda usar antes a Confirmar execução — a validação só age depois que a execução foi registrada.\n- **Esperar validar algo cancelado ou já validado.** Apenas o status registrada aguarda validação; qualquer outro é recusado com a explicação do status atual.\n- **Ignorar o aviso de registro do RT.** Se o RT da aplicação não tem registro formal cadastrado ou está vencido, aparece um aviso — a validação segue, mas regularize o registro em Pessoas para atender a exigência.\n\n## Antes e depois\nAntes: Confirmar a execução da aplicação com as quantidades reais. Depois: Arquivar o receituário do RT e acompanhar o boletim de pulverização.\n\n## Roteiro do vídeo\n- Abrir Pulverização e filtrar por aplicações registradas.\n- Abrir uma aplicação e narrar a conferência de produtos e operadores.\n- Destacar o botão **Validar (RT)** antes de clicar.\n- Clicar e mostrar o status virando validada.\n- Mostrar o aviso de registro do RT quando aparecer, explicando que não trava.','mip','validar','safra','intermediario',130,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(73,NULL,'cadastrar-faixas-nutricionais','Cadastrar as faixas nutricionais que classificam os laudos','FAZER',NULL,'## Finalidade\nA faixa é a régua do responsável técnico: é ela que diz se um resultado de laudo está \"baixo\", \"adequado\" ou \"excessivo\". Sem faixa cadastrada, o VERO não inventa referência — o laudo entra sem classificação e sem alerta. Cadastrar as faixas é o que dá vida às análises de solo e foliares.\n\n## Como fazer\n1. Escolha o **tipo** (solo ou foliar) e o **nutriente** — cada faixa vale para um dos dois.\n2. Preencha a **faixa ideal** (ideal mín e ideal máx) — os dois são obrigatórios.\n3. Se quiser, informe **mínimo** e **máximo** para as bordas \"muito baixo\" e \"excessivo\". Vale a regra: mínimo ≤ ideal mín ≤ ideal máx ≤ máximo.\n4. Se a referência muda por variedade ou fase fenológica, escolha a **variedade/fase** — a faixa passa a valer só naquele contexto.\n5. Clique em **Salvar**. A partir daí, todo laudo novo é classificado contra essa faixa.\n\n## Erros comuns\n- **Faixa inconsistente.** O sistema recusa se o ideal mínimo for maior que o ideal máximo, ou se o mínimo/máximo invadir a faixa ideal. Confira a ordem dos quatro números antes de salvar.\n- **Faixa duplicada para o mesmo contexto.** Já existe uma faixa ativa para aquele nutriente/variedade/fase — inative a anterior antes de cadastrar a nova, senão o salvamento é bloqueado.\n- **Unidade em branco.** A faixa sem unidade classifica, mas gera confusão na leitura — informe a unidade (ppm, cmolc/dm³, g/kg...) igual à do laudo.\n\n## Antes e depois\nAntes: Ter os nutrientes cadastrados que serão medidos. Depois: Registrar as análises de solo e foliares — que passam a sair classificadas e a emitir alertas.\n\n## Roteiro do vídeo\n- Abrir Faixas Nutricionais com a lista vazia para um nutriente.\n- Narrar: \"A faixa é a régua do RT. Sem ela, o laudo entra sem cor.\"\n- Cadastrar uma faixa (tipo, nutriente, ideal mín/máx), mostrar a regra dos quatro números.\n- Cortar para uma Análise onde o mesmo nutriente agora aparece classificado.','nutricao','cadastrar','continuo','iniciante',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(74,NULL,'consultar-aplicacoes-nutricionais','Consultar as aplicações nutricionais da safra','CONSULTAR',NULL,'## Finalidade\nEsta tela é a vitrine das aplicações nutricionais — fertirrigação, adubação foliar e indutor de brotação — com produtos, dose do RT, custo e status. Ela é de leitura: o registro em si acontece no núcleo de Aplicações. Serve para acompanhar o que já foi aplicado e quanto custou.\n\n## Como fazer\n1. Abra **Aplicações Nutricionais** e, se quiser, filtre por tipo (fertirrigação, foliar, indutor).\n2. Leia a lista: data, válvula, safra, produtos com a dose informada pelo RT, custo e status.\n3. Para **registrar** uma nova aplicação, use o link \"registrar\" — a receita nasce em MIP → Aplicações (`/mip/aplicacoes.php`), escolhendo o tipo nutricional.\n4. Acompanhe o status: \"Aguardando RT\" significa que a validação técnica ainda não saiu.\n\n## Antes e depois\nAntes: A aplicação é registrada e validada no núcleo de Aplicações. Depois: O custo aparece aqui e no Custo Realizado da safra.\n\n## Roteiro do vídeo\n- Abrir Aplicações Nutricionais, aplicar o filtro de tipo.\n- Narrar a leitura de uma linha (produto, dose do RT, custo, status).\n- Mostrar o link \"registrar\" levando ao núcleo de Aplicações.','nutricao','consultar','safra','iniciante',110,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(75,NULL,'importar-laudo-de-analise','Importar um laudo em PDF com a IA e revisar antes de gravar','FAZER',NULL,'## Finalidade\nEm vez de digitar nutriente por nutriente, você envia o PDF do laboratório e a IA extrai os resultados. Mas a IA só propõe — quem grava a análise é você, depois de conferir cada campo. É um atalho para o cadastro, não um substituto do olho do responsável técnico.\n\n## Como fazer\n1. Escolha o **tipo** do laudo (solo ou foliar) e envie o **PDF** original (arquivo válido, dentro do limite de tamanho).\n2. Clique em **Extrair**: a IA lê o documento e devolve os resultados em tela.\n3. **Revise TODOS os campos** — a revisão humana é obrigatória. Corrija qualquer valor, unidade ou data que a IA tenha lido errado.\n4. Preencha a **data da amostra** e clique em **Confirmar** para gravar a análise de verdade.\n5. Confira a classificação resultante, igual a uma análise digitada à mão.\n\n## Erros comuns\n- **Confirmar sem revisar.** A IA erra vírgula, unidade e às vezes troca nutriente. Confirmar direto grava o erro na safra — leia campo a campo.\n- **Enviar arquivo que não é PDF.** Fotos, prints e planilhas são recusados; exporte o laudo em PDF original do laboratório.\n- **Teto mensal de IA atingido.** Quando o custo estimado do mês estoura, a extração é bloqueada — use a digitação manual ou o CSV até virar o mês.\n\n## Antes e depois\nAntes: Ter o laudo em PDF e as faixas cadastradas. Depois: A análise gravada é classificada e alimenta o Painel de Nutrientes.\n\n## Roteiro do vídeo\n- Abrir Importar Laudo, escolher tipo e anexar um PDF.\n- Clicar em Extrair e mostrar a IA preenchendo os campos.\n- Narrar: \"A IA propõe; você confere.\" Corrigir um valor de propósito.\n- Preencher data da amostra, Confirmar, mostrar a análise gravada e classificada.','nutricao','importar','safra','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(76,NULL,'registrar-analise-de-solo','Registrar uma análise de solo e classificá-la','FAZER',NULL,'## Finalidade\nAqui você lança o laudo de solo por talhão/válvula. Ao salvar, o VERO compara cada valor com as faixas do RT, classifica cada nutriente (baixo, adequado, excessivo) e emite os alertas correspondentes. É o que transforma um PDF de laboratório em informação que orienta a adubação.\n\n## Como fazer\n1. Preencha o **cabeçalho**: a **data da amostra** (obrigatória) e o talhão/válvula de onde veio o solo.\n2. Lance os **valores por nutriente** conforme o laudo do laboratório.\n3. Confira as **unidades** — cada resultado precisa da sua unidade de medida.\n4. Clique em **Salvar**: o sistema reclassifica os resultados contra as faixas e reemite os alertas.\n5. Leia a coluna de classificação — nutriente sem faixa cadastrada fica sem cor (o sistema nunca inventa referência).\n\n## Erros comuns\n- **pH fora da escala 0–14.** O salvamento é recusado. Confira o valor digitado; o pH é adimensional, então deixe a unidade em branco (ou \"pH\").\n- **Unidade que é um número.** Digitar \"4\" no campo unidade é rejeitado — unidade é medida (ppm, cmolc/dm³...), não valor.\n- **Resultado sem cor.** Não é bug: falta a faixa daquele nutriente. Cadastre a faixa e salve de novo para classificar.\n\n## Antes e depois\nAntes: Ter as faixas nutricionais cadastradas para o laudo sair classificado. Depois: Ler o Painel de Nutrientes e planejar a adubação com o RT.\n\n## Roteiro do vídeo\n- Abrir Análises de Solo e iniciar um lançamento.\n- Preencher data da amostra + talhão, lançar dois ou três nutrientes.\n- Narrar a crítica do pH (0–14) e da unidade.\n- Salvar e mostrar as classificações aparecendo + o alerta gerado.','nutricao','registrar','safra','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(77,NULL,'registrar-analise-foliar','Registrar uma análise foliar por variedade e fase','FAZER',NULL,'## Finalidade\nA análise foliar mostra o que a planta de fato absorveu — e o valor certo depende da variedade e da fase fenológica em que a folha foi coletada. Ao salvar, o VERO classifica cada nutriente contra as faixas do RT daquele contexto e emite alertas. É a leitura mais fina do estado nutricional do vinhedo.\n\n## Como fazer\n1. Preencha o **cabeçalho**: **data da amostra** (obrigatória), talhão/válvula e a **variedade/fase fenológica** da coleta.\n2. Lance os **valores por nutriente** conforme o laudo, com as respectivas unidades.\n3. Clique em **Salvar**: os resultados são reclassificados contra as faixas foliares daquele contexto e os alertas, reemitidos.\n4. Confira as classificações — se um nutriente sai sem cor, falta a faixa foliar para aquela variedade/fase.\n\n## Erros comuns\n- **Esquecer a variedade/fase.** A faixa foliar costuma ser específica por variedade e fase; sem esse contexto o resultado pode cair na faixa errada ou ficar sem classificação.\n- **Unidade incoerente.** Um número puro no campo unidade é rejeitado; o pH, se houver, precisa estar entre 0 e 14.\n- **Comparar foliar com solo.** São réguas diferentes — não use a faixa de solo para julgar um laudo foliar.\n\n## Antes e depois\nAntes: Cadastrar as faixas foliares por variedade/fase. Depois: Cruzar solo e foliar no Painel de Nutrientes e ajustar a fertirrigação com o RT.\n\n## Roteiro do vídeo\n- Abrir Análises Foliares e iniciar um lançamento.\n- Destacar a escolha de variedade + fase fenológica antes dos valores.\n- Lançar nutrientes, salvar, mostrar a classificação específica daquele contexto.','nutricao','registrar','safra','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(78,NULL,'acompanhar-produtividade-por-talhao','Acompanhar a produtividade por talhão','CONSULTAR',NULL,'## Finalidade\nEste painel mostra o atingimento de produtividade por válvula: o realizado (kg colhido) contra o planejado da safra, com barras clicáveis. É a leitura de quanto cada talhão entregou frente à meta.\n\n## Como fazer\n1. Abra **Produtividade por Talhão** e selecione a **safra**.\n2. Leia os KPIs e a barra de atingimento de cada válvula (realizado ÷ planejado).\n3. Clique numa barra para o **drill-down** — as colheitas individuais que compõem o número daquela válvula.\n4. Compare kg/ha realizado com a produtividade planejada para achar os talhões abaixo da meta.\n\n## Antes e depois\nAntes: Registrar as colheitas da safra por válvula. Depois: Cruzar produtividade com o custo realizado para avaliar a margem por talhão.\n\n## Roteiro do vídeo\n- Abrir Produtividade por Talhão e escolher a safra.\n- Percorrer as barras de atingimento e clicar numa para o drill-down.\n- Apontar um talhão abaixo da meta e ler o kg/ha realizado.','operacao-agricola','acompanhar','safra','intermediario',100,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(79,NULL,'cadastrar-area-produtiva','Cadastrar uma área produtiva','FAZER',NULL,'## Finalidade\nA área produtiva é a macro-área da fazenda (ex.: Quadra Norte) que agrupa talhões. Serve para organizar e somar o parreiral por bloco, sem substituir o cadastro de cada talhão.\n\n## Como fazer\n1. Abra **Áreas Produtivas** e clique em **+ Nova área**.\n2. Dê um **nome** à área (ex.: Quadra Norte) e escolha a **fazenda** — ambos obrigatórios.\n3. Informe a área declarada em hectares, se quiser (opcional).\n4. Clique em **Salvar** — a área passa a ficar disponível para vincular talhões.\n5. O vínculo talhão → área é feito depois, no cadastro de Talhões.\n\n## Erros comuns\n- **Salvar sem escolher a fazenda.** A fazenda é obrigatória (coluna NOT NULL); sem ela o sistema recusa e a área não é criada.\n- **Tentar excluir uma área com talhões.** Se houver talhão vinculado, a exclusão é bloqueada — mova os talhões para outra área antes.\n- **Confundir \"área declarada\" com \"área dos talhões\".** A tela mostra as duas: a declarada é a que você digita; a dos talhões é a soma real dos talhões ativos vinculados.\n\n## Antes e depois\nAntes: Ter a fazenda cadastrada. Depois: Vincular os talhões a esta área no cadastro de Talhões.\n\n## Roteiro do vídeo\n- Abrir Áreas Produtivas e clicar em + Nova área.\n- Nomear a área, escolher a fazenda e salvar.\n- Mostrar as duas colunas de área (declarada x soma dos talhões) e o link para o cadastro de talhões.','operacao-agricola','cadastrar','implantacao','iniciante',110,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(80,NULL,'cadastrar-bomba-de-irrigacao','Cadastrar uma bomba e suas válvulas','FAZER',NULL,'## Finalidade\nA bomba de irrigação e o vínculo com as válvulas que ela atende são a base da fertirrigação (IF): o documento IF referencia a bomba usada. Cadastrar a bomba e marcar suas válvulas deixa a IF pronta para apontar.\n\n## Como fazer\n1. Abra **Bombas** e clique em **+ Nova bomba**.\n2. Escolha a **fazenda** e informe o **nome** da bomba — obrigatórios.\n3. Preencha código, vazão (m³/h) e potência (kW), se tiver.\n4. Marque as **válvulas** que a bomba atende — só aparecem válvulas ativas da mesma fazenda.\n5. Clique em **Salvar** — a bomba e o vínculo com as válvulas ficam gravados.\n\n## Erros comuns\n- **Repetir o nome da bomba na fazenda.** O sistema recusa nome igual a outra bomba ativa da mesma fazenda.\n- **Marcar válvula de outra fazenda.** Só entram válvulas ativas da fazenda da bomba; válvulas de outra fazenda são ignoradas no vínculo.\n- **Vazão ou potência negativas.** São grandezas físicas e o sistema bloqueia valores negativos.\n- **Excluir uma bomba usada em IF.** A exclusão inativa a bomba, mas se ela já foi referenciada em documentos IF o histórico é preservado e o sistema avisa — ela só some dos selects e vínculos.\n\n## Antes e depois\nAntes: Ter as válvulas da fazenda cadastradas. Depois: Apontar a fertirrigação (IF) referenciando esta bomba.\n\n## Roteiro do vídeo\n- Abrir Bombas e clicar em + Nova bomba.\n- Escolher a fazenda, nomear, informar vazão/potência.\n- Marcar as válvulas atendidas e salvar; mostrar a lista de válvulas na linha.','operacao-agricola','cadastrar','implantacao','intermediario',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(81,NULL,'cadastrar-cultura','Cadastrar uma cultura','FAZER',NULL,'## Finalidade\nA cultura é a base de quase tudo no agrícola: o vínculo Safra × Válvula exige uma cultura, e ela define a unidade de produtividade e se a colheita vira entrada no estoque. Cadastre-a antes das variedades e das safras.\n\n## Como fazer\n1. Abra **Culturas** e clique em **+ Nova cultura**.\n2. Informe o **nome** (ex.: Uva, Manga) — obrigatório e único por tenant.\n3. Escolha a **unidade de produtividade** (kg/ha, t/ha, sacas/ha, @/ha ou L/ha).\n4. Se a colheita desta cultura deve entrar no estoque, selecione o **produto** e o **almoxarifado** de destino; deixe vazio se a colheita não gera entrada.\n5. Marque se **exige classificação** e clique em **Salvar**.\n\n## Erros comuns\n- **Repetir o nome de uma cultura ativa.** O sistema recusa nomes duplicados entre culturas ativas (\"Já existe a cultura\").\n- **Esperar a colheita entrar no estoque sem configurar o produto.** Sem produto e almoxarifado de colheita definidos aqui, a colheita registra a produção mas NÃO movimenta estoque.\n- **Cadastrar variedade no lugar da cultura.** Aqui é o nível cultura; o detalhe de cada variedade fica no módulo Variedades.\n\n## Antes e depois\nAntes: Definir a fazenda e as unidades produtivas. Depois: Cadastrar as variedades desta cultura.\n\n## Roteiro do vídeo\n- Abrir Culturas e clicar em + Nova cultura.\n- Nomear a cultura, escolher a unidade de produtividade.\n- Mostrar a configuração de produto/almoxarifado da colheita e salvar.','operacao-agricola','cadastrar','implantacao','iniciante',120,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(82,NULL,'cadastrar-estagio-fenologico','Cadastrar um estágio fenológico da cultura','FAZER',NULL,'## Finalidade\nOs estágios fenológicos são o vocabulário de fases por cultura e escala (BBCH, E-L ou própria) usado no apontamento e nas faixas nutricionais. Cadastre-os antes de definir os períodos por safra.\n\n## Como fazer\n1. Abra **Fases Fenológicas** e clique em **+ Novo estágio**.\n2. Escolha a **cultura** e a **escala** (BBCH, E-L ou Própria).\n3. Informe o **código** (ex.: EL-12, BBCH-65) e o **nome** do estágio (ex.: Floração plena) — obrigatórios.\n4. Preencha a **ordem** de exibição para os estágios saírem na sequência certa.\n5. Clique em **Salvar**.\n\n## Erros comuns\n- **Repetir o código na mesma cultura e escala.** A combinação cultura × escala × código é única (inclui inativos) — o sistema recusa duplicidade.\n- **Misturar escalas sem querer.** Um código BBCH e um E-L podem coexistir; o que não pode é o mesmo código repetido dentro da mesma escala e cultura.\n- **Esquecer a ordem.** Sem o número de ordem os estágios saem fora de sequência nas listas e nos selects do apontamento.\n- **Confundir com a curva da variedade.** Aqui é o catálogo de estágios da cultura; a curva de dias por variedade é montada na fenologia da variedade.\n\n## Antes e depois\nAntes: Cadastrar a cultura. Depois: Definir os períodos por safra para a fase ser resolvida automaticamente pela data.\n\n## Roteiro do vídeo\n- Abrir Fases Fenológicas e clicar em + Novo estágio.\n- Escolher cultura e escala, informar código, nome e ordem.\n- Salvar e mostrar o estágio ordenado na tabela.','operacao-agricola','cadastrar','implantacao','intermediario',130,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(83,NULL,'cadastrar-porta-enxerto','Cadastrar um porta-enxerto','FAZER',NULL,'## Finalidade\nO porta-enxerto é o cadastro botânico irmão da variedade. Ele é atribuído no talhão/válvula e serve de referência nas faixas nutricionais. A permissão de escrita é a mesma das variedades.\n\n## Como fazer\n1. Abra **Porta-enxertos** e clique em **+ Novo porta-enxerto**.\n2. Informe o **nome** (ex.: IAC 572, Paulsen 1103, SO4) — único campo obrigatório.\n3. Preencha código e descrição (vigor, tolerâncias, indicações), se tiver.\n4. Clique em **Salvar** — ele passa a aparecer na lista de porta-enxertos do cadastro de talhão/válvula.\n\n## Erros comuns\n- **Repetir um nome já usado.** O nome é único por tenant e a checagem inclui inativos — se aparecer \"já existe\", reative o registro em vez de duplicar.\n- **Esperar que o porta-enxerto se aplique sozinho.** Ele só passa a valer quando você o atribui no cadastro do talhão/válvula (campo Porta-enxerto).\n- **Não encontrar a permissão.** Quem edita variedades edita porta-enxertos — é a mesma chave; não há permissão separada.\n\n## Antes e depois\nAntes: Ter as variedades e culturas do parreiral cadastradas. Depois: Atribuir o porta-enxerto no cadastro do talhão/válvula.\n\n## Roteiro do vídeo\n- Abrir Porta-enxertos e clicar em + Novo porta-enxerto.\n- Digitar o nome e a descrição, salvar.\n- Abrir o cadastro de uma válvula e mostrar o porta-enxerto disponível no select.','operacao-agricola','cadastrar','implantacao','iniciante',90,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(84,NULL,'cadastrar-talhao','Completar os dados técnicos de um talhão','FAZER',NULL,'## Finalidade\nEsta é a ficha técnica completa do talhão: tipo de solo, espaçamentos, data de plantio, coordenadas e a área produtiva a que ele pertence. É o cadastro canônico — a válvula-espelho herda tudo daqui.\n\n## Como fazer\n1. Abra **Talhões** (ou entre pela ficha da válvula) e clique em **Editar** no talhão.\n2. Confirme fazenda e código, e vincule a **área produtiva** — ela precisa ser da mesma fazenda do talhão.\n3. Escolha o **tipo de solo** na lista (catálogo fechado mantido pelo RT) e informe espaçamento de linha e de planta.\n4. Preencha data de plantio, nº de plantas real, variedade e porta-enxerto.\n5. Clique em **Salvar** — os dados ficam gravados e a válvula-espelho é sincronizada.\n\n## Erros comuns\n- **Tentar digitar um tipo de solo fora do catálogo.** O campo só aceita valores da lista do RT; para incluir um novo, edite o catálogo no rodapé da tela (\"Catálogo de tipos de solo\").\n- **Escolher uma área produtiva de outra fazenda.** O sistema recusa (\"a área não pertence à fazenda escolhida\") — a área precisa ser da mesma fazenda.\n- **Achar que aqui se desenha o mapa.** O polígono (geometria) não é editado nesta tela; ele é desenhado na tela Mapa da Fazenda.\n- **Informar nº de plantas \"teórico\".** Use a contagem real — o parreiral tem falhas e esse número alimenta a calculadora de mão de obra.\n\n## Antes e depois\nAntes: Cadastrar a válvula/unidade produtiva. Depois: Desenhar o polígono no Mapa da Fazenda para recalcular a área pelo desenho.\n\n## Roteiro do vídeo\n- Abrir Talhões e editar um talhão existente.\n- Mostrar o select de tipo de solo (catálogo) e o link do catálogo no rodapé.\n- Vincular a área produtiva da mesma fazenda; preencher espaçamentos e plantio.\n- Salvar e narrar que a válvula-espelho herdou os dados.','operacao-agricola','cadastrar','implantacao','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(85,NULL,'cadastrar-tipo-de-atividade','Cadastrar um tipo de atividade','FAZER',NULL,'## Finalidade\nO tipo de atividade é o catálogo de operações do campo (Poda, Raleio, Colheita, Embalamento) que sustenta o apontamento e a premiação. A categoria e a marcação \"exige produção\" definem como a atividade alimenta colheita, metas e custo.\n\n## Como fazer\n1. Abra **Tipos de Atividade** e clique em **+ Novo tipo**.\n2. Informe o **nome** e escolha a **categoria** (trato cultural, colheita, aplicação, irrigação, packing ou outro) — obrigatórios.\n3. Escolha a **unidade padrão de produção** (planta, caixa, kg, ha, cacho, fila…) quando fizer sentido.\n4. Defina se **exige quantidade produzida** — Sim faz a atividade alimentar colheita e metas.\n5. Marque as **culturas** em que se aplica (nenhuma marcada = vale para todas) e clique em **Salvar**.\n\n## Erros comuns\n- **Repetir o nome do tipo.** O nome é único por tenant e a checagem inclui inativos — se der duplicidade, reative o tipo existente.\n- **Marcar \"exige produção\" sem definir a unidade.** Atividades que exigem produção sem unidade padrão deixam o apontamento sem base de medida — defina a unidade.\n- **Não marcar nenhuma cultura sem querer.** Sem cultura marcada, o tipo vale para todas — se você quis restringir, marque as culturas certas.\n- **Esperar que colheita e metas apareçam de tipos \"Não exige produção\".** Só os tipos com exige produção = Sim alimentam colheita e metas; os demais alimentam apenas operação e custo.\n\n## Antes e depois\nAntes: Ter as culturas cadastradas. Depois: Definir os parâmetros de rendimento (mão de obra) deste tipo de atividade.\n\n## Roteiro do vídeo\n- Abrir Tipos de Atividade e clicar em + Novo tipo.\n- Nomear (ex.: Poda), escolher categoria e unidade padrão, marcar exige produção.\n- Marcar culturas e salvar; explicar \"sem cultura = todas\".','operacao-agricola','cadastrar','implantacao','iniciante',140,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(86,NULL,'cadastrar-valvula','Cadastrar uma válvula (a unidade produtiva)','FAZER',NULL,'## Finalidade\nA válvula é a unidade produtiva do VERO — é nela que safra, colheita, custo e apontamento se ancoram. Nesta operação válvula e talhão são a mesma coisa: você cadastra uma vez e o sistema mantém o espelho sincronizado sozinho.\n\n## Como fazer\n1. Abra **Válvulas** e clique em **+ Nova válvula**.\n2. Informe a **fazenda** e o **código** — curto e único na fazenda (ex.: 5A, 2D).\n3. Preencha área (ha), nº de plantas, variedade, estrutura de condução, porta-enxerto e tipo de irrigação, conforme tiver.\n4. Clique em **Salvar** — a válvula fica gravada e a válvula-espelho é criada e sincronizada automaticamente.\n5. Os dados técnicos finos (solo, coordenadas, espaçamento) você completa depois na **ficha** da válvula.\n\n## Erros comuns\n- **Repetir o código na mesma fazenda.** O sistema recusa código igual a outra válvula ativa da fazenda (\"Já existe a válvula\"). Códigos repetidos só são permitidos em fazendas diferentes.\n- **Deixar o nº de plantas em branco e estranhar a calculadora.** A calculadora de mão de obra por planta usa esse número; sem ele, a estimativa de diárias fica incompleta.\n- **Área negativa.** Área é grandeza física — o sistema bloqueia valores menores que zero.\n- **Cadastrar a válvula antes da cultura/variedade.** A variedade só aparece na lista se já estiver cadastrada; cadastre a cultura e a variedade primeiro.\n\n## Antes e depois\nAntes: Cadastrar a cultura e a variedade que a válvula recebe. Depois: Desenhar o polígono da válvula no Mapa da Fazenda.\n\n## Roteiro do vídeo\n- Abrir Válvulas e clicar em + Nova válvula.\n- Preencher fazenda, código, área e nº de plantas; narrar \"válvula = unidade produtiva\".\n- Salvar e mostrar a linha nova com a válvula-espelho já sincronizada.\n- Abrir a ficha da válvula e apontar onde ficam os dados técnicos completos.','operacao-agricola','cadastrar','implantacao','iniciante',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(87,NULL,'cadastrar-variedade','Cadastrar uma variedade','FAZER',NULL,'## Finalidade\nA variedade é o catálogo por cultura que alimenta as faixas nutricionais, a colheita e a premiação. A produtividade esperada informada aqui vira a referência que pré-preenche a meta no vínculo safra × talhão.\n\n## Como fazer\n1. Abra **Variedades** e clique em **+ Nova variedade**.\n2. Escolha a **cultura** e informe o **nome** (ex.: Thompson Seedless, Vitória) — obrigatórios.\n3. Preencha uso (mesa, vinho, suco, mista), cor da baga, se é apirênica e o ciclo em dias, conforme tiver.\n4. Informe a **produtividade esperada em kg/ha** — ela é referência e pré-preenche a meta da safra (editável).\n5. Clique em **Salvar**.\n\n## Erros comuns\n- **Repetir a variedade na mesma cultura.** O nome é único por cultura, e a checagem inclui variedades inativas — se aparecer duplicidade, reative a existente em vez de recriar.\n- **Achar que a produtividade esperada é imposta.** Ela é só referência: pré-preenche a meta no vínculo safra × talhão, mas você pode ajustar lá.\n- **Digitar produtividade negativa.** O sistema bloqueia — produtividade nunca é negativa.\n- **Cadastrar variedade sem a cultura existir.** A variedade exige uma cultura; cadastre a cultura primeiro.\n\n## Antes e depois\nAntes: Cadastrar a cultura. Depois: Montar a curva fenológica da variedade (fases desde a poda).\n\n## Roteiro do vídeo\n- Abrir Variedades e clicar em + Nova variedade.\n- Escolher a cultura, nomear a variedade, marcar uso/cor/apirênica.\n- Preencher a produtividade esperada em kg/ha e salvar; apontar o ícone de fenologia na linha.','operacao-agricola','cadastrar','implantacao','iniciante',130,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(88,NULL,'calcular-diarias-de-mao-de-obra','Calcular quantas diárias uma tarefa precisa','CONSULTAR',NULL,'## Finalidade\nA calculadora estima quantas diárias uma tarefa precisa para caber no prazo, usando o rendimento cadastrado do tipo de atividade. Ela orienta o dimensionamento da equipe — não grava nada e não decide por você.\n\n## Como fazer\n1. Abra a **Calculadora de Diárias** e escolha a **atividade** (o rendimento vigente já entra como meta).\n2. Para tarefas por planta (poda etc.), informe **nº de plantas** e **dias**; a conta é plantas ÷ dias ÷ meta, arredondada para cima.\n3. Para **colheita** (unidade caixa/kg), informe a **produção prevista em kg**, os dias e o **peso da caixa** — a meta é convertida em kg.\n4. Escolha **Própria** ou **Terceirizada** e, se quiser, o custo da diária para ver o custo total rotulado.\n5. Leia o resultado de diárias necessárias; ajuste dias ou meta para simular cenários.\n\n## Antes e depois\nAntes: Cadastrar os parâmetros de rendimento do tipo de atividade. Depois: Planejar a atividade e emitir a Ordem de Serviço com a equipe dimensionada.\n\n## Roteiro do vídeo\n- Abrir a Calculadora e escolher a atividade Poda.\n- Digitar nº de plantas e dias; mostrar as diárias arredondando para cima.\n- Trocar para uma atividade de colheita e demonstrar produção em kg × peso da caixa.','operacao-agricola','dimensionar','safra','iniciante',120,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(89,NULL,'definir-parametros-de-rendimento','Definir os parâmetros de rendimento de mão de obra','FAZER',NULL,'## Finalidade\nEstes parâmetros são o que liga a Calculadora de Mão de Obra a cada tipo de atividade: rendimento por diária, fator de ajuste e custo da diária. O sistema nunca inventa rendimento — sem esse cadastro, a calculadora avisa e espera. Os valores são versionados por vigência.\n\n## Como fazer\n1. Abra **Parâmetros de Rendimento (MO)** e clique no lápis do tipo de atividade.\n2. Informe o **rendimento por diária** (quanto 1 pessoa faz por dia, na unidade da atividade).\n3. Ajuste o **fator** (1,0 = normal) e, se quiser, use **Puxar custo automático** para trazer a diária própria (por equipe CLT) e a terceirizada da folha.\n4. Defina o **início da vigência** — os apontamentos usam a vigência da data.\n5. Clique em **Gravar parâmetros** — a versão anterior é desativada (a trilha fica) e a calculadora já usa a nova.\n\n## Erros comuns\n- **Deixar um campo vazio achando que zera.** Campo vazio NÃO mexe na chave — ele preserva o valor vigente. Para mudar, digite o novo valor.\n- **Valor negativo.** A gravação é bloqueada: nenhum parâmetro pode ser negativo.\n- **Esquecer a vigência.** Corrigir um valor cria uma nova vigência a partir da data informada; apontamentos antigos continuam com a vigência que valia na data deles.\n- **Colheita medida por planta.** Na colheita o rendimento é em caixas (ou kg) por pessoa/dia; a calculadora parte da produção prevista e converte pelo peso da caixa, nunca pelo nº de plantas.\n\n## Antes e depois\nAntes: Cadastrar o tipo de atividade. Depois: Usar a Calculadora de Diárias para dimensionar a equipe.\n\n## Roteiro do vídeo\n- Abrir Parâmetros de Rendimento e editar um tipo (ex.: Poda).\n- Informar rendimento/diária e fator; usar \"Puxar custo automático\" por equipe.\n- Definir a vigência, gravar e mostrar o valor vigente na tabela.','operacao-agricola','configurar','implantacao','expert',180,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(90,NULL,'definir-periodos-fenologicos-da-safra','Definir os períodos fenológicos de uma safra','FAZER',NULL,'## Finalidade\nOs períodos ligam cada estágio a datas reais da safra (ex.: poda 01–10/07, brotação 11–25/07). Com eles, a fase da planta passa a ser resolvida automaticamente pela data no apontamento, na DF e na IF — sem escolher a fase na mão.\n\n## Como fazer\n1. Abra **Fases Fenológicas** e, no bloco **Períodos por safra**, escolha a **safra**.\n2. Selecione o **estágio** e o **escopo** — safra inteira ou um talhão específico.\n3. Informe a **data de início** e a **data de fim** do período.\n4. Clique em **Adicionar período** — a fase daquela data passa a ser resolvida automaticamente.\n5. Repita para cobrir o ciclo; períodos de talhão vencem os de safra inteira.\n\n## Erros comuns\n- **Início depois do fim.** O sistema recusa período com data inicial maior que a final.\n- **Escolher um talhão que não é da safra.** O talhão precisa estar vinculado à safra escolhida; caso contrário aparece \"o talhão selecionado não é desta safra\".\n- **Ignorar o aviso de sobreposição.** Sobrepor períodos no mesmo escopo não trava, mas na resolução automática vale o mais específico e o mais recente — confira se é isso que você quer.\n- **Deixar datas sem cobertura.** Sem período para uma data, a fase volta a ser manual naquele dia.\n\n## Antes e depois\nAntes: Cadastrar os estágios fenológicos da cultura. Depois: Apontar em campo com a fase já resolvida pela data.\n\n## Roteiro do vídeo\n- Abrir Fases Fenológicas e selecionar a safra no bloco de períodos.\n- Adicionar poda 01–10/07 (safra inteira) e brotação 11–25/07.\n- Mostrar o aviso de sobreposição e explicar a regra do mais específico/recente.','operacao-agricola','planejar','safra','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(91,NULL,'desenhar-valvula-no-mapa','Desenhar a válvula no mapa da fazenda','FAZER',NULL,'## Finalidade\nNo mapa você desenha o polígono de cada válvula sobre a imagem de satélite. Ao salvar a geometria, o sistema recalcula a área da válvula pelo próprio desenho — deixando a área alinhada com o que existe no campo.\n\n## Como fazer\n1. Abra **Mapa da Fazenda** e clique na válvula que quer mapear.\n2. Use a ferramenta de desenho do mapa para traçar o polígono da válvula.\n3. Clique em **Salvar** a geometria — o polígono é gravado e a **área é recalculada pelo desenho**.\n4. Se já tiver os mapas prontos, use **Importar mapa** (KML, KMZ ou GeoJSON) para casar os polígonos por código/nome da válvula.\n5. Confira a área recalculada mostrada na mensagem de confirmação.\n\n## Erros comuns\n- **Enviar um formato não suportado.** A importação aceita KML, KMZ e GeoJSON (Shapefile é fase 2) e recusa arquivos acima de 5 MB.\n- **Arquivo com nome que não bate com a válvula.** A importação casa polígono com válvula pelo código/nome — os que não encontram par aparecem em \"sem correspondência\" e não são aplicados.\n- **Esperar sobrescrever mapas existentes sem marcar a opção.** Por padrão a importação só preenche válvulas sem mapa; para trocar um mapa já existente, escolha \"sobrescrever\" (ou limpe os polígonos da fazenda antes de reimportar).\n- **Desenhar linha em vez de área.** Só é aceito polígono (GeoJSON Polygon/MultiPolygon); geometria inválida é recusada.\n\n## Antes e depois\nAntes: Cadastrar a válvula com seu código. Depois: Usar o mapa para conferir área, alertas e custo por válvula.\n\n## Roteiro do vídeo\n- Abrir Mapa da Fazenda e clicar numa válvula.\n- Desenhar o polígono e salvar; mostrar a área recalculada na mensagem.\n- Demonstrar a importação de um KML e o relatório de válvulas casadas.','operacao-agricola','mapear','implantacao','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(92,NULL,'montar-fenologia-da-variedade','Montar a curva fenológica de uma variedade','FAZER',NULL,'## Finalidade\nAqui você define as fases da variedade contando os dias desde a poda (dia 0), com o volume de irrigação e a calda de cada fase. É a curva que a fertirrigação (IF) e a defesa (DF) usam para saber em que fase a planta está.\n\n## Como fazer\n1. No catálogo de **Variedades**, clique no ícone de folha (Fenologia) da variedade.\n2. Clique em **+ Adicionar fase** e comece pela **poda (dia inicial 0)**.\n3. Dê o nome da fase, o dia inicial e o **dia final** (maior que o inicial), e o volume em mm/dia e a calda em L/ha, se tiver.\n4. Clique em **Salvar fase** — cada fase já fica gravada; o dia inicial sugerido da próxima é o dia final da anterior.\n5. Repita até cobrir o ciclo; a faixa verde **\"Fases contíguas desde a poda\"** confirma que a curva está fechada.\n\n## Erros comuns\n- **Não começar no dia 0.** A primeira fase precisa começar na poda (dia 0); se começar depois, aparece o aviso de contiguidade (mas não trava).\n- **Deixar lacuna ou sobreposição entre fases.** O sistema avisa \"há uma LACUNA\" ou \"há SOBREPOSIÇÃO\" quando o dia inicial de uma fase não bate com o dia final da anterior — use o dia sugerido para encaixar.\n- **Dia final menor ou igual ao inicial.** É bloqueado: o dia final tem de ser maior que o inicial.\n- **Confundir mm/dia com m³/ha.** A conversão é informativa: m³/ha/dia = mm/dia × 10; L/planta/dia depende da densidade e é calculado no uso, não aqui.\n\n## Antes e depois\nAntes: Cadastrar a variedade. Depois: Definir os períodos fenológicos da safra (datas reais que resolvem a fase automaticamente).\n\n## Roteiro do vídeo\n- Abrir a fenologia de uma variedade pelo ícone de folha.\n- Adicionar a fase Poda (0 → X), depois Brotação encaixando no dia final anterior.\n- Mostrar o aviso de lacuna e depois a faixa verde de contiguidade.','operacao-agricola','cadastrar','implantacao','intermediario',180,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(93,NULL,'planejar-atividade','Planejar uma atividade no talhão','FAZER',NULL,'## Finalidade\nA atividade planejada é o que organiza o trabalho por talhão e safra e gera automaticamente a Ordem de Serviço numerada. O realizado (área e custo) vem sozinho dos apontamentos que citam a atividade — aqui você define o previsto.\n\n## Como fazer\n1. Abra **Planejamento de Atividades** e clique em **+ Nova atividade**.\n2. Escreva a **descrição** e escolha o **talhão** — obrigatórios; selecione o tipo de atividade e a safra.\n3. Informe data planejada, responsável, área prevista e custo previsto (informativos).\n4. Adicione os **insumos planejados** (o custo médio atual é sugerido, editável) — eles alimentam a reserva orientativa do estoque.\n5. Clique em **Salvar** — a atividade nasce \"planejada\" e a OS-espelho é sincronizada.\n\n## Erros comuns\n- **Salvar sem descrição ou sem talhão.** Ambos são obrigatórios; sem eles a atividade não é criada.\n- **Esperar o realizado aparecer sem apontamento.** Área e custo realizados derivam dos apontamentos vinculados à atividade — se ninguém apontou citando ela, o realizado fica zerado.\n- **Achar que o custo previsto trava o gasto.** Ele é informativo: não bloqueia apontamentos; serve só para o comparativo previsto × realizado.\n- **Área ou custo previsto negativos.** São bloqueados — não podem ser menores que zero.\n\n## Antes e depois\nAntes: Cadastrar o tipo de atividade. Depois: Imprimir a Ordem de Serviço e, depois da execução, finalizar os apontamentos.\n\n## Roteiro do vídeo\n- Abrir Planejamento de Atividades e criar uma nova.\n- Preencher descrição, talhão, tipo e data; adicionar um insumo planejado.\n- Salvar e mostrar a OS sincronizada e a linha com previsto × realizado.','operacao-agricola','planejar','safra','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(94,NULL,'registrar-chuva-do-dia','Registrar a chuva do dia no pluviômetro','FAZER',NULL,'## Finalidade\nAqui você lança a leitura manual do pluviômetro: chuva do dia por fazenda (válvula opcional) e temperaturas mín/máx. É um registro simples — o VERO acumula o mês e o ano, sem derivar recomendações a partir dele.\n\n## Como fazer\n1. Abra **Clima e Chuvas** e clique em **+ Novo registro**.\n2. Escolha a **fazenda** e a **data** — obrigatórias; a válvula é opcional.\n3. Informe a **chuva em mm** e, se medir, as temperaturas mínima e máxima.\n4. Clique em **Salvar** — o registro entra no acumulado do mês e do ano.\n\n## Erros comuns\n- **Lançar dois registros para a mesma fazenda/válvula na mesma data.** O sistema recusa duplicidade e pede para editar o registro existente daquele dia.\n- **Válvula de outra fazenda.** A válvula escolhida precisa pertencer à fazenda selecionada; senão o lançamento é recusado.\n- **Temperatura mínima maior que a máxima.** É bloqueado — confira os valores antes de salvar.\n- **Esperar alertas automáticos de clima.** Este registro é só a leitura do pluviômetro; ele não gera recomendação nem trava aplicação (as faixas de referência do RT ficam em outro bloco e apenas avisam).\n\n## Antes e depois\nAntes: Ter a fazenda cadastrada. Depois: Acompanhar o acumulado mensal e anual de chuva.\n\n## Roteiro do vídeo\n- Abrir Clima e Chuvas e clicar em + Novo registro.\n- Escolher fazenda e data, digitar mm de chuva e temperaturas.\n- Salvar e mostrar os KPIs de mm do mês e acumulado do ano.','operacao-agricola','registrar','safra','iniciante',110,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(95,NULL,'registrar-colheita-no-campo','Registrar uma colheita pela visão do campo','FAZER',NULL,'## Finalidade\nEsta tela é o atalho de campo para registrar a colheita sem sair da Gestão Agrícola. O formulário é o mesmo do módulo Colheita e usa as mesmas regras: a classificação soma no máximo 100% e a colheita pode gerar entrada no estoque.\n\n## Como fazer\n1. Abra **Colheita (visão agrícola)** e clique em **+ Registrar colheita**.\n2. Preencha o formulário: válvula, safra, cultura/variedade, data e os quilos colhidos.\n3. Distribua a **classificação em percentuais** — a soma não pode passar de 100%.\n4. Clique em **Salvar** — o registro é gravado pelo handler do módulo Colheita e, se a cultura estiver configurada, entra no estoque.\n5. Volte à lista e confira o previsto × realizado e a barra de realização por válvula.\n\n## Erros comuns\n- **Somar mais de 100% na classificação.** A regra crítica bloqueia: a soma dos percentuais de classificação não pode ultrapassar 100%.\n- **Estranhar que a colheita não entrou no estoque.** A entrada só acontece se a cultura tiver produto e almoxarifado de colheita configurados; sem isso, registra a produção mas não movimenta estoque.\n- **Registrar sem previsão e achar que houve erro.** Sem previsão a barra de realização mostra \"sem previsão\" — é normal; o realizado continua contando.\n- **Procurar o registro completo aqui.** Esta é a visão de campo; o registro detalhado (com todas as classificações) vive no módulo Colheita, linkado no rodapé.\n\n## Antes e depois\nAntes: Cadastrar a válvula e a safra colhida. Depois: Conferir o custo realizado e a produtividade por talhão.\n\n## Roteiro do vídeo\n- Abrir Colheita (visão agrícola) e clicar em + Registrar colheita.\n- Preencher válvula, kg e classificação; mostrar o bloqueio ao passar de 100%.\n- Salvar e mostrar a barra de realização na lista.','operacao-agricola','registrar','safra','intermediario',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(96,NULL,'cadastrar-um-bem-patrimonial','Cadastrar um bem patrimonial para depreciar e controlar o patrimônio','FAZER',NULL,'## Finalidade\nO cadastro de ativos é o registro central do patrimônio da fazenda — terras, benfeitorias, equipamentos, veículos e máquinas. É o valor de aquisição e a vida útil informados aqui que alimentam a depreciação gerencial e o valor patrimonial do negócio.\n\n## Como fazer\n1. Abra **Ativos Patrimoniais** e clique em **Novo ativo**.\n2. Informe a **descrição** e a **categoria** (Terras, Benfeitorias, Equipamentos, Veículos ou Máquinas) — a categoria traz uma vida útil padrão.\n3. Preencha o **valor de aquisição** (maior que zero) e a **data de aquisição**.\n4. Ajuste, se quiser, a **vida útil em meses** e o **valor residual** (o que o bem valerá ao fim da vida útil).\n5. Se o ativo estiver ligado a uma máquina cadastrada, vincule a **máquina**. Clique em **Salvar**.\n\n## Erros comuns\n- **Deixar o valor de aquisição zerado ou negativo.** É obrigatório e maior que zero — sem ele a depreciação não tem base para calcular.\n- **Cadastrar terra esperando depreciação.** A categoria Terras tem vida útil zero e **não deprecia** de propósito. Isso é correto: terra não perde valor por uso.\n- **Excluir um ativo que já tem depreciação lançada.** O sistema não apaga: ele **inativa (dá baixa)** para preservar o histórico. Use a baixa em vez de tentar excluir.\n\n## Antes e depois\nAntes: ter a nota/valor de aquisição do bem e saber a categoria. Depois: gerar a depreciação gerencial por competência e acompanhar o valor patrimonial.\n\n## Roteiro do vídeo\n- Abrir Ativos Patrimoniais com a lista por categoria.\n- Narrar: \"Todo bem da fazenda começa aqui — é o valor de aquisição que vai virar depreciação.\"\n- Criar um equipamento com valor de aquisição, data e vida útil.\n- Salvar e mostrar o ativo na lista pronto para depreciar.','patrimonio','cadastrar','continuo','iniciante',160,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(97,NULL,'gerar-a-depreciacao-gerencial','Gerar a depreciação gerencial do mês para virar custo no custeio','FAZER',NULL,'## Finalidade\nA depreciação gerencial calcula, por competência, quanto cada bem produtivo perdeu de valor no mês — de forma linear: (aquisição − residual) ÷ vida útil. Gerar a competência é o que transforma esse desgaste em custo dentro do custeio, dando o custo real de produção. Não substitui a depreciação contábil/fiscal.\n\n## Como fazer\n1. Abra **Depreciação Gerencial**.\n2. Informe a **competência** (mês/ano) que quer processar.\n3. Clique em **Gerar** — o sistema calcula um lançamento por ativo produtivo elegível e emite o custo ao custeio.\n4. Confira o retorno: quantos foram **gerados**, quantos **pulados** e quantos ficaram sem cálculo por falta de vida útil.\n5. Repita a cada mês. Gerar de novo a mesma competência **não duplica** (é idempotente por ativo e competência).\n\n## Erros comuns\n- **Ativo sem vida útil e sem categoria com vida.** Ele fica de fora do cálculo (aparece como \"sem vida\"). Defina a vida útil no ativo ou na categoria para ele depreciar.\n- **Esperar que Terras depreciem.** Não depreciam por regra (vida útil zero). Categorias administrativas também não viram custo do custeio — só os bens produtivos.\n- **Gerar antes de cadastrar/ajustar os bens do mês.** O que não estava cadastrado (ou com data de aquisição posterior à competência) não entra. Cadastre os bens antes de gerar.\n\n## Antes e depois\nAntes: os bens cadastrados com valor de aquisição e vida útil. Depois: conferir a depreciação como custo no custeio e no valor patrimonial atualizado.\n\n## Roteiro do vídeo\n- Abrir Depreciação Gerencial.\n- Narrar: \"A depreciação é o desgaste do bem virando custo — mês a mês, sem duplicar.\"\n- Informar a competência e clicar em Gerar.\n- Mostrar o resumo de gerados/pulados/sem vida.\n- Cortar para o custeio com a depreciação lançada.','patrimonio','gerar','continuo','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(98,NULL,'cadastrar-regra-de-premiacao','Cadastrar uma regra de premiação para pagar produção acima da meta','FAZER',NULL,'## Finalidade\nA regra de premiação define quanto se paga por produção que passa da meta numa atividade (por planta, caixa, kg, hora, etc.). Ela não paga ninguém sozinha: serve para dimensionar a equipe e, na hora do apontamento, virar o valor de premiação que entra no bruto da folha.\n\n## Como fazer\n1. Abra **Premiação** e clique em **Nova regra**.\n2. Escolha a **atividade** e a **unidade** (planta, caixa, kg, ha, hora...) — os dois são obrigatórios.\n3. Escolha a **cultura** (ou deixe em branco para valer em todas).\n4. Informe a **meta** (produção esperada por pessoa) e o **valor acima da meta** — o que se paga por unidade excedente.\n5. Defina a **vigência** (início e, se quiser, fim). Clique em **Salvar**.\n\n## Erros comuns\n- **Cair no bloqueio de vigência sobreposta.** Não pode existir duas regras ativas para a mesma atividade e cultura no mesmo período. Encerre a vigência da regra anterior (ou inative-a) antes de criar a nova.\n- **Achar que cadastrar a regra já paga a premiação.** A regra é só o parâmetro. O valor só é gerado quando o trabalho é lançado no apontamento de campo, e entra no bruto da folha do mês.\n- **Inverter meta e valor.** Meta é quanto a pessoa precisa produzir; valor acima da meta é o preço do excedente. Trocar os dois distorce todo o cálculo.\n\n## Antes e depois\nAntes: ter a atividade e a cultura cadastradas. Depois: apontar a produção em campo e fechar a folha do mês com as premiações incluídas.\n\n## Roteiro do vídeo\n- Abrir Premiação com regras já cadastradas na lista.\n- Narrar: \"Esta tela não paga ninguém — ela define a regra. O pagamento nasce lá no apontamento.\"\n- Criar nova regra: atividade colheita, unidade caixa, meta e valor por caixa acima da meta.\n- Definir vigência e salvar.\n- Fechar reforçando que o valor cairá na folha via apontamento.','pessoas','cadastrar','safra','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(99,NULL,'cadastrar-um-colaborador','Cadastrar um colaborador para ele entrar na folha e nos apontamentos','FAZER',NULL,'## Finalidade\nO cadastro do colaborador é o que faz a pessoa existir para o sistema: sem ele não dá para montar equipe, apontar trabalho, calcular premiação nem gerar a folha. É aqui que você define o tipo de vínculo e o custo do trabalho dessa pessoa.\n\n## Como fazer\n1. Abra **Colaboradores** e clique em **Novo colaborador**.\n2. Informe o **nome** e o **tipo de vínculo** (CLT, diarista, etc.) — os dois são obrigatórios.\n3. Preencha função, documento e, se for CLT, o **salário mensal**.\n4. Deixe o **custo/hora** em branco: o sistema calcula sozinho a partir do salário mais os encargos vigentes. Só preencha se quiser forçar um valor manual.\n5. Clique em **Salvar** — a partir daqui a pessoa já aparece para equipes, apontamentos e folha.\n\n## Erros comuns\n- **Cadastrar o mesmo nome duas vezes.** O sistema barra homônimo ativo. Se são pessoas diferentes, use o documento para diferenciar antes de salvar.\n- **Esperar o custo/hora sem ter encargos configurados.** O cálculo automático depende da configuração de Encargos CLT vigente. Sem ela, o custo/hora fica zerado e o custo de mão de obra sai errado.\n- **Deixar o salário de um CLT em branco.** Sem salário mensal, esse colaborador não entra na geração da folha.\n\n## Antes e depois\nAntes: ter o vínculo e o valor combinado com a pessoa. Depois: montar a equipe e começar a apontar o trabalho dela.\n\n## Roteiro do vídeo\n- Abrir Colaboradores com a lista visível.\n- Narrar: \"Todo mundo que trabalha na fazenda começa aqui — é este cadastro que liga a pessoa à folha e aos apontamentos.\"\n- Clicar em Novo colaborador, preencher nome, vínculo CLT e salário.\n- Mostrar o custo/hora sendo preenchido sozinho depois de salvar.\n- Fechar mostrando a pessoa já disponível na lista.','pessoas','cadastrar','continuo','iniciante',150,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(100,NULL,'consultar-historico-do-colaborador','Consultar o histórico de um colaborador','CONSULTAR',NULL,'## Finalidade\nO histórico do colaborador reúne, em um só lugar, o que aquela pessoa acumulou na fazenda — trabalho apontado, produção e ligações com folha e premiação. É uma tela de leitura: serve para conferir e conversar, não para lançar nada.\n\n## Como consultar\n1. Abra **Histórico do colaborador**.\n2. Escolha o **colaborador** que quer analisar.\n3. Percorra o histórico apresentado para conferir o que a pessoa acumulou no período.\n\n## Antes e depois\nAntes: o colaborador já cadastrado e com apontamentos lançados. Depois: usar o que viu para ajustar equipe, premiação ou uma conversa de desempenho.\n\n## Roteiro do vídeo\n- Abrir Histórico do colaborador.\n- Narrar: \"Aqui você não lança nada — é a ficha de tudo que a pessoa já fez na fazenda.\"\n- Selecionar um colaborador e rolar o histórico.\n- Fechar apontando onde estão os números que ajudam na decisão.','pessoas','consultar','continuo','iniciante',80,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(101,NULL,'fechar-a-folha-do-mes','Fechar a folha do mês para o custo de mão de obra entrar no custeio','FAZER',NULL,'## Finalidade\nA folha calcula salário, encargos e descontos dos colaboradores CLT de uma competência. Fechar a folha é o passo que transforma salário + encargos em custo de mão de obra dentro do custeio — enquanto ela fica aberta, esse custo ainda não conta para a safra.\n\n## Como fazer\n1. Abra **Folha** e crie o **período** informando a competência (mês/ano).\n2. Clique em **Gerar lançamentos** — o sistema calcula um lançamento por colaborador CLT com salário, encargos, descontos e as premiações do mês já somadas ao bruto.\n3. Confira os valores por colaborador na lista do período.\n4. Clique em **Fechar período** — este é o passo que **emite o custo de salário + encargos ao custeio**.\n5. Se precisar corrigir depois, use **Reabrir**: o custeio da folha é removido e será reemitido no próximo fechamento.\n\n## Erros comuns\n- **Gerar sem encargos vigentes.** O sistema barra a geração se não houver configuração de Encargos CLT válida para a competência. Cadastre em Pessoas → Encargos CLT antes.\n- **Gerar antes de lançar as premiações do mês.** As premiações entram no bruto no momento da geração. Se apontar depois, gere de novo para incluí-las (regerar recalcula o período aberto).\n- **Tentar excluir um período fechado.** Não é permitido — reabra o período primeiro. E lembre: só entram na folha colaboradores CLT com salário mensal informado.\n\n## Antes e depois\nAntes: cadastrar colaboradores CLT com salário e configurar os encargos vigentes. Depois: conferir o custo de mão de obra no custeio da safra.\n\n## Roteiro do vídeo\n- Abrir Folha e criar o período da competência atual.\n- Narrar: \"A folha vira custo da fazenda só quando a gente fecha o período.\"\n- Gerar os lançamentos e percorrer bruto, encargos e líquido de um colaborador.\n- Destacar o botão Fechar período antes de clicar; clicar.\n- Cortar para o custeio mostrando o custo de mão de obra lançado.','pessoas','fechar','continuo','intermediario',180,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(102,NULL,'montar-uma-equipe','Montar uma equipe para agilizar o apontamento em campo','FAZER',NULL,'## Finalidade\nA equipe agrupa colaboradores que trabalham juntos. Com ela montada, o apontamento de campo lança a turma inteira de uma vez, em vez de escolher pessoa por pessoa — menos erro e mais rapidez no dia a dia.\n\n## Como fazer\n1. Abra **Equipes** e clique em **Nova equipe**.\n2. Dê um **nome** à equipe (obrigatório) e, se fizer sentido, escolha a **fazenda** a que ela pertence.\n3. Marque os **membros** entre os colaboradores já cadastrados.\n4. Clique em **Salvar** — a equipe fica pronta para ser usada no apontamento.\n\n## Erros comuns\n- **Procurar uma pessoa que não aparece.** Só entra na equipe quem já é colaborador cadastrado. Cadastre a pessoa antes de montar a turma.\n- **Salvar equipe sem membro.** A equipe existe, mas não adianta nada no apontamento — sempre marque quem faz parte.\n- **Excluir para \"limpar\" a equipe.** A exclusão é uma inativação; os membros ficam guardados para reativação. Para trocar quem participa, edite a lista de membros em vez de excluir.\n\n## Antes e depois\nAntes: cadastrar os colaboradores que vão compor a turma. Depois: usar a equipe no apontamento de campo para lançar todo mundo de uma vez.\n\n## Roteiro do vídeo\n- Abrir Equipes com uma equipe já existente na lista.\n- Narrar: \"A equipe é um atalho: junte quem trabalha lado a lado e aponte a turma inteira de uma vez.\"\n- Criar nova equipe, nomear, escolher fazenda e marcar três membros.\n- Salvar e mostrar a contagem de membros na lista.','pessoas','cadastrar','continuo','iniciante',130,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(103,NULL,'criar-safra-e-vincular-valvulas','Criar uma safra e vincular as válvulas com cultura e área','FAZER',NULL,'## Finalidade\nA safra é o ciclo produtivo, e o vínculo safra × válvula é a amarração central do sistema: custeio, colheita e dashboards todos dependem dele. Ao criar a safra você já escolhe as válvulas; a cultura vem da variedade de cada válvula, junto com a área plantada e a produtividade planejada. Sem esse vínculo, nada da safra tem onde se apoiar.\n\n## Como fazer\n1. Abra **Safras / Ciclos** e clique em **+ Nova safra**.\n2. Informe a **identificação** (única) e a **data de início** — as duas são obrigatórias.\n3. Marque as **válvulas** que entram na safra já na criação — o sistema cria os vínculos com a cultura e a área de cada uma.\n4. Ajuste o status (planejada, ativa ou encerrada) e, se souber, o fim previsto.\n5. Clique em **Salvar** — a safra nasce com as válvulas vinculadas, prontas para o custeio e a colheita.\n\n## Erros comuns\n- **Vincular válvula sem variedade.** A cultura vem da variedade da válvula; sem variedade a válvula é ignorada no vínculo, com aviso. Defina a variedade da válvula antes de vinculá-la.\n- **Repetir a identificação de uma safra.** A identificação não pode se repetir no tenant. Se já existir, o sistema avisa e não grava.\n- **Achar que precisa cadastrar as válvulas depois.** Elas entram já na criação. Se faltar alguma, use o painel de vincular/desvincular da safra para ajustar depois.\n\n## Antes e depois\nAntes: Ter as válvulas cadastradas com suas variedades. Depois: Abrir a safra e confirmar a poda de cada válvula (o dia 0 da fenologia).\n\n## Roteiro do vídeo\n- Abrir Safras / Ciclos com a lista de safras.\n- Clicar em + Nova safra e preencher identificação e data de início.\n- Marcar as válvulas e narrar: \"A cultura e a área vêm sozinhas, da variedade da válvula.\"\n- Destacar **Salvar**; clicar.\n- Abrir a safra criada e mostrar as válvulas vinculadas.','safra','criar','safra','intermediario',170,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(104,NULL,'rolar-valvulas-de-uma-safra-anterior','Rolar as válvulas de uma safra anterior para a nova','FAZER',NULL,'## Finalidade\nRolar uma safra copia os vínculos de válvulas de uma safra anterior para a nova, de uma vez. Como a lavoura perene repete quase as mesmas válvulas a cada ciclo, a rolagem poupa o trabalho de vincular tudo à mão — traz válvula, cultura, área e a meta de produtividade prontas para revisão.\n\n## Como fazer\n1. Abra **Safras / Ciclos** e entre na safra de destino (a nova, que vai receber as válvulas).\n2. No painel **Rolar safra**, escolha a **safra de origem** — de onde os vínculos serão copiados.\n3. Clique em rolar — este é o passo que copia os vínculos de válvulas ativas para a safra atual.\n4. Leia o resultado: quantos vínculos foram copiados e quantos já existiam e foram mantidos.\n5. **Revise as áreas e as metas de produtividade** de cada válvula, pois vêm da safra antiga.\n\n## Erros comuns\n- **Escolher a mesma safra como origem e destino.** O sistema recusa: a origem tem de ser diferente da atual. Selecione a safra anterior de verdade.\n- **Esperar que a rolagem sobrescreva o que já existe.** Vínculos que já estão na safra de destino são mantidos, não duplicados. A rolagem só acrescenta o que falta.\n- **Deixar as áreas e metas como vieram.** Elas são copiadas da safra antiga e podem ter mudado. Revise a área plantada e a produtividade planejada de cada válvula depois de rolar.\n\n## Antes e depois\nAntes: Criar a nova safra. Depois: Abrir a safra e confirmar a poda de cada válvula.\n\n## Roteiro do vídeo\n- Abrir Safras / Ciclos e entrar numa safra nova, ainda sem válvulas.\n- Mostrar o painel Rolar safra e escolher a safra de origem.\n- Clicar em rolar e ler o resultado: copiados e mantidos.\n- Narrar: \"Veio tudo da safra passada — agora é revisar área e meta.\"\n- Abrir uma válvula e ajustar a produtividade planejada.','safra','rolar','safra','intermediario',140,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:33:09','2026-07-26 18:33:09'),(105,NULL,'consultar-o-historico-de-compras','Consultar o histórico de compras','CONSULTAR',NULL,'## Finalidade\nO Histórico de Compras é a leitura consolidada dos recebimentos já confirmados, item por item. Serve para responder rápido \"quanto compramos deste produto?\", \"quanto pagamos por unidade da última vez?\" e \"quanto esse fornecedor entregou no período?\" — com filtros de fornecedor, produto e datas, mais os totais.\n\n## Como fazer\n1. Abra **Histórico de Compras**.\n2. Filtre por **fornecedor**, **produto** e **período** conforme a pergunta.\n3. Leia os itens recebidos e o **total** do filtro.\n4. Use o resultado para negociar preço na próxima cotação ou conferir a ficha do fornecedor.\n\n## Antes e depois\nAntes: Ter compras recebidas e confirmadas nos Recebimentos. Depois: Levar o histórico de preços para a próxima cotação de fornecedores.\n\n## Roteiro do vídeo\n- Abrir Histórico de Compras.\n- Filtrar um produto num período e ler os itens e o total.\n- Trocar o filtro para um fornecedor e comparar.\n- Narrar como usar o preço passado para negociar a próxima compra.','compras','consultar','continuo','iniciante',110,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:34:27','2026-07-26 18:34:27'),(106,NULL,'cadastrar-implemento','Cadastrar um implemento agrícola','FAZER',NULL,'## Finalidade\nO implemento é o que se acopla ao trator: grade, pulverizador, roçadeira, subsolador. Cadastrá-lo organiza a frota, permite dizer a qual máquina ele está acoplado e deixa o inventário de equipamentos completo para as operações e o controle patrimonial.\n\n## Como fazer\n1. Na tela de **Implementos**, clique em **+ Novo implemento**.\n2. Informe o **nome** — é o campo obrigatório.\n3. Preencha o **tipo** e escolha a **fazenda**.\n4. Se ele fica acoplado a uma máquina, selecione a **máquina** correspondente.\n5. Clique em **Salvar**. O implemento entra na lista como ativo.\n\n## Erros comuns\n- **Salvar sem nome.** O nome é obrigatório — sem ele o cadastro é recusado.\n- **Não indicar a máquina acoplada.** É opcional, mas sem esse vínculo você perde a visão de qual trator carrega qual implemento.\n- **Confundir implemento com máquina.** Implemento não tem horímetro nem abastecimento próprios; se for equipamento motorizado, cadastre em Máquinas.\n\n## Antes e depois\nAntes: Ter a máquina de tração cadastrada. Depois: Usar o implemento nas operações agrícolas e no controle da frota.\n\n## Roteiro do vídeo\n- Abrir Implementos e clicar em + Novo implemento.\n- Preencher nome, tipo e fazenda; vincular a uma máquina.\n- Salvar e mostrar o implemento na lista com o vínculo.','maquinas','cadastrar','continuo','iniciante',110,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:34:28','2026-07-26 18:34:28'),(107,NULL,'cadastrar-uma-benfeitoria','Cadastrar uma benfeitoria para incorporá-la ao patrimônio','FAZER',NULL,'## Finalidade\nBenfeitorias são as construções e melhorias fixas da fazenda — galpões, cercas, sistemas de irrigação, casas. Cadastrá-las incorpora esse valor ao patrimônio e faz elas entrarem na depreciação gerencial com a vida útil padrão da categoria (mais longa que a de máquinas).\n\n## Como fazer\n1. Abra **Benfeitorias** — esta tela já traz a categoria Benfeitorias fixada.\n2. Clique em **Nova benfeitoria** e informe a **descrição**.\n3. Preencha o **valor de aquisição** (maior que zero) e a **data de aquisição**.\n4. Ajuste a **vida útil** e o **valor residual** se o padrão não servir.\n5. Clique em **Salvar** — a benfeitoria entra no patrimônio e passa a depreciar.\n\n## Erros comuns\n- **Deixar o valor de aquisição em branco.** É obrigatório e maior que zero; sem ele não há base para depreciar.\n- **Colocar valor residual negativo.** O residual nunca é negativo — é o quanto o bem ainda valerá ao fim da vida útil.\n- **Excluir uma benfeitoria já depreciada.** O sistema inativa (dá baixa) em vez de apagar, para não perder o histórico das depreciações lançadas.\n\n## Antes e depois\nAntes: ter o valor e a data da construção/melhoria. Depois: gerar a depreciação gerencial da competência para a benfeitoria virar custo.\n\n## Roteiro do vídeo\n- Abrir Benfeitorias com a categoria já fixada.\n- Narrar: \"Galpão, cerca, irrigação — tudo que é melhoria fixa entra no patrimônio por aqui.\"\n- Cadastrar uma benfeitoria com valor e data de aquisição.\n- Salvar e mostrar a vida útil padrão da categoria.','patrimonio','cadastrar','continuo','iniciante',140,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:34:28','2026-07-26 18:34:28'),(108,NULL,'consultar-onde-esta-cada-bem','Consultar onde está cada bem por fazenda','CONSULTAR',NULL,'## Finalidade\nA Localização de Ativos mostra onde está cada bem, agrupado por fazenda: máquinas, veículos, implementos e ativos patrimoniais vinculados. É uma tela de leitura, útil para inventário e para saber rapidamente o que está em cada unidade.\n\n## Como consultar\n1. Abra **Localização de Ativos**.\n2. Percorra os blocos por **fazenda** — cada bem aparece com sua classe (Máquina, Veículo, Implemento ou Ativo) e um detalhe.\n3. Verifique o bloco **Sem localização definida** ao final: são bens sem fazenda vinculada.\n4. Para mudar a localização de um bem, edite o cadastro do bem (máquina, veículo ou implemento) e ajuste a fazenda — esta tela apenas reflete o que está lá.\n\n## Antes e depois\nAntes: os bens cadastrados e vinculados às suas fazendas. Depois: usar o inventário para conferência física ou para corrigir a fazenda de um bem no cadastro.\n\n## Roteiro do vídeo\n- Abrir Localização de Ativos.\n- Narrar: \"Aqui você não move nada — é o retrato de onde cada bem está, fazenda por fazenda.\"\n- Percorrer uma fazenda e mostrar máquinas, veículos e implementos.\n- Apontar o bloco Sem localização definida e explicar como corrigir no cadastro do bem.','patrimonio','consultar','continuo','iniciante',90,'publicado','1.0','1.3',NULL,'conteudo@example.com','2026-07-26','2027-01-24',1,NULL,NULL,'2026-07-26 18:34:28','2026-07-26 18:34:28');
