/*!40000 ALTER TABLE `uni_checklist_item` DISABLE KEYS */;
INSERT INTO `uni_checklist_item` VALUES (1,NULL,'chk-fazenda-talhoes','Cadastrar fazenda e talhões','Cadastre a fazenda e desenhe os talhões (as válvulas) no mapa. É a base de tudo: sem talhão, não há onde apontar, colher ou custear.',NULL,'SELECT 1 FROM agro_talhoes WHERE tenant_id = :tenant AND ativo = 1 LIMIT 1','gestor',1,1,'2026-07-26 17:16:40','2026-07-26 17:16:40'),(2,NULL,'chk-variedade-valvula','Definir a variedade em cada válvula','Informe qual variedade está plantada em cada talhão. A variedade guia a fenologia (o dia 0 da poda) e as recomendações — sem ela, a safra não calcula direito.',NULL,'SELECT 1 FROM agro_talhoes WHERE tenant_id = :tenant AND ativo = 1 AND variedade_id IS NOT NULL LIMIT 1','gestor',2,1,'2026-07-26 17:16:40','2026-07-26 17:16:40'),(3,NULL,'chk-abrir-safra','Abrir a safra','Abra a safra e confirme a poda (o dia 0). É o que liga o relógio da fenologia e permite emitir ordens, apontar e acumular custo no ciclo.','abrir-safra-e-confirmar-poda','SELECT 1 FROM agro_safras WHERE tenant_id = :tenant AND status IN (\'ativa\',\'encerrada\') LIMIT 1','gestor',3,1,'2026-07-26 17:16:40','2026-07-26 17:16:40'),(4,NULL,'chk-saldo-estoque','Fazer o saldo inicial do estoque','Lance o saldo inicial dos produtos no almoxarifado. Sem saldo, as aplicações não têm de onde baixar insumo e o custo dos produtos não aparece.','fazer-saldo-inicial','SELECT 1 FROM estoque_saldos WHERE tenant_id = :tenant AND quantidade > 0 LIMIT 1','almoxarifado',4,1,'2026-07-26 17:16:40','2026-07-26 17:16:40'),(5,NULL,'chk-colaboradores','Cadastrar colaboradores','Cadastre os operadores/colaboradores (com custo por hora). Sem eles não há quem executar a ordem de serviço nem como custear a mão de obra.',NULL,'SELECT 1 FROM agro_operadores WHERE tenant_id = :tenant AND ativo = 1 LIMIT 1','gestor',5,1,'2026-07-26 17:16:40','2026-07-26 17:16:40'),(6,NULL,'chk-primeira-os','Emitir a primeira Ordem de Serviço','Emita a primeira Ordem de Serviço para o campo executar. É o comando que sai do escritório e vira apontamento no talhão.','emitir-ordem-de-servico','SELECT 1 FROM agro_ordens_servico WHERE tenant_id = :tenant LIMIT 1','encarregado',6,1,'2026-07-26 17:16:40','2026-07-26 17:16:40'),(7,NULL,'chk-primeiro-apontamento','Fazer e finalizar o primeiro apontamento','Faça e finalize o primeiro apontamento (status validado). É quando o trabalho no campo vira custo real na safra — o ciclo fecha aqui.','finalizar-apontamento','SELECT 1 FROM agro_apontamentos WHERE tenant_id = :tenant AND status = \'validado\' LIMIT 1','encarregado',7,1,'2026-07-26 17:16:40','2026-07-26 17:16:40');
/*!40000 ALTER TABLE `uni_checklist_item` ENABLE KEYS */;
UNLOCK TABLES;

