/*!40000 ALTER TABLE `uni_tarefa_pratica` DISABLE KEYS */;
INSERT INTO `uni_tarefa_pratica` VALUES (1,2,'pratica-finalizar-apontamento','Finalize um apontamento na Fazenda Escola','Vá até os apontamentos e **finalize (valide)** um apontamento da fazenda.\n\nSó depois de validado é que o custo dele entra na conta da safra. Quando terminar, volte aqui e clique em **Verificar**.','SELECT 1 FROM agro_apontamentos WHERE tenant_id = :tenant AND status = \'validado\' LIMIT 1',NULL,'Boa! Você tem um apontamento validado — o custo dele já pode entrar na safra.','Ainda não achei apontamento validado. Abra um apontamento, finalize/valide e verifique de novo.',10,1,'2026-07-26 16:56:13','2026-07-26 16:56:13'),(2,6,'pratica-abrir-safra','Abra uma safra','Abra uma **safra** na fazenda — é ela que amarra talhões, custos e colheita do ciclo.\n\nDepois de criar a safra, volte aqui e clique em **Verificar**.','SELECT 1 FROM agro_safras WHERE tenant_id = :tenant LIMIT 1',NULL,'Safra aberta! Agora o ciclo tem onde pendurar talhões, custos e colheita.','Ainda não encontrei nenhuma safra da fazenda. Abra a safra na tela de abertura e verifique de novo.',20,1,'2026-07-26 16:56:13','2026-07-26 16:56:13'),(3,9,'pratica-dar-entrada-estoque','Registre uma entrada de estoque','Dê **entrada** de um produto no estoque — como quando chega a nota do fornecedor.\n\nÉ a entrada que forma o saldo e o custo dos insumos. Feito isso, volte aqui e clique em **Verificar**.','SELECT 1 FROM estoque_movimentacoes WHERE tenant_id = :tenant AND tipo = \'entrada\' LIMIT 1',NULL,'Entrada registrada! O saldo e o custo do insumo já estão no estoque.','Ainda não vi nenhuma entrada de estoque da fazenda. Registre a entrada da nota e verifique de novo.',30,1,'2026-07-26 16:56:13','2026-07-26 16:56:13');
/*!40000 ALTER TABLE `uni_tarefa_pratica` ENABLE KEYS */;
