INSERT INTO `uni_trilha` VALUES (1,NULL,'operador','Trilha do Operador','Para quem executa as tarefas no campo e registra o que foi feito.','- Você não precisa abrir a safra nem configurar permissões\n- Você não precisa mexer no financeiro nem nos custos\n- Você não precisa dar entrada de nota no estoque',14,1,1,'2026-07-26 16:54:55','2026-07-26 16:54:55'),(2,NULL,'mao_de_obra','Trilha do Mão de obra','Para quem trabalha na lavoura e finaliza os apontamentos das tarefas.','- Você não precisa emitir ordens de serviço\n- Você não precisa mexer no estoque nem no financeiro',8,2,1,'2026-07-26 16:54:55','2026-07-26 16:54:55'),(3,NULL,'monitor','Trilha do Monitor','Para quem faz o monitoramento de pragas e doenças (MIP) no campo.','- Você não precisa emitir ordens de serviço nem fechar a safra\n- Você não precisa mexer no estoque nem no financeiro',3,3,1,'2026-07-26 16:54:55','2026-07-26 16:54:55'),(4,NULL,'encarregado','Trilha do Encarregado','Para quem lidera a turma no campo e emite as ordens de serviço.','- Você não precisa fechar títulos no financeiro\n- Você não precisa configurar o sistema nem as permissões',19,4,1,'2026-07-26 16:54:55','2026-07-26 16:54:55'),(5,NULL,'almoxarifado','Trilha do Almoxarifado','Para quem controla o estoque e recebe as compras da fazenda.','- Você não precisa mexer na operação agrícola do campo\n- Você não precisa baixar títulos no financeiro',8,5,1,'2026-07-26 16:54:55','2026-07-26 16:54:55'),(6,NULL,'financeiro','Trilha do Financeiro','Para quem cuida do dinheiro: títulos, baixas e custo da safra.','- Você não precisa emitir ordens de serviço nem apontar tarefas no campo\n- Você não precisa dar entrada de nota no estoque',5,6,1,'2026-07-26 16:54:55','2026-07-26 16:54:55'),(7,NULL,'gestor','Trilha do Gestor','Para quem coordena a operação, os custos e as compras da fazenda.','- Você não precisa apontar tarefas no campo no dia a dia\n- Você não precisa fazer o saldo inicial do estoque manualmente',21,7,1,'2026-07-26 16:54:55','2026-07-26 16:54:55'),(8,NULL,'rt_gerente','Trilha do RT/Gerente','Para o responsável técnico / gerente que planeja a safra e acompanha os custos.','- Você não precisa dar entrada de nota no estoque\n- Você não precisa baixar títulos no financeiro',11,8,1,'2026-07-26 16:54:55','2026-07-26 16:54:55');
